insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-1', 'Focused risk assessment', 'Take a focused risk assessment of a 26-year-old woman who has been feeling ''very low'' since a breakup.', 420, '[{"item":"Asked about suicidal ideation in clear language","weight":2},{"item":"Explored plan, means, intent","weight":2},{"item":"Asked about prior attempts","weight":1},{"item":"Asked about protective factors","weight":1},{"item":"Asked about alcohol/substance use","weight":1},{"item":"Made a clear safety plan / referral","weight":2},{"item":"Maintained a non-judgemental stance","weight":1}]'::jsonb, '{"label":"Global risk-assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-2', 'Explain an SSRI to a reluctant patient', 'Explain what an SSRI is, what to expect, and address a 40-year-old man''s fears that ''antidepressants are addictive''.', 420, '[{"item":"Explained mechanism in plain language","weight":1},{"item":"Set realistic timeline (2-4 weeks)","weight":1},{"item":"Addressed the ''addiction'' myth directly","weight":2},{"item":"Discussed common side effects + what to do","weight":1},{"item":"Discussed discontinuation (not abrupt)","weight":1},{"item":"Checked understanding","weight":1},{"item":"Shared decision-making (not lecturing)","weight":2}]'::jsonb, '{"label":"Global psychoeducation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-3', 'Break the news you''re referring them', 'Break the news to a 30-year-old man that you''re referring him to a psychiatrist. He''s worried it means he''s ''mad''.', 420, '[{"item":"Used a warning shot (''I have something important to share'')","weight":1},{"item":"Normalised referral without minimising","weight":2},{"item":"Addressed the stigma directly","weight":1},{"item":"Explained what will happen at the referral","weight":1},{"item":"Checked emotional response","weight":1},{"item":"Offered support / follow-up","weight":1},{"item":"Paced the information","weight":1}]'::jsonb, '{"label":"Global breaking-bad-news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-4', 'Assess capacity', 'A 72-year-old man with dementia wants to discharge himself against advice to ''check on the shop''. Assess his capacity to make this decision.', 420, '[{"item":"Explained the purpose of the capacity assessment","weight":1},{"item":"Assessed ability to understand the relevant information","weight":2},{"item":"Assessed ability to retain it","weight":1},{"item":"Assessed ability to weigh it up","weight":2},{"item":"Assessed ability to communicate a decision","weight":1},{"item":"Did not equate capacity with agreement","weight":2},{"item":"Documented the assessment","weight":1}]'::jsonb, '{"label":"Global capacity-assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-5', 'An angry relative', 'A patient''s brother is furious in the waiting room: ''You people have made him worse!'' Manage the anger without being defensive or dismissive.', 420, '[{"item":"Acknowledged the emotion before the content","weight":2},{"item":"Did not get defensive or argue","weight":2},{"item":"Reflected what the relative said they observed","weight":1},{"item":"Offered a concrete next step (review, second opinion, complaint route)","weight":2},{"item":"Set safe boundaries on behaviour without escalating","weight":1},{"item":"Followed up on what can actually change","weight":1}]'::jsonb, '{"label":"Global anger-management competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-6', 'Non-adherence conversation', 'A 38-year-old woman on an antidepressant stopped taking it two weeks ago because of weight gain. She says she''s ''never going back on it''. Address this without coercion.', 420, '[{"item":"Asked about the reason before assuming the cause","weight":2},{"item":"Validated the side-effect concern","weight":1},{"item":"Explored the trade-off honestly (benefit vs side effect)","weight":1},{"item":"Did not lecture or guilt-trip","weight":2},{"item":"Offered options: dose timing, prescriber review, alternatives","weight":1},{"item":"Closed with a concrete plan she owns","weight":1},{"item":"Explained discontinuation risk of stopping abruptly","weight":1}]'::jsonb, '{"label":"Global adherence-conversation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-7', 'First psychotic episode: the family', 'A 19-year-old was hospitalised with a first psychotic episode. His parents are terrified he''s ''ruined for life''. Explain what a first episode means, honestly.', 420, '[{"item":"Named the diagnosis clearly without jargon","weight":1},{"item":"Explained that first-episode outcomes vary: honest hope, not false promise","weight":2},{"item":"Addressed the stigma fear directly (''mad'', ''ruined'')","weight":2},{"item":"Explained the treatment timeline (weeks-months, not days)","weight":1},{"item":"Involved the family in the care plan","weight":1},{"item":"Checked their understanding and emotion","weight":1},{"item":"Offered support resources","weight":1}]'::jsonb, '{"label":"Global first-episode psychoeducation","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-8', 'Adolescent alone', 'A 15-year-old is brought by parents who want ''the full report'' on their daughter. She won''t speak while they''re in the room. Gain her trust and negotiate the disclosure question.', 420, '[{"item":"Asked the parents to step out at some point","weight":2},{"item":"Engaged the adolescent directly, not through the parents","weight":2},{"item":"Named the confidentiality rules clearly (safety exceptions)","weight":2},{"item":"Did not promise blanket secrecy","weight":1},{"item":"Explored what she wants the parents to know","weight":1},{"item":"Set up a feedback structure that protects her voice","weight":1}]'::jsonb, '{"label":"Global adolescent-engagement competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-9', 'Grief, not depression', 'A 58-year-old man, four weeks after his wife''s death, is eating little and sleeping badly. His daughter fears ''he''s depressed''. Assess what this is before labelling it.', 420, '[{"item":"Did not jump to the depression label","weight":2},{"item":"Explored the grief timeline and function honestly","weight":2},{"item":"Distinguished normal grief from complicated grief/depression","weight":2},{"item":"Asked about risk without pathologising","weight":1},{"item":"Normalised the family''s worry while correcting the frame","weight":1},{"item":"Offered follow-up if things don''t shift","weight":1}]'::jsonb, '{"label":"Global grief-assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-10', 'Disclosure of abuse', 'A 26-year-old woman, in her third session, reveals her partner ''gets physical'' when angry. She says she''s not ready to leave. Respond safely.', 420, '[{"item":"Believed and validated the disclosure","weight":2},{"item":"Assessed immediate danger (weapon, threats, children)","weight":2},{"item":"Did not pressure her to leave","weight":2},{"item":"Explored safety planning step by step","weight":1},{"item":"Offered concrete resources (helplines, shelters) without pushing","weight":1},{"item":"Explained the confidentiality limits (risk to life)","weight":1}]'::jsonb, '{"label":"Global abuse-disclosure competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-11', 'Side-effect complaint', 'A 29-year-old on an antipsychotic reports ''my hands won''t stay still'': pacing, restless legs, unbearable urge to move. The treating doctor said ''it''s just anxiety''. Take the complaint seriously.', 420, '[{"item":"Recognised akathisia as a possibility (drug-induced)","weight":2},{"item":"Did not dismiss it as anxiety","weight":2},{"item":"Took a medication timeline (started when?)","weight":1},{"item":"Explained the concern and its management to the prescriber","weight":2},{"item":"Did not stop or change the medication himself","weight":1},{"item":"Reassured with action, not platitudes","weight":1}]'::jsonb, '{"label":"Global akathisia-recognition competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-12', 'Telehealth boundary', 'A client calls you on video from their car at 9pm, mid-panic, and wants ''a full session now''. They have done this twice this month. Establish the boundary safely.', 420, '[{"item":"Stabilised the immediate panic with grounding (not full therapy)","weight":2},{"item":"Did not run the full session on demand","weight":2},{"item":"Named the pattern without shaming","weight":1},{"item":"Set a clear on-demand vs scheduled boundary","weight":1},{"item":"Gave a concrete crisis plan for outside-session moments","weight":2},{"item":"Scheduled a proper session to process the pattern","weight":1}]'::jsonb, '{"label":"Global telehealth-boundary competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-13', 'History: low mood in a teacher', 'Mrs Rekha Pillai, 45, a school teacher, says she has ''no interest in anything''. Take a focused history to establish whether she has a depressive episode. You do not need to examine her.', 420, '[{"item":"Introduced self and explained the purpose of the interview","weight":1},{"item":"Asked about mood, interest and energy (core symptoms)","weight":2},{"item":"Asked about sleep, appetite, concentration, guilt and slowing","weight":2},{"item":"Established duration and impact on work and home","weight":1},{"item":"Asked about suicide clearly","weight":2},{"item":"Screened for past high or elated periods","weight":1},{"item":"Asked about alcohol, medical illness and family history","weight":1},{"item":"Summarised back to the patient","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-14', 'History: first episode of unusual experiences', 'Rahul, 22, was brought by his parents because he ''talks to himself''. Take a history of his current experiences and screen for the key psychotic symptoms.', 420, '[{"item":"Built rapport and used open questions first","weight":1},{"item":"Asked about hearing voices or sounds others cannot hear, without leading","weight":2},{"item":"Clarified voice content, number, person (second or third) and running commentary","weight":2},{"item":"Explored beliefs about the device and thought reading without arguing","weight":2},{"item":"Asked about substance use including cannabis","weight":1},{"item":"Asked about mood and sleep","weight":1},{"item":"Asked about risk to self and others","weight":2}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-15', 'History: is this a high?', 'Pooja''s husband says she has been ''unstoppable'' for a week. Take a history from Pooja, 30, to assess for a manic episode.', 420, '[{"item":"Asked about mood and how it differs from usual","weight":1},{"item":"Asked about sleep need and energy","weight":2},{"item":"Asked about racing thoughts, speech and plans","weight":1},{"item":"Asked about spending, risky behaviour and sexual disinhibition sensitively","weight":2},{"item":"Asked about past low or high episodes","weight":1},{"item":"Asked about substances and medicines","weight":1},{"item":"Asked about risk and insight","weight":2}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-16', 'History: the morning drink', 'Mr Joseph, 48, attends with stomach pain. His GP suspects alcohol use. Take an alcohol history, including whether he is dependent.', 420, '[{"item":"Asked about type, amount and frequency (a typical day)","weight":2},{"item":"Calculated or estimated units or standard drinks","weight":1},{"item":"Asked about tolerance and withdrawal symptoms","weight":2},{"item":"Asked about morning drinking and failed attempts to cut down","weight":1},{"item":"Asked about consequences: health, work, family, legal","weight":1},{"item":"Asked about past withdrawal seizures or confusion","weight":1},{"item":"Used a non-judgemental tone","weight":1},{"item":"Asked about suicide and mood","weight":1}]'::jsonb, '{"label":"Global substance history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-17', 'History: the stuck thoughts', 'Ananya, 25, says she ''cannot stop washing''. Take a history to assess for obsessive-compulsive disorder.', 420, '[{"item":"Asked about the content of intrusive thoughts","weight":2},{"item":"Asked about compulsions and time spent","weight":1},{"item":"Assessed insight (does she see them as excessive)","weight":1},{"item":"Asked about other unwanted thoughts (harm, sexual, religious) sensitively","weight":2},{"item":"Distinguished intrusive harm thoughts from intent","weight":2},{"item":"Asked about impact and avoidance","weight":1},{"item":"Asked about mood and family accommodation","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-18', 'History: after the accident', 'Mr Khan, 35, was in a bus accident three months ago. He is not sleeping. Take a history to assess for post-traumatic stress disorder.', 420, '[{"item":"Asked about the event at his pace without forcing detail","weight":2},{"item":"Asked about re-experiencing: nightmares and flashbacks","weight":1},{"item":"Asked about avoidance","weight":1},{"item":"Asked about alertness, startle and sleep","weight":1},{"item":"Asked about mood, guilt and numbness","weight":1},{"item":"Asked about alcohol and coping","weight":1},{"item":"Asked about suicide clearly","weight":2},{"item":"Checked impact on work and family","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-19', 'Collateral history: memory problems', 'Speak to the daughter of Mr Rao, 76, who is worried about his memory. Take a collateral history.', 420, '[{"item":"Explained the purpose and obtained the patient''s agreement or noted capacity issues","weight":1},{"item":"Established onset, course (gradual or stepwise) and duration","weight":2},{"item":"Asked about memory, orientation, language and functioning","weight":1},{"item":"Asked about safety: gas, wandering, driving, finances","weight":2},{"item":"Asked about mood, hallucinations and behaviour change","weight":1},{"item":"Asked about medical history and medicines","weight":1},{"item":"Asked about carer strain and support","weight":1}]'::jsonb, '{"label":"Global collateral history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-20', 'History: a child who won''t sit still', 'Mrs Sharma''s son Aryan, 7, has been sent home from school for ''disruptive behaviour''. Take a history from his mother to assess for ADHD.', 420, '[{"item":"Asked about onset before age twelve and duration","weight":1},{"item":"Asked about inattention, hyperactivity and impulsivity with examples","weight":2},{"item":"Checked if symptoms occur in more than one setting","weight":2},{"item":"Took birth and developmental history","weight":1},{"item":"Asked about family history","weight":1},{"item":"Asked about sleep, screens and mood","weight":1},{"item":"Asked about strengths and the parent''s feelings","weight":1}]'::jsonb, '{"label":"Global child history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-21', 'History: the girl who has lost weight', 'Kritika, 17, has lost 10 kg in six months. Take a history to assess for an eating disorder, including medical risk.', 420, '[{"item":"Asked about eating pattern and restriction","weight":1},{"item":"Asked about body image and fear of weight gain","weight":2},{"item":"Asked about compensatory behaviours: exercise, vomiting, laxatives","weight":1},{"item":"Asked about periods","weight":1},{"item":"Asked about physical risk symptoms: dizziness, fainting, palpitations","weight":2},{"item":"Asked about mood and self-harm","weight":1},{"item":"Remained non-judgemental","weight":1},{"item":"Mentioned the need for physical checks (weight, BMI, blood tests, ECG)","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-22', 'Assessment after an overdose', 'Neha, 24, took 20 paracetamol tablets last night and is now medically fit. Assess her suicide risk before discharge.', 420, '[{"item":"Explored the events before, during and after the overdose","weight":2},{"item":"Assessed intent: planning, isolation, precautions against discovery, note","weight":2},{"item":"Asked how she feels about having survived","weight":1},{"item":"Asked about current suicidal thoughts and plans","weight":2},{"item":"Asked about past attempts, mental illness and substance use","weight":1},{"item":"Explored protective factors","weight":1},{"item":"Formulated risk and a safety plan, including means and follow-up","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-23', 'Violence risk on the ward', 'Mr Singh, 32, was admitted yesterday. Staff say he threatened a nurse. Assess his risk of violence.', 420, '[{"item":"Ensured safety: position near exit, staff aware, calm tone","weight":2},{"item":"Asked about thoughts of harming others and towards whom","weight":2},{"item":"Asked about command voices and whether he feels he must obey","weight":2},{"item":"Asked about persecutory beliefs and threat from the nurse","weight":1},{"item":"Asked about past violence, substance use and weapons","weight":1},{"item":"Asked about self-harm","weight":1},{"item":"Summarised risk and immediate steps (staff, observation, review)","weight":1}]'::jsonb, '{"label":"Global violence risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-24', 'Mental state: thought disorder', 'Talk with Mr Das, 40, for five minutes, then describe his form of thought to the examiner using correct terms.', 420, '[{"item":"Allowed the patient to speak freely to sample speech","weight":1},{"item":"Identified loosening of associations (derailment)","weight":2},{"item":"Identified thought block","weight":1},{"item":"Identified neologism","weight":1},{"item":"Distinguished thought form from content","weight":2},{"item":"Gave examples from the conversation","weight":1},{"item":"Used correct terms and avoided vague labels like ''confused''","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-25', 'Mental state: perceptual abnormalities', 'Mrs Kaur, 55, says she ''sees and hears things''. Explore her perceptual experiences and classify them.', 420, '[{"item":"Asked about each sense: hearing, sight, smell, taste, touch","weight":1},{"item":"Explored timing (falling asleep, waking, daytime)","weight":2},{"item":"Asked whether the experience seemed inside or outside the head","weight":1},{"item":"Asked about insight (does she think it is real)","weight":1},{"item":"Identified hypnagogic images as normal","weight":1},{"item":"Linked the burning smell and lost time to possible seizures","weight":2},{"item":"Considered bereavement-related experiences","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-26', 'Cognitive screen at the bedside', 'Carry out a brief cognitive screen on Mr Iyer, 78, covering orientation, attention, recall, language and visuospatial skills. Explain what you are doing.', 420, '[{"item":"Introduced and gained consent; checked hearing, glasses and education","weight":2},{"item":"Tested orientation to time and place","weight":1},{"item":"Tested attention (serial sevens, months backwards or similar)","weight":1},{"item":"Registered three words and tested delayed recall","weight":2},{"item":"Tested naming and following a command","weight":1},{"item":"Tested visuospatial copy or clock drawing","weight":1},{"item":"Explained the results in plain words and the need for full assessment","weight":1}]'::jsonb, '{"label":"Global cognitive assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-27', 'Frontal lobe tests', 'Mr Patel''s wife says his personality changed after a head injury. Demonstrate three or more bedside tests of frontal lobe function and describe what you find.', 420, '[{"item":"Explained the tests and gained consent","weight":1},{"item":"Tested verbal fluency (letter or category)","weight":2},{"item":"Tested motor sequencing (fist-edge-palm)","weight":1},{"item":"Tested response inhibition (go or no-go)","weight":1},{"item":"Tested abstraction (proverb or similarities)","weight":1},{"item":"Observed social behaviour and disinhibition","weight":1},{"item":"Interpreted results correctly","weight":2}]'::jsonb, '{"label":"Global frontal assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-28', 'Assessing insight', 'Mr Thomas, 30, has schizophrenia. Assess his insight into his illness and its treatment.', 420, '[{"item":"Asked whether he thinks he has an illness","weight":1},{"item":"Asked how he explains his experiences","weight":2},{"item":"Asked about his view of treatment and why he takes it","weight":2},{"item":"Asked what would happen if he stopped","weight":1},{"item":"Explored what helps him (sleep)","weight":1},{"item":"Summarised insight as partial with reasons","weight":2}]'::jsonb, '{"label":"Global insight assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-29', 'History: the sleepless lawyer', 'Ms Rao, 38, a lawyer, asks for sleeping tablets. Take a sleep history.', 420, '[{"item":"Asked about sleep onset, maintenance and early waking","weight":1},{"item":"Asked about bedtime routine and screens","weight":1},{"item":"Asked about caffeine, alcohol and medicines","weight":1},{"item":"Asked about naps and sleep schedule","weight":1},{"item":"Screened for sleep apnoea and restless legs","weight":2},{"item":"Asked about mood and anxiety","weight":2},{"item":"Explained why tablets are not first choice","weight":1}]'::jsonb, '{"label":"Global sleep history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-30', 'History: the mother of a new baby', 'Mrs Fatima Shaikh, 27, had a baby six weeks ago. The health visitor is worried about her mood. Take a history including risk.', 420, '[{"item":"Asked about mood, sleep, appetite and bonding","weight":1},{"item":"Asked about thoughts of harming herself clearly","weight":2},{"item":"Asked about thoughts of harm to the baby sensitively","weight":2},{"item":"Distinguished intrusive unwanted thoughts from intent","weight":2},{"item":"Asked about psychotic symptoms","weight":1},{"item":"Asked about support at home","weight":1},{"item":"Offered reassurance without dismissing risk","weight":1}]'::jsonb, '{"label":"Global perinatal assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-31', 'History: pain that no test explains', 'Mrs Meena Joshi, 50, has had headaches and body pain for four years with normal tests. Take a history that explores the symptoms and her concerns.', 420, '[{"item":"Took the symptom history fully and with interest","weight":2},{"item":"Asked about her ideas, concerns and expectations","weight":2},{"item":"Asked about investigations and doctor visits","weight":1},{"item":"Asked about life events around onset","weight":1},{"item":"Asked about mood and anxiety","weight":1},{"item":"Avoided dismissive language","weight":1},{"item":"Summarised in a way that validates her","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-32', 'Adolescent alone: substances and safety', 'Riya, 16, was brought because her grades fell. Her parents are outside. Take a psychosocial history using a structured approach (home, education, activities, drugs, sex, suicide).', 420, '[{"item":"Explained confidentiality and its limits at the start","weight":2},{"item":"Asked about home and relationships","weight":1},{"item":"Asked about school and activities","weight":1},{"item":"Asked about alcohol, vaping and drugs","weight":1},{"item":"Asked about relationships and sexual health sensitively","weight":1},{"item":"Asked about self-harm and suicide","weight":2},{"item":"Agreed what to share with parents","weight":1}]'::jsonb, '{"label":"Global adolescent interview competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-33', 'History: sexual difficulty', 'Mr Arora, 34, says he has ''a private problem''. Take a history of his sexual difficulty.', 420, '[{"item":"Ensured privacy and normalised the topic","weight":2},{"item":"Clarified the problem: desire, arousal, erection, ejaculation","weight":1},{"item":"Asked about onset, situational versus global, morning erections","weight":2},{"item":"Asked about medical risks: diabetes, smoking, medicines","weight":1},{"item":"Asked about anxiety, mood and relationship","weight":1},{"item":"Avoided judgemental or embarrassed language","weight":1},{"item":"Outlined next steps including physical checks","weight":1}]'::jsonb, '{"label":"Global sexual history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-34', 'Taking a personality history', 'Ms Dsouza, 26, has had many crises. Explore her long-standing patterns of relating, emotions and behaviour to assess personality.', 420, '[{"item":"Framed questions about long-standing patterns, not just current episode","weight":2},{"item":"Asked about relationships over time","weight":1},{"item":"Asked about emotions, mood changes and triggers","weight":1},{"item":"Asked about self-image and emptiness","weight":1},{"item":"Asked about impulsivity and self-harm","weight":2},{"item":"Sought collateral or other sources as part of plan","weight":1},{"item":"Communicated respectfully without labelling","weight":1}]'::jsonb, '{"label":"Global personality assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-35', 'Risk: an older man after his wife''s death', 'Mr Gill, 72, lives alone after his wife died six months ago. His GP is worried. Assess his suicide risk.', 420, '[{"item":"Asked about suicidal thoughts directly","weight":2},{"item":"Asked about plans and access to means, including the gun","weight":2},{"item":"Recognised high-risk factors: older man, alone, bereaved, alcohol, firearm","weight":2},{"item":"Asked about protective factors","weight":1},{"item":"Asked about depression symptoms","weight":1},{"item":"Agreed an immediate safety plan including removing the firearm","weight":2}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-36', 'Risk: safeguarding a child', 'Mrs Rani, 32, attends for depression. During the session she mentions that her husband hits their 9-year-old son ''to discipline him''. Respond and assess the risk to the child.', 420, '[{"item":"Responded calmly and took the disclosure seriously","weight":2},{"item":"Asked about frequency, injuries and the child''s current safety","weight":2},{"item":"Asked about her own safety","weight":1},{"item":"Explained limits of confidentiality and duty to act","weight":2},{"item":"Explained next steps (child protection services or child welfare committee)","weight":1},{"item":"Offered support and safety planning","weight":1}]'::jsonb, '{"label":"Global safeguarding competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-37', 'History: hearing voices after drinking', 'Mr Chauhan, 45, a heavy drinker, hears threatening voices. Take a history and assess whether this is delirium.', 420, '[{"item":"Asked about the voices: content, timing, insight","weight":1},{"item":"Assessed orientation, attention and awareness","weight":2},{"item":"Asked about withdrawal symptoms (tremor, sweating, seizures)","weight":1},{"item":"Took an alcohol history","weight":1},{"item":"Asked about risk to others (the rod)","weight":2},{"item":"Asked about suicide","weight":1},{"item":"Explained the likely cause and plan","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-38', 'History: the chemist''s sleeping tablets', 'Mrs Lalitha, 55, asks you to ''write her usual tablet''. Take a history of her sedative use.', 420, '[{"item":"Asked about name, dose, duration and source","weight":2},{"item":"Asked about escalation and attempts to stop","weight":1},{"item":"Asked about withdrawal symptoms including seizures","weight":2},{"item":"Asked about falls, memory and driving","weight":1},{"item":"Asked about underlying anxiety and mood","weight":1},{"item":"Explained not stopping abruptly","weight":1},{"item":"Non-judgemental tone","weight":1}]'::jsonb, '{"label":"Global substance history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-39', 'Assessment of catatonia', 'Ms Kumari, 28, has not spoken or eaten for two days. Examine her for catatonic signs and describe them to the examiner.', 420, '[{"item":"Introduced self and explained even though she is mute","weight":1},{"item":"Observed for mutism, staring, posturing and grimacing","weight":2},{"item":"Tested for waxy flexibility or catalepsy","weight":1},{"item":"Tested for negativism or gegenhalten","weight":1},{"item":"Tested for echolalia or echopraxia","weight":1},{"item":"Checked vital signs and hydration (malignant features)","weight":2},{"item":"Described findings and urgency correctly","weight":1}]'::jsonb, '{"label":"Global catatonia examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-40', 'Examine for side effects of antipsychotics', 'Mr Yadav, 38, takes haloperidol. Examine him for extrapyramidal side effects and describe your findings.', 420, '[{"item":"Explained and gained consent","weight":1},{"item":"Observed for tremor and abnormal movements at rest","weight":1},{"item":"Tested tone at the elbows and wrists (rigidity, cogwheeling)","weight":2},{"item":"Observed gait and arm swing","weight":1},{"item":"Looked for orofacial movements (tardive dyskinesia)","weight":2},{"item":"Asked about inner restlessness (akathisia)","weight":1},{"item":"Summarised findings and possible actions","weight":1}]'::jsonb, '{"label":"Global physical examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-41', 'Alcohol withdrawal assessment', 'Mr Nair, 50, was admitted for a fracture. His last drink was 18 hours ago. Assess his withdrawal severity and explain your plan to the examiner.', 420, '[{"item":"Asked about last drink, usual amount and past withdrawal","weight":2},{"item":"Assessed tremor, sweating, nausea, anxiety and agitation","weight":1},{"item":"Asked about perceptual disturbances","weight":1},{"item":"Checked orientation","weight":1},{"item":"Noted past withdrawal seizure as high risk","weight":2},{"item":"Explained a plan: monitoring scale, benzodiazepine regime, thiamine","weight":2}]'::jsonb, '{"label":"Global withdrawal assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-42', 'Recognise neuroleptic malignant syndrome', 'A nurse calls you: Mr Reddy, 30, started on an antipsychotic five days ago, is stiff, confused and has a temperature of 39.5. Assess him and explain your actions.', 420, '[{"item":"Asked about recent antipsychotic changes","weight":1},{"item":"Recognised fever, rigidity, confusion and autonomic instability","weight":2},{"item":"Requested creatine kinase, kidney tests and blood count","weight":1},{"item":"Stopped the antipsychotic","weight":2},{"item":"Arranged urgent medical care (cooling, fluids, monitoring)","weight":2},{"item":"Considered differentials (infection, serotonin toxicity)","weight":1}]'::jsonb, '{"label":"Global emergency recognition competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-43', 'Recognise serotonin toxicity', 'Ms Joshi, 35, on an SSRI, was given tramadol for back pain yesterday. She is agitated, sweating and twitching. Assess her and explain your thinking.', 420, '[{"item":"Took a medicine history and noticed the SSRI plus tramadol","weight":2},{"item":"Elicited clonus and brisk reflexes","weight":2},{"item":"Noted rapid onset over hours","weight":1},{"item":"Distinguished from NMS (slower onset, rigidity, slow reflexes)","weight":2},{"item":"Stopped serotonergic drugs and arranged medical care","weight":1}]'::jsonb, '{"label":"Global emergency recognition competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-44', 'Recognise lithium toxicity', 'Mr Rao, 66, on lithium, is brought by his wife: shaky, vomiting and unsteady. Take a focused history and explain your plan.', 420, '[{"item":"Asked about symptoms and timing","weight":1},{"item":"Asked about fluid loss and intake","weight":1},{"item":"Asked about new medicines (NSAIDs, diuretics, ACE inhibitors)","weight":2},{"item":"Asked about last lithium level","weight":1},{"item":"Recognised toxicity and stopped lithium","weight":2},{"item":"Arranged urgent level, kidney tests and emergency care","weight":2},{"item":"Explained prevention to the wife","weight":1}]'::jsonb, '{"label":"Global emergency recognition competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-45', 'Screen for metabolic side effects', 'Ms Begum, 34, has taken olanzapine for a year and gained 12 kg. Discuss and plan her physical health monitoring.', 420, '[{"item":"Acknowledged the distress about weight","weight":1},{"item":"Asked about thirst, urination and family history of diabetes","weight":1},{"item":"Planned weight, waist, BP, glucose or HbA1c and lipids","weight":2},{"item":"Discussed lifestyle support","weight":1},{"item":"Discussed medicine options (switch, add-on) with prescriber","weight":2},{"item":"Advised against stopping abruptly","weight":1},{"item":"Agreed a monitoring schedule","weight":1}]'::jsonb, '{"label":"Global physical health monitoring competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-46', 'Assessing capacity to refuse treatment', 'Mrs Desai, 60, with depression, refuses dialysis. The renal team asks you to assess her capacity to refuse.', 420, '[{"item":"Explained the purpose and that capacity is decision-specific","weight":1},{"item":"Assessed understanding of the information","weight":1},{"item":"Assessed retention","weight":1},{"item":"Assessed ability to weigh the information","weight":2},{"item":"Assessed ability to communicate a choice","weight":1},{"item":"Considered whether depression is distorting the weighing","weight":2},{"item":"Documented and planned treatment of depression and review","weight":1}]'::jsonb, '{"label":"Global capacity assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-47', 'History: late-life worry', 'Mr Bose, 70, is ''always worried''. Take a history of his anxiety and screen for medical and cognitive contributors.', 420, '[{"item":"Asked about worry content, control and duration","weight":1},{"item":"Asked about physical symptoms","weight":1},{"item":"Asked about medicines and caffeine (decongestant)","weight":2},{"item":"Screened for low mood","weight":1},{"item":"Screened for memory problems","weight":1},{"item":"Asked about medical conditions (thyroid, heart, lungs)","weight":1},{"item":"Summarised and proposed a plan","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-48', 'History: the gambler', 'Mr Patil, 29, says he is ''in a money problem''. Take a history about his gambling.', 420, '[{"item":"Asked about type, frequency and money spent","weight":1},{"item":"Asked about chasing losses and loss of control","weight":1},{"item":"Asked about debts and lying","weight":1},{"item":"Asked about legal and work risks sensitively","weight":1},{"item":"Asked about suicide clearly","weight":2},{"item":"Asked about alcohol and mood","weight":1},{"item":"Discussed financial safety steps","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-49', 'History from an interpreter', 'Mrs Lakshmamma, 44, speaks only Telugu. Using the interpreter present, take a brief history of her low mood.', 420, '[{"item":"Briefed the interpreter on confidentiality and word-for-word interpreting","weight":1},{"item":"Spoke directly to the patient, not the interpreter","weight":2},{"item":"Used short, clear questions","weight":1},{"item":"Checked whether the patient is comfortable with this interpreter (a neighbour)","weight":2},{"item":"Asked about mood and suicide clearly","weight":2},{"item":"Checked understanding at the end","weight":1}]'::jsonb, '{"label":"Global interpreter-assisted interview competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-50', 'History: the man who wants a letter (secondary gain)', 'Mr Kapoor, 40, wants a certificate saying he is unfit for work for six months due to stress. Take a history and decide what you can honestly write.', 420, '[{"item":"Took a full history of symptoms and function","weight":2},{"item":"Assessed mood and anxiety severity","weight":1},{"item":"Explored work conflict","weight":1},{"item":"Was honest about what the evidence supports","weight":2},{"item":"Offered appropriate help (short leave, HR route, therapy)","weight":1},{"item":"Stayed calm and respectful when challenged","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-51', 'Delirium screen on the ward', 'Mrs Kapoor, 82, became confused overnight after a hip operation. Assess her for delirium and outline likely causes.', 420, '[{"item":"Assessed attention (months backwards or similar)","weight":2},{"item":"Assessed orientation and level of alertness","weight":1},{"item":"Asked about fluctuation and onset (from staff or family)","weight":1},{"item":"Looked for causes: pain medicines, urinary retention, infection, dehydration","weight":2},{"item":"Asked about hallucinations","weight":1},{"item":"Outlined management of causes and environment","weight":1}]'::jsonb, '{"label":"Global delirium assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-52', 'History: sudden change in an older man''s behaviour', 'Mr Fernandes, 70, has become ''over-friendly'' and spends wildly for two weeks. His wife is distressed. Take a collateral history.', 420, '[{"item":"Established a clear change from his usual self","weight":1},{"item":"Asked about onset and any medical event (the stroke)","weight":2},{"item":"Asked about sleep, mood, speech and spending","weight":1},{"item":"Asked about medicines, alcohol and drugs","weight":1},{"item":"Asked about safety and risk","weight":1},{"item":"Considered an organic cause in late-onset mania","weight":2},{"item":"Supported the wife","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-53', 'Assess suicide risk in a student after exam failure', 'Arjun, 18, failed his entrance exam. His coaching centre warden found him crying. Assess his risk.', 420, '[{"item":"Built rapport quickly and non-judgementally","weight":1},{"item":"Asked about suicidal thoughts directly","weight":2},{"item":"Asked about plans, means and timing","weight":2},{"item":"Asked about exposure to suicide (hostel mate)","weight":1},{"item":"Asked about protective factors","weight":1},{"item":"Agreed an immediate safety plan and informed appropriate people with explanation","weight":2}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-54', 'History: is this grief or something more?', 'Mrs Krishnan, 55, lost her son 18 months ago. Take a history to decide between normal grief, prolonged grief disorder and a depressive episode.', 420, '[{"item":"Let her tell the story of the loss","weight":1},{"item":"Asked about yearning, preoccupation and disbelief","weight":2},{"item":"Asked about duration and impact","weight":1},{"item":"Screened for depressive features (worthlessness, global anhedonia)","weight":2},{"item":"Asked about suicide","weight":1},{"item":"Explained the conclusion kindly","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-55', 'History: the bride with fits', 'Lakshmi, 22, has ''fits'' since her marriage eight months ago. Take a history of the episodes and her situation.', 420, '[{"item":"Asked for a detailed description of an episode (before, during, after)","weight":2},{"item":"Asked about features suggesting epilepsy or not (eyes, duration, injuries)","weight":1},{"item":"Asked about triggers and the home situation","weight":1},{"item":"Asked gently about past trauma","weight":2},{"item":"Asked about mood and self-harm","weight":1},{"item":"Explained the plan without implying faking","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-56', 'Elicit delusions: assessing conviction', 'Mr Bhatt, 52, believes his wife is unfaithful. Explore this belief to decide whether it is a delusion.', 420, '[{"item":"Explored the belief with neutral curiosity","weight":1},{"item":"Asked about evidence and how he came to believe it","weight":1},{"item":"Assessed conviction and response to counter-evidence","weight":2},{"item":"Assessed whether the belief is shared culturally or by others","weight":1},{"item":"Asked about actions taken (checking, following)","weight":1},{"item":"Assessed risk to the wife","weight":2},{"item":"Concluded with reasons whether it is delusional","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-57', 'History: the patient who hears her name at night', 'Ms Priya, 20, is worried because she hears her name called as she falls asleep. Explore and explain.', 420, '[{"item":"Explored timing and frequency","weight":1},{"item":"Asked about daytime experiences","weight":1},{"item":"Asked about insight","weight":1},{"item":"Asked about stress, sleep and substances","weight":1},{"item":"Identified hypnagogic experiences as normal","weight":2},{"item":"Reassured clearly and gave advice on sleep","weight":2}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-58', 'Assess mood and risk on the telephone', 'You are on a helpline. A caller, Sam, 30, says ''I can''t do this anymore''. Assess risk over the phone and act.', 420, '[{"item":"Introduced self and established the caller''s name and location early","weight":2},{"item":"Asked directly about suicidal intent and means","weight":2},{"item":"Asked whether pills had been taken","weight":2},{"item":"Kept the caller engaged with calm, warm language","weight":1},{"item":"Asked the caller to move the pills away","weight":1},{"item":"Arranged emergency help or a trusted person","weight":2}]'::jsonb, '{"label":"Global telephone risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-59', 'History: a child who won''t speak at school', 'Speak to the father of Rehan, 6, who talks at home but not at school. Take a history.', 420, '[{"item":"Asked where the child speaks and does not","weight":2},{"item":"Asked about duration and onset","weight":1},{"item":"Asked about language development and hearing","weight":1},{"item":"Asked about temperament and family history of anxiety","weight":1},{"item":"Asked about how school responds","weight":1},{"item":"Explained the condition and a graded plan","weight":1}]'::jsonb, '{"label":"Global child history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-60', 'History: a man who wants to stop his medicine', 'Mr Neeraj, 31, stable for two years on an antipsychotic injection, wants to stop. Explore his reasons.', 420, '[{"item":"Asked open questions about his reasons","weight":2},{"item":"Asked about side effects directly, including sexual ones","weight":2},{"item":"Asked about stigma and fears","weight":1},{"item":"Asked about residual symptoms","weight":1},{"item":"Did not lecture","weight":1},{"item":"Summarised options to discuss with the team","weight":1}]'::jsonb, '{"label":"Global adherence history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-61', 'Clinical handover to a senior', 'You have just assessed Mr Kamble, 38, who hears voices telling him to harm his supervisor. Call the consultant and hand over using a structured format.', 420, '[{"item":"Introduced self and the reason for the call","weight":1},{"item":"Gave the situation in one or two sentences","weight":1},{"item":"Gave relevant background (diagnosis, stopped medicine, past admissions)","weight":1},{"item":"Gave a clear assessment of risk (commands, target, weapon access)","weight":2},{"item":"Made a clear request or recommendation","weight":2},{"item":"Confirmed the plan and read back","weight":1}]'::jsonb, '{"label":"Global clinical communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-62', 'Explain why you are asking about suicide', 'Ms Joshi, 40, with low mood, asks: ''Why are you asking me about suicide? Won''t that put ideas in my head?'' Answer her and complete the question.', 420, '[{"item":"Acknowledged her concern","weight":1},{"item":"Explained that asking does not increase risk and is routine","weight":2},{"item":"Asked the question clearly","weight":2},{"item":"Followed up on passive thoughts (plans, intent)","weight":2},{"item":"Explored protective factors","weight":1},{"item":"Thanked her and summarised","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-63', 'Explain lithium before starting', 'Ms Revathi, 30, with bipolar I disorder, is advised to start lithium. Explain the medicine, the tests and the safety rules.', 420, '[{"item":"Explained what lithium does in plain words (prevents highs and lows)","weight":1},{"item":"Explained regular blood levels, kidney and thyroid tests","weight":2},{"item":"Explained signs of toxicity: coarse tremor, vomiting, diarrhoea, unsteadiness, confusion","weight":2},{"item":"Explained sick-day rules and avoiding NSAIDs without advice","weight":2},{"item":"Addressed the kidney fear honestly","weight":1},{"item":"Mentioned planning before pregnancy","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global medication explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-64', 'Explain clozapine', 'Mr Prakash, 35, has treatment-resistant schizophrenia. Explain clozapine to him and his sister.', 420, '[{"item":"Explained why clozapine is offered (works when others have not)","weight":2},{"item":"Explained regular blood counts and why (low white cells)","weight":2},{"item":"Explained to report fever, sore throat, chest pain or breathlessness","weight":2},{"item":"Discussed common side effects: drowsiness, drooling, constipation, weight","weight":1},{"item":"Explained that smoking changes affect the dose","weight":1},{"item":"Linked to his goals","weight":1}]'::jsonb, '{"label":"Global medication explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-65', 'Consent for ECT', 'Mrs Sharma, 62, has severe depression with food refusal. ECT is recommended. Explain it to her and her son and seek consent.', 420, '[{"item":"Explained why ECT is recommended now","weight":1},{"item":"Described the procedure: anaesthesia, muscle relaxant, brief current, no pain","weight":2},{"item":"Discussed benefits and how many sessions","weight":1},{"item":"Discussed side effects: headache, confusion, memory effects","weight":2},{"item":"Explained the right to refuse or withdraw","weight":1},{"item":"Explained that modified ECT under anaesthesia is the legal standard in India","weight":1},{"item":"Checked capacity and understanding","weight":1}]'::jsonb, '{"label":"Global consent competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-66', 'Explain a schizophrenia diagnosis', 'Explain to Mr Thomas, 25, that his illness fits schizophrenia. Answer his questions.', 420, '[{"item":"Checked what he already knows or thinks","weight":1},{"item":"Explained the diagnosis in plain words","weight":1},{"item":"Gave honest, hopeful outcome information","weight":2},{"item":"Addressed blame and cannabis accurately","weight":1},{"item":"Addressed marriage and life goals","weight":1},{"item":"Explained treatment and relapse prevention","weight":1},{"item":"Checked understanding and feelings","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-67', 'Explain OCD and its treatment', 'Explain obsessive-compulsive disorder and exposure and response prevention to Neha, 20, and her mother.', 420, '[{"item":"Explained obsessions and compulsions in plain words","weight":1},{"item":"Explained the cycle: anxiety, ritual, relief, stronger urge","weight":2},{"item":"Explained exposure and response prevention step by step","weight":2},{"item":"Advised the family to reduce reassurance kindly","weight":1},{"item":"Mentioned medicine options (SSRIs)","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global psychoeducation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-68', 'Explain ADHD to parents', 'Explain to the parents of Aryan, 7, that he has ADHD and discuss treatment.', 420, '[{"item":"Explained ADHD as a brain-based developmental condition","weight":1},{"item":"Addressed blame directly","weight":2},{"item":"Explained parent training and school support","weight":1},{"item":"Explained medicine benefits and side effects honestly","weight":2},{"item":"Addressed the addiction and ''zombie'' fears","weight":1},{"item":"Highlighted his strengths","weight":1}]'::jsonb, '{"label":"Global psychoeducation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-69', 'Explain autism to parents', 'Share the diagnosis of autism with the parents of Riya, 4, and answer their questions.', 420, '[{"item":"Prepared the parents and checked what they know","weight":1},{"item":"Gave the diagnosis clearly and kindly","weight":2},{"item":"Explained autism as a lifelong difference in development","weight":1},{"item":"Addressed blame (screens did not cause it)","weight":2},{"item":"Gave honest hope about speech and early intervention","weight":1},{"item":"Gave next steps and support","weight":1}]'::jsonb, '{"label":"Global breaking news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-70', 'Explain dementia to a family', 'Explain to Mr Rao''s daughter that tests suggest Alzheimer''s dementia. Discuss what this means.', 420, '[{"item":"Gave a warning shot and checked what she understands","weight":1},{"item":"Gave the diagnosis clearly","weight":1},{"item":"Explained the likely course honestly","weight":1},{"item":"Discussed medicines (cholinesterase inhibitors) realistically","weight":1},{"item":"Discussed safety and planning while he has capacity","weight":2},{"item":"Addressed her genetic worry accurately","weight":1},{"item":"Offered support for carers","weight":1}]'::jsonb, '{"label":"Global breaking news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-71', 'Explain delirium to a worried son', 'Mrs Kapoor, 82, has delirium after surgery. Her son thinks ''she has gone mad''. Explain delirium.', 420, '[{"item":"Explained delirium as a temporary brain upset caused by illness","weight":2},{"item":"Explained common causes","weight":1},{"item":"Explained it is usually reversible but can take days or weeks","weight":1},{"item":"Explained why sedation is avoided where possible","weight":2},{"item":"Advised how family can help (orientation, glasses, calm presence)","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global psychoeducation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-72', 'Explain an antipsychotic long-acting injection', 'Ms Shabana, 37, keeps relapsing after stopping tablets. Explain a long-acting injection as an option.', 420, '[{"item":"Asked about her experience with tablets","weight":1},{"item":"Explained what a long-acting injection is","weight":1},{"item":"Addressed the stigma about injections","weight":2},{"item":"Discussed side effects and options","weight":1},{"item":"Discussed covert medication honestly and that she will be told everything","weight":2},{"item":"Left the decision with her","weight":1}]'::jsonb, '{"label":"Global medication explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-73', 'Valproate and a woman who may become pregnant', 'Ms Pallavi, 34, on valproate for bipolar disorder, plans to marry next year. Counsel her.', 420, '[{"item":"Explained valproate''s risks in pregnancy (birth defects, development)","weight":2},{"item":"Discussed effective contraception now","weight":2},{"item":"Discussed alternative medicines","weight":1},{"item":"Advised not to stop suddenly","weight":1},{"item":"Addressed relapse fear","weight":1},{"item":"Offered support with disclosure","weight":1}]'::jsonb, '{"label":"Global medication counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-74', 'Advance directive under the Mental Healthcare Act', 'Mr Kunal, 38, with bipolar disorder, wants to decide in advance how he is treated if he becomes unwell. Explain an advance directive under the Mental Healthcare Act 2017.', 420, '[{"item":"Explained what an advance directive is","weight":1},{"item":"Explained who can make one (an adult with capacity)","weight":1},{"item":"Explained he can state treatments he wants or refuses","weight":1},{"item":"Explained nominating a representative","weight":2},{"item":"Explained registration with the Mental Health Review Board","weight":1},{"item":"Explained when it may not be followed (emergencies, Board review)","weight":2},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global legal counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-75', 'Nominated representative', 'Mrs Kaur''s son asks what a ''nominated representative'' is and whether he can be one for his mother. Explain.', 420, '[{"item":"Explained who can be a nominated representative","weight":1},{"item":"Explained how one is appointed (by the person, or by order where none)","weight":2},{"item":"Explained duties: support decisions, consider the person''s wishes","weight":2},{"item":"Explained rights: information, involvement in discharge planning, appeals","weight":1},{"item":"Explained it is not absolute control","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global legal counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-76', 'Supported admission', 'Mr Kamble needs admission but refuses. Explain to his wife the conditions for a supported (non-voluntary) admission and his rights.', 420, '[{"item":"Explained when supported admission is allowed (risk, lack of capacity to decide, after assessment)","weight":2},{"item":"Explained who assesses and applies","weight":1},{"item":"Explained time limits and review","weight":1},{"item":"Explained his rights: information, appeal to the Board, nominated representative","weight":2},{"item":"Addressed her guilt","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global legal counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-77', 'Confidentiality and a worried employer', 'The HR manager of your client Kiran calls asking about Kiran''s diagnosis and when they will return to work. Respond.', 420, '[{"item":"Did not confirm or disclose clinical information without consent","weight":2},{"item":"Explained confidentiality respectfully","weight":1},{"item":"Offered to seek the client''s consent","weight":1},{"item":"Explained what could be shared with consent (fitness for work, adjustments)","weight":2},{"item":"Remained polite and firm","weight":1},{"item":"Documented the call","weight":1}]'::jsonb, '{"label":"Global ethics competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-78', 'Duty to protect: a client threatens someone', 'In session, your client says, ''If my brother-in-law takes the property, I''ll kill him. I know where he lives.'' Respond and decide what to do.', 420, '[{"item":"Stayed calm and explored the threat seriously","weight":1},{"item":"Assessed intent, plan, means, timeline and history of violence","weight":2},{"item":"Explained limits of confidentiality","weight":1},{"item":"Recognised a serious, specific threat to an identifiable person","weight":2},{"item":"Planned protective action (consult senior, warn, inform police as required)","weight":2},{"item":"Documented the assessment and decision","weight":1}]'::jsonb, '{"label":"Global ethics competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-79', 'Reporting under POCSO', 'Meera, 14, tells you her tuition teacher touches her inappropriately. She begs you not to tell anyone. Respond.', 420, '[{"item":"Listened calmly and believed her","weight":2},{"item":"Did not ask leading questions or press for detail","weight":1},{"item":"Explained that this must be reported to keep her safe","weight":2},{"item":"Explained the mandatory reporting duty and who will be told","weight":1},{"item":"Reassured that it is not her fault","weight":1},{"item":"Planned immediate safety and support","weight":1}]'::jsonb, '{"label":"Global safeguarding competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-80', 'Consent for therapy with a 16-year-old', 'Kabir, 16, wants counselling for anxiety but does not want his parents told. Discuss consent and confidentiality.', 420, '[{"item":"Explored why he does not want parents involved","weight":1},{"item":"Explained confidentiality and its limits","weight":2},{"item":"Explained the legal position on minors and parental consent in your setting","weight":2},{"item":"Encouraged appropriate parental involvement without forcing","weight":1},{"item":"Agreed a plan he can accept","weight":1},{"item":"Checked safety","weight":1}]'::jsonb, '{"label":"Global ethics competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-81', 'Telepsychiatry: identity and safety', 'Begin a first video consultation with a new client, Ms Rhea, 31. Set it up safely before clinical work.', 420, '[{"item":"Confirmed identity and location","weight":2},{"item":"Checked privacy and who else is present","weight":1},{"item":"Obtained consent for video work","weight":1},{"item":"Agreed what to do if the call drops","weight":1},{"item":"Obtained an emergency contact and local emergency plan","weight":2},{"item":"Explained confidentiality and recording","weight":1}]'::jsonb, '{"label":"Global telehealth practice competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-82', 'Motivational interviewing for drinking', 'Mr Hegde, 52, with early liver damage, says he will ''just cut down''. Use motivational interviewing to explore change.', 420, '[{"item":"Used open questions","weight":1},{"item":"Used reflective listening","weight":2},{"item":"Avoided arguing or lecturing","weight":2},{"item":"Elicited his own reasons for change (change talk)","weight":2},{"item":"Developed discrepancy between values and drinking","weight":1},{"item":"Summarised and asked about next steps","weight":1}]'::jsonb, '{"label":"Global motivational interviewing competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-83', 'Behavioural activation', 'Explain behavioural activation to Mr Abdul, 47, with depression, and plan his first week.', 420, '[{"item":"Explained the link between activity and mood","weight":2},{"item":"Explained acting before motivation arrives","weight":1},{"item":"Identified valued activities with him","weight":1},{"item":"Planned small, specific steps","weight":2},{"item":"Anticipated barriers","weight":1},{"item":"Agreed a way to review","weight":1}]'::jsonb, '{"label":"Global therapy skills competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-84', 'A thought record', 'Help Ms Megha, 30, complete a thought record for a recent situation where she felt worthless.', 420, '[{"item":"Identified the situation","weight":1},{"item":"Identified the emotion and its strength","weight":1},{"item":"Identified the automatic thought","weight":2},{"item":"Explored evidence for and against","weight":2},{"item":"Helped form a balanced thought","weight":1},{"item":"Re-rated the emotion","weight":1}]'::jsonb, '{"label":"Global CBT skills competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-85', 'Grounding during a flashback', 'During a session, Aditi, 23, suddenly looks frightened and says ''he''s here''. Help her ground herself.', 420, '[{"item":"Used her name and a calm, steady voice","weight":1},{"item":"Oriented her to the present (time, place, safety)","weight":2},{"item":"Used sensory grounding (see, hear, touch)","weight":2},{"item":"Did not touch her without permission","weight":1},{"item":"Checked when she was back","weight":1},{"item":"Debriefed and planned for future triggers","weight":1}]'::jsonb, '{"label":"Global therapy skills competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-86', 'Make a safety plan', 'Ms Neha, 24, after an overdose, is going home. Create a safety plan with her.', 420, '[{"item":"Identified warning signs","weight":1},{"item":"Identified internal coping strategies","weight":1},{"item":"Identified people and places for distraction","weight":1},{"item":"Identified people to ask for help","weight":1},{"item":"Listed professional and crisis contacts","weight":1},{"item":"Addressed means safety (paracetamol)","weight":2},{"item":"Wrote it in her words and gave her a copy","weight":1}]'::jsonb, '{"label":"Global safety planning competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-87', 'Relapse prevention plan for bipolar disorder', 'Ms Revathi, 47, has stable bipolar disorder. Build a relapse prevention plan with her.', 420, '[{"item":"Identified early warning signs of highs and lows","weight":2},{"item":"Identified triggers","weight":1},{"item":"Agreed actions for each stage","weight":2},{"item":"Involved her husband with consent","weight":1},{"item":"Addressed adherence and sleep","weight":1},{"item":"Wrote down contacts","weight":1}]'::jsonb, '{"label":"Global relapse prevention competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-88', 'Family psychoeducation: expressed emotion', 'The parents of Rakesh, 21, recovering from a first episode, keep criticising him for being ''lazy''. Talk with them about how they can help.', 420, '[{"item":"Acknowledged their worry and love","weight":1},{"item":"Explained negative symptoms and recovery","weight":2},{"item":"Explained that criticism and over-involvement raise relapse risk","weight":2},{"item":"Suggested practical communication changes","weight":1},{"item":"Avoided blaming","weight":1},{"item":"Offered family sessions","weight":1}]'::jsonb, '{"label":"Global family psychoeducation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-89', 'Feedback of an intelligence assessment', 'Give feedback to the parents of Sunny, 10, whose assessment shows a full-scale IQ of 62 with similar adaptive scores.', 420, '[{"item":"Checked what the parents expect","weight":1},{"item":"Explained the results in plain words, not just numbers","weight":2},{"item":"Explained intellectual disability (mild) including adaptive skills","weight":1},{"item":"Highlighted strengths found in testing","weight":1},{"item":"Discussed schooling, support and certification","weight":2},{"item":"Gave hope and answered fears","weight":1}]'::jsonb, '{"label":"Global assessment feedback competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-90', 'Explain a personality test result', 'Ms Divya, 29, completed a personality inventory as part of assessment. Give her feedback on the profile, which shows high neuroticism and low extraversion.', 420, '[{"item":"Explained what the test measures and its limits","weight":2},{"item":"Described traits in plain, non-judgemental words","weight":1},{"item":"Linked results to her own experience","weight":1},{"item":"Highlighted strengths","weight":1},{"item":"Avoided labelling as abnormal","weight":1},{"item":"Discussed how results inform therapy","weight":1}]'::jsonb, '{"label":"Global assessment feedback competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-91', 'Breaking news: the referral to a psychiatrist after a scan', 'Kiran, 20, has functional leg weakness. Her MRI is normal. Explain the result and the diagnosis.', 420, '[{"item":"Explained the normal scan as good news","weight":1},{"item":"Gave the diagnosis positively (functional neurological disorder)","weight":2},{"item":"Explained the ''software not hardware'' idea","weight":1},{"item":"Showed a positive sign (Hoover''s) if relevant","weight":1},{"item":"Avoided ''all in your head''","weight":2},{"item":"Explained treatment with physiotherapy","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-92', 'Talking to a family who prefer a faith healer', 'The family of Imran, 24, with psychosis, plan to take him to a dargah instead of starting medicine. Talk with them.', 420, '[{"item":"Explored the family''s beliefs respectfully","weight":2},{"item":"Did not dismiss faith or healing practices","weight":2},{"item":"Explained the medical view simply","weight":1},{"item":"Suggested both together where safe","weight":1},{"item":"Addressed safety (no chaining, no stopping food)","weight":1},{"item":"Agreed a plan","weight":1}]'::jsonb, '{"label":"Global cultural communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-93', 'Respond to a complaint', 'Mrs Gupta says the clinic shared her daughter''s diagnosis with a relative on the phone. Respond to her complaint.', 420, '[{"item":"Listened without interrupting or defending","weight":2},{"item":"Acknowledged and apologised for her experience","weight":1},{"item":"Did not blame colleagues publicly","weight":1},{"item":"Explained the complaint process and timeline","weight":2},{"item":"Explained how this will be investigated","weight":1},{"item":"Offered to keep her informed","weight":1}]'::jsonb, '{"label":"Global complaint handling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-94', 'Explain a mental health diagnosis to an employer, with consent', 'With Mr Sunil''s written consent, speak to his manager about returning to work after a depressive episode.', 420, '[{"item":"Confirmed the scope of consent","weight":2},{"item":"Shared only fitness for work and adjustments","weight":2},{"item":"Suggested a phased return","weight":1},{"item":"Avoided sharing diagnosis details","weight":1},{"item":"Addressed the ''safe'' question appropriately","weight":1},{"item":"Agreed a review","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-95', 'Responding when a patient asks about your personal life', 'Your client Mr Ravi, 35, asks for your phone number and whether you are married. Respond.', 420, '[{"item":"Responded warmly, not coldly","weight":1},{"item":"Declined to share personal details","weight":2},{"item":"Explained the reason for boundaries","weight":1},{"item":"Explored the meaning of the question","weight":1},{"item":"Offered the clinic contact for between-session needs","weight":1},{"item":"Kept the relationship intact","weight":1}]'::jsonb, '{"label":"Global boundaries competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-96', 'A gift from a client', 'At the last session, Mrs Fernandes offers you a gold chain as thanks. Respond.', 420, '[{"item":"Thanked her warmly","weight":1},{"item":"Declined the valuable gift with explanation","weight":2},{"item":"Considered the meaning and cultural context","weight":1},{"item":"Offered an alternative way to express thanks","weight":1},{"item":"Preserved her dignity","weight":1},{"item":"Considered consulting or documenting","weight":1}]'::jsonb, '{"label":"Global ethics competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-97', 'Discuss a colleague''s impairment', 'Your colleague Dr Arun smelled of alcohol at a morning clinic for the second time this week. Speak to him.', 420, '[{"item":"Chose a private, appropriate moment","weight":1},{"item":"Raised the concern directly but kindly","weight":2},{"item":"Focused on patient safety and his wellbeing","weight":2},{"item":"Offered support routes (occupational health, doctors'' support)","weight":1},{"item":"Explained what you must do if patients are at risk","weight":1},{"item":"Followed up","weight":1}]'::jsonb, '{"label":"Global professionalism competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-98', 'Explain cognitive behavioural therapy', 'Mr Rajesh, 38, with panic disorder, asks, ''What is CBT? Will it just be talking?'' Explain.', 420, '[{"item":"Explained thoughts, feelings, body and behaviour links","weight":2},{"item":"Explained it is active and structured","weight":1},{"item":"Explained homework and practice","weight":1},{"item":"Gave a realistic length (often 8 to 16 sessions)","weight":1},{"item":"Explained evidence for panic disorder","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global psychoeducation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-99', 'Explain exposure therapy for a phobia', 'Mr Salim, 42, must fly in six weeks and fears planes. Explain graded exposure and plan a first step.', 420, '[{"item":"Explained how avoidance keeps fear going","weight":2},{"item":"Explained gradual steps and habituation or new learning","weight":2},{"item":"Built a fear ladder with him","weight":1},{"item":"Agreed a first small step","weight":1},{"item":"Addressed his worry about it getting worse","weight":1}]'::jsonb, '{"label":"Global psychoeducation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-100', 'Explain sleep hygiene and stimulus control', 'Ms Rao, 38, has insomnia. Explain practical changes to improve her sleep without tablets.', 420, '[{"item":"Explained a regular wake time","weight":1},{"item":"Explained using bed only for sleep (stimulus control)","weight":2},{"item":"Advised getting up if awake over about 20 minutes","weight":1},{"item":"Advised caffeine and screen limits","weight":1},{"item":"Explained not napping","weight":1},{"item":"Explained these work over weeks","weight":1}]'::jsonb, '{"label":"Global psychoeducation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-101', 'Explain antidepressant discontinuation', 'Mr Thomas, 63, has been well for nine months on an SSRI and wants to stop. Advise him.', 420, '[{"item":"Reviewed how long he has been well and number of episodes","weight":1},{"item":"Discussed relapse risk and recommended duration","weight":2},{"item":"Explained gradual tapering","weight":2},{"item":"Explained discontinuation symptoms","weight":1},{"item":"Agreed a plan and review","weight":1}]'::jsonb, '{"label":"Global medication explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-102', 'Discuss weight gain on antipsychotics with a teenager', 'Diya, 16, on an antipsychotic after a manic episode, has gained 8 kg and wants to stop. Discuss with her.', 420, '[{"item":"Validated her distress","weight":1},{"item":"Explored her goals","weight":1},{"item":"Explained relapse risk honestly","weight":2},{"item":"Discussed alternatives and add-ons","weight":2},{"item":"Planned lifestyle support","weight":1},{"item":"Involved parents appropriately","weight":1}]'::jsonb, '{"label":"Global shared decision-making competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-103', 'Assess and explain akathisia to a prescriber', 'Call the prescriber of Mr Karan, 29, who has likely akathisia, and request a review.', 420, '[{"item":"Introduced self and purpose","weight":1},{"item":"Gave timeline linking onset to the medicine","weight":2},{"item":"Described observations (pacing, inner restlessness)","weight":2},{"item":"Mentioned risks (distress, stopping medicine, suicidality)","weight":1},{"item":"Made a clear request","weight":1},{"item":"Confirmed the plan","weight":1}]'::jsonb, '{"label":"Global clinical communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-104', 'Talking with a young widow about money and next steps', 'Mrs Lakshmi, 34, lost her husband in an accident two months ago and worries about money. Offer support.', 420, '[{"item":"Listened and validated grief","weight":2},{"item":"Assessed mood and risk","weight":1},{"item":"Explored practical needs","weight":1},{"item":"Linked to practical help (legal aid, schemes, social worker)","weight":2},{"item":"Identified supports","weight":1},{"item":"Agreed follow-up","weight":1}]'::jsonb, '{"label":"Global supportive counselling competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-105', 'Assess a patient''s understanding of a research consent form', 'Mr Mohan, 45, with schizophrenia, is invited into a research study. Check his understanding and obtain consent if appropriate.', 420, '[{"item":"Explained the purpose of the study plainly","weight":1},{"item":"Corrected the belief that it is a cure","weight":2},{"item":"Explained that refusing does not affect care","weight":2},{"item":"Explained risks, benefits and right to withdraw","weight":1},{"item":"Checked understanding with teach-back","weight":1},{"item":"Recorded consent properly","weight":1}]'::jsonb, '{"label":"Global research ethics competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-106', 'Explain the difference between psychologist and psychiatrist', 'Mrs Sharma asks, ''What''s the difference between you, a clinical psychologist, and a psychiatrist? Why do I need both?'' Explain.', 420, '[{"item":"Explained a psychiatrist is a medical doctor who can prescribe","weight":2},{"item":"Explained a clinical psychologist assesses and provides psychological therapy","weight":2},{"item":"Explained why both may help","weight":1},{"item":"Addressed cost and options","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-107', 'Explain a diagnosis of panic disorder', 'Explain to Vivek, 29, with normal ECGs, what panic attacks are and why they are not dangerous.', 420, '[{"item":"Explained the fight-or-flight response","weight":2},{"item":"Explained how symptoms are produced (heart, breathing, tingling)","weight":1},{"item":"Explained the cycle of fear","weight":1},{"item":"Explained panic is not dangerous","weight":1},{"item":"Discussed treatment","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global psychoeducation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-108', 'Assess a patient for dhat syndrome', 'Rahul, 22, believes he loses semen in his urine and is becoming weak. Assess and explain.', 420, '[{"item":"Explored his beliefs respectfully","weight":2},{"item":"Asked about mood, anxiety and sleep","weight":1},{"item":"Asked about physical symptoms","weight":1},{"item":"Gave accurate sex education without ridicule","weight":2},{"item":"Addressed guilt about masturbation","weight":1},{"item":"Planned treatment for anxiety or low mood","weight":1}]'::jsonb, '{"label":"Global cultural assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-109', 'Ask about domestic violence in an antenatal clinic', 'Ms Rani, 26, pregnant, has unexplained bruises. Her husband waits outside. Ask about domestic violence.', 420, '[{"item":"Ensured she was alone and safe to talk","weight":2},{"item":"Asked directly and gently","weight":2},{"item":"Believed and validated","weight":1},{"item":"Assessed immediate risk (pregnancy, weapons, escalation)","weight":1},{"item":"Offered support and helpline information safely","weight":1},{"item":"Explained confidentiality and limits","weight":1}]'::jsonb, '{"label":"Global safeguarding competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-110', 'Brief intervention for tobacco', 'Mr Venkatesh, 55, smokes 25 beedis a day. Deliver a five-minute brief intervention.', 420, '[{"item":"Asked about tobacco use","weight":1},{"item":"Advised to quit clearly and personally","weight":2},{"item":"Assessed readiness","weight":1},{"item":"Corrected the beedi myth","weight":1},{"item":"Assisted with a plan (quit date, nicotine replacement)","weight":2},{"item":"Arranged follow-up","weight":1}]'::jsonb, '{"label":"Global brief intervention competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-111', 'Explain why you will not prescribe a benzodiazepine', 'Mr Chopra, 68, with COPD, demands ''a strong sleeping tablet''. Explain why you will not prescribe a benzodiazepine and offer alternatives.', 420, '[{"item":"Acknowledged his distress","weight":1},{"item":"Explained the risk of breathing suppression in COPD","weight":2},{"item":"Linked his neighbour''s tablet experience","weight":1},{"item":"Offered alternatives (breathing techniques, chest review, CBT)","weight":2},{"item":"Respected his dignity","weight":1},{"item":"Agreed a plan","weight":1}]'::jsonb, '{"label":"Global communication competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-112', 'Talking to a patient who wants to leave against advice', 'Mr Nair, 58, recovering from alcohol withdrawal on day two, wants to leave now to attend a meeting. Respond.', 420, '[{"item":"Explored his reasons","weight":1},{"item":"Explained the risks of leaving (seizures, delirium)","weight":2},{"item":"Assessed capacity for this decision","weight":2},{"item":"Negotiated alternatives","weight":1},{"item":"Respected his autonomy if he has capacity","weight":1},{"item":"Documented and gave a safety plan if he leaves","weight":1}]'::jsonb, '{"label":"Global capacity and negotiation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-113', 'History: worry about everything', 'Mr Vinod Kulkarni, 38, an accountant in Nashik, says he ''cannot switch off''. Take a history to find out whether he has generalised anxiety disorder.', 420, '[{"item":"Opened with a broad question and let him describe the worry","weight":1},{"item":"Established that the worry covers many areas, not one fear","weight":2},{"item":"Asked how hard the worry is to control and how much of the day it takes","weight":2},{"item":"Asked about physical tension, tiredness, irritability, poor concentration and sleep","weight":1},{"item":"Established duration of months, not days","weight":1},{"item":"Screened for panic attacks, low mood and alcohol","weight":1},{"item":"Asked about caffeine, thyroid symptoms and medicines","weight":1},{"item":"Summarised and acknowledged his distress","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-114', 'History: fear of speaking in meetings', 'Ms Farzana Sheikh, 27, a junior engineer, was passed over for promotion because she ''never speaks up''. Take a history of her difficulty.', 420, '[{"item":"Put her at ease and allowed pauses","weight":1},{"item":"Asked which situations bring the fear and what she fears others will think","weight":2},{"item":"Asked about body symptoms in those situations","weight":1},{"item":"Asked about avoidance and safety behaviours such as rehearsing","weight":2},{"item":"Established long duration and impact on work","weight":1},{"item":"Asked about alcohol used to cope and about low mood","weight":1},{"item":"Separated social fear from fear of panic attacks anywhere","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-115', 'History: panic on the metro', 'Mr Rohit Bansal, 31, works in Gurugram. He has stopped taking the Delhi Metro. Take a history of his attacks and what he now avoids.', 420, '[{"item":"Asked him to describe the first attack in detail","weight":1},{"item":"Asked about the peak and length of the attacks","weight":1},{"item":"Asked whether attacks come unexpectedly as well as in crowds","weight":2},{"item":"Asked about fear of further attacks and what he thinks will happen","weight":2},{"item":"Asked about places avoided and how far he can travel alone","weight":2},{"item":"Checked medical causes: heart, thyroid, caffeine, stimulants","weight":1},{"item":"Screened for low mood","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-116', 'History: the nursing student who faints at blood', 'Ms Jincy Thomas, 20, a nursing student in Kottayam, has fainted twice during practical classes. Take a history.', 420, '[{"item":"Asked about the trigger: blood, needles, injury","weight":2},{"item":"Asked what happens in her body, step by step","weight":2},{"item":"Recognised the fainting pattern (a fall in heart rate and blood pressure after an initial rise)","weight":2},{"item":"Ruled out seizures, heart symptoms and other fears","weight":1},{"item":"Asked about avoidance and impact on the course","weight":1},{"item":"Asked about family history","weight":1},{"item":"Ended with hope that it is treatable","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-117', 'History: certain it is cancer', 'Mrs Sunanda Ghosh, 52, from Kolkata, has had four normal scans in a year but remains sure she has stomach cancer. Her physician has referred her. Take a history.', 420, '[{"item":"Acknowledged the fear and her sister''s death early","weight":2},{"item":"Asked about her worry, checking and searching online","weight":1},{"item":"Asked how long reassurance lasts","weight":2},{"item":"Checked for genuine red-flag symptoms: weight loss, bleeding, swallowing difficulty","weight":2},{"item":"Asked about mood and grief","weight":1},{"item":"Did not say the problem is imaginary","weight":1},{"item":"Explored what she hoped from the referral","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-118', 'History: the nose that looks wrong', 'Mr Karthik Raman, 24, has asked a cosmetic surgeon in Chennai for a third nose operation. The surgeon has asked you to see him. Take a history.', 420, '[{"item":"Asked about the concern without arguing about the nose","weight":2},{"item":"Asked about time spent checking, comparing and hiding","weight":1},{"item":"Asked about past procedures and how he felt afterwards","weight":1},{"item":"Assessed how certain he is (insight)","weight":2},{"item":"Asked about suicide clearly","weight":3},{"item":"Asked about impact on work and social life","weight":1},{"item":"Asked about mood and other appearance concerns","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-119', 'Collateral history: a flat full of newspapers', 'Mr Ashok Mehta, 66, lives alone in a Mumbai flat. His son is worried about the state of the home. Take a collateral history from the son.', 420, '[{"item":"Explained purpose and asked whether his father knows about this conversation","weight":1},{"item":"Asked what is kept, for how long, and the distress on discarding","weight":2},{"item":"Asked how rooms can be used: kitchen, bed, bathroom","weight":1},{"item":"Asked about safety: fire, falls, hygiene, pests, blocked exits","weight":2},{"item":"Asked about memory and self-care to look for dementia or self-neglect","weight":1},{"item":"Asked about mood and the effect of his mother''s death","weight":1},{"item":"Acknowledged the son''s feelings","weight":1}]'::jsonb, '{"label":"Global collateral history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-120', 'History: a girl who pulls her hair', 'Riya, 15, wears a cap to school. Her mother has noticed a bald patch. Take a history from Riya (her mother is waiting outside).', 420, '[{"item":"Explained confidentiality and its limits to a teenager","weight":1},{"item":"Asked about the pulling: when, where, how often","weight":1},{"item":"Asked about tension before and relief after, and pulling without awareness","weight":2},{"item":"Asked about attempts to stop","weight":1},{"item":"Asked whether she swallows hair (risk of a hairball in the stomach)","weight":2},{"item":"Asked about mood, bullying and self-harm","weight":2},{"item":"Responded without shock or blame","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-121', 'History: years of grey mood', 'Mr Harish Nair, 44, a bank officer in Thrissur, says he has ''always been a gloomy person''. Recently it is worse. Take a history.', 420, '[{"item":"Established the long baseline of low mood (years, more days than not)","weight":2},{"item":"Identified the recent worsening and its symptoms","weight":2},{"item":"Asked about suicide clearly","weight":2},{"item":"Screened for past highs","weight":1},{"item":"Asked about alcohol, medical illness and medicines","weight":1},{"item":"Asked about stresses and supports","weight":1},{"item":"Summarised both the long-term and the recent pattern","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-122', 'History: low and irritable before periods', 'Ms Divya Rao, 29, a pharmacist in Mysuru, says she ''becomes a different person'' for a week each month. Take a history.', 420, '[{"item":"Asked about timing of symptoms in relation to the cycle","weight":2},{"item":"Confirmed she is well in the week after the period","weight":2},{"item":"Asked about mood, irritability, anxiety and physical symptoms","weight":1},{"item":"Asked about impact on relationships and work","weight":1},{"item":"Screened for depression or anxiety at other times","weight":1},{"item":"Suggested daily symptom rating over at least two cycles","weight":2},{"item":"Asked about contraception and medical history","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-123', 'History: highs that were never noticed', 'Ms Ankita Joshi, 26, has her third depressive episode. Antidepressants ''worked too well'' once. Before treatment is changed, take a history looking for past highs.', 420, '[{"item":"Asked about highs in plain words, not just ''mania''","weight":2},{"item":"Asked about reduced need for sleep with high energy","weight":2},{"item":"Asked about duration of the spells and whether others noticed","weight":2},{"item":"Asked about spending, new projects and risk taking","weight":1},{"item":"Asked about the response to the earlier antidepressant","weight":2},{"item":"Asked about family history","weight":1},{"item":"Asked about current suicide risk","weight":2}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-124', 'History: certain his wife is unfaithful', 'Mr Balwinder Singh, 49, a farmer from Ludhiana, was brought by his brother after accusing his wife of an affair. Take a history and assess risk.', 420, '[{"item":"Explored the belief and the evidence calmly without colluding","weight":2},{"item":"Assessed the strength of conviction","weight":1},{"item":"Asked about checking, following and confronting","weight":1},{"item":"Asked directly about thoughts of harming his wife or the other man","weight":3},{"item":"Asked about weapons, especially the gun","weight":3},{"item":"Took an alcohol history","weight":2},{"item":"Planned to tell a senior, safeguard the wife and secure the weapon","weight":2}]'::jsonb, '{"label":"Global risk-focused history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-125', 'History: sudden voices after a death in the family', 'Ms Kavita Yadav, 23, from a village near Varanasi, became disturbed five days after her father died. Take a history from her and screen for causes.', 420, '[{"item":"Approached gently and acknowledged her loss","weight":1},{"item":"Established the very sudden onset and timeline","weight":2},{"item":"Asked about hallucinations and beliefs","weight":1},{"item":"Asked about fever, headache, confusion and seizures to screen for organic causes","weight":2},{"item":"Asked about substances and medicines","weight":1},{"item":"Asked about previous episodes and family history","weight":1},{"item":"Asked about risk to self","weight":2}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-126', 'History: mood swings and voices together', 'Mr Sandeep Kumar, 34, has had three admissions with different diagnoses. Take a history that will settle the diagnosis by mapping his mood and psychotic symptoms over time.', 600, '[{"item":"Explained that the aim is to build a timeline","weight":1},{"item":"Explored each episode: mood state and psychotic symptoms","weight":2},{"item":"Asked about psychotic symptoms when mood was normal, and for how long","weight":3},{"item":"Estimated how much of the illness had mood episodes present","weight":2},{"item":"Asked about cannabis and its timing","weight":1},{"item":"Asked about current risk","weight":2},{"item":"Summarised the timeline back and named the likely diagnosis and look-alikes","weight":2}]'::jsonb, '{"label":"Global diagnostic history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-127', 'Witness history: fits that only happen at home', 'Ms Pooja Verma, 19, has ''fits'' several times a week despite two anti-epileptic medicines. Her EEG is normal. Take a history from her mother, who has seen many episodes.', 420, '[{"item":"Asked what happens before, during and after an episode","weight":2},{"item":"Asked about eyes open or closed and resistance to eye opening","weight":2},{"item":"Asked about duration, side-to-side movements and crying","weight":1},{"item":"Asked about injury, tongue biting site and incontinence","weight":1},{"item":"Asked about recovery and confusion afterwards","weight":1},{"item":"Asked sensitively about stresses at the time of onset","weight":2},{"item":"Acknowledged the mother''s fear and avoided saying ''she is faking''","weight":2}]'::jsonb, '{"label":"Global witness history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-128', 'History: the man who lost two days', 'Mr Arif Qureshi, 36, was found at Nagpur railway station with no memory of the last two days. He is from Hyderabad. Take a history.', 420, '[{"item":"Asked about the last clear memory and the first memory after","weight":2},{"item":"Checked identity and long-term memory are intact","weight":1},{"item":"Screened for head injury, seizures, alcohol, drugs and low sugar","weight":2},{"item":"Explored the stress just before the gap","weight":2},{"item":"Asked about previous episodes","weight":1},{"item":"Asked about suicide clearly","weight":2},{"item":"Planned physical examination and investigations before a final diagnosis","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-129', 'History: feeling like a robot', 'Ms Sneha Kapoor, 22, a law student in Pune, says she feels ''unreal''. Take a history.', 420, '[{"item":"Asked her to describe the experience in her own words","weight":1},{"item":"Distinguished feeling detached from self from the world feeling unreal","weight":2},{"item":"Checked that she knows it is not really so (intact reality testing)","weight":2},{"item":"Asked about onset, triggers and the cannabis episode","weight":1},{"item":"Screened for anxiety, low mood and psychotic symptoms","weight":1},{"item":"Asked about seizures and head injury","weight":1},{"item":"Reassured her that she is not losing her mind","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-130', 'History: heroin use in a truck driver', 'Mr Gurpreet Singh, 28, a truck driver from Amritsar, wants help to stop ''chitta''. Take a substance history.', 420, '[{"item":"Asked about substances used, route, amount and frequency","weight":2},{"item":"Asked about withdrawal symptoms and tolerance","weight":1},{"item":"Asked about injecting practices and needle sharing","weight":2},{"item":"Asked about past overdose","weight":2},{"item":"Asked about HIV, hepatitis testing and sexual risk","weight":1},{"item":"Asked about other drugs and alcohol","weight":1},{"item":"Asked about treatment goals and motivation","weight":1},{"item":"Remained non-judgemental","weight":1}]'::jsonb, '{"label":"Global substance history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-131', 'History: daily ganja and lost motivation', 'Mr Aditya Mishra, 20, an engineering student in Bhopal, has failed two semesters. His father thinks it is ''ganja''. Take a history from Aditya.', 420, '[{"item":"Asked about amount, frequency and time of first use in the day","weight":2},{"item":"Asked about withdrawal and loss of control","weight":1},{"item":"Asked about effects on study, sleep and mood","weight":1},{"item":"Asked about suspicious or unusual experiences","weight":2},{"item":"Asked about other substances and alcohol","weight":1},{"item":"Explored his own view without lecturing","weight":1},{"item":"Asked about family history of psychosis","weight":1}]'::jsonb, '{"label":"Global substance history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-132', 'History: cough syrup and sleeping pills', 'Ms Nandini Das, 21, a college student in Guwahati, was found drowsy in her hostel. She is now alert. Take a history of her use of medicines.', 420, '[{"item":"Asked about each substance, amount and source","weight":2},{"item":"Asked about withdrawal from both opioids and sedatives","weight":2},{"item":"Recognised the danger of combining opioids and sedatives","weight":2},{"item":"Asked about last night''s intent and current suicidal thoughts","weight":2},{"item":"Asked about mood and the break-up","weight":1},{"item":"Asked about alcohol and other drugs","weight":1},{"item":"Advised against stopping alprazolam suddenly","weight":1}]'::jsonb, '{"label":"Global substance history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-133', 'History: a street child who sniffs whitener', 'Raju, 13, was brought to a Mumbai child shelter by an outreach worker. He smells of solvent. Take a history from him. The shelter counsellor is present.', 420, '[{"item":"Introduced self simply and checked he is comfortable and fed","weight":1},{"item":"Used child-friendly language","weight":1},{"item":"Asked about solvent use: how often, why and what happens","weight":2},{"item":"Asked about accidents, fainting and breathing problems","weight":1},{"item":"Asked safely about family, abuse and why he left home","weight":2},{"item":"Asked about exploitation and safety now","weight":2},{"item":"Planned to inform child protection services as required","weight":2}]'::jsonb, '{"label":"Global child history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-134', 'History: gaming through the night', 'Aarav, 16, from Hyderabad, plays online games until 4 am and refuses to go to school. Take a history from Aarav.', 420, '[{"item":"Showed interest in the game before addressing problems","weight":1},{"item":"Asked about hours, control and attempts to cut down","weight":2},{"item":"Asked about priority over other activities and continuing despite harm","weight":2},{"item":"Asked about sleep, school and family conflict","weight":1},{"item":"Asked about mood, loneliness and bullying","weight":2},{"item":"Asked about self-harm","weight":1},{"item":"Explored what the game gives him","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-135', 'History: eating in secret at night', 'Mrs Meera Agarwal, 35, from Jaipur, was referred by her diabetologist because her sugars are poorly controlled and she ''cannot stop eating''. Take a history.', 420, '[{"item":"Asked about eating episodes, amount and speed","weight":2},{"item":"Asked about loss of control during episodes","weight":2},{"item":"Asked about compensatory behaviours","weight":2},{"item":"Asked about feelings after episodes","weight":1},{"item":"Asked about frequency and duration","weight":1},{"item":"Asked about mood and stress at home","weight":1},{"item":"Responded without shame or blame","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-136', 'History: vomiting after meals', 'Ms Tanya Malhotra, 19, a fashion student in Delhi, was referred by her dentist for enamel damage. Take a history.', 420, '[{"item":"Asked about binges and compensatory behaviours","weight":2},{"item":"Asked about frequency of vomiting and laxative use","weight":1},{"item":"Asked about shape and weight concern","weight":1},{"item":"Asked about palpitations, cramps, dizziness and fainting","weight":2},{"item":"Mentioned urgent blood tests for potassium and an ECG","weight":2},{"item":"Asked about self-harm and mood","weight":2},{"item":"Responded with warmth","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-137', 'History: a picky eater who is not growing', 'Ishaan, 10, from Bengaluru, eats only white rice, plain dosa and one brand of biscuits. His paediatrician is worried about his growth. Take a history from his father.', 420, '[{"item":"Asked about foods eaten and avoided and reasons (texture, fear, interest)","weight":2},{"item":"Asked about the choking episode and fear of choking","weight":1},{"item":"Asked whether he worries about body shape or weight","weight":2},{"item":"Asked about growth, energy and physical health","weight":1},{"item":"Asked about development and sensory sensitivities","weight":1},{"item":"Asked about mealtime conflict and family coping","weight":1},{"item":"Considered autism and planned a growth and nutrition check","weight":1}]'::jsonb, '{"label":"Global child history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-138', 'History: low after losing a job', 'Mr Prasanna Hegde, 41, a software manager in Bengaluru, was laid off six weeks ago. His wife asked him to see someone. Take a history.', 420, '[{"item":"Explored the stressor and its meaning","weight":1},{"item":"Asked about core depressive symptoms in detail","weight":2},{"item":"Noted preserved enjoyment and functioning","weight":2},{"item":"Established onset close to the stressor","weight":1},{"item":"Asked about suicide clearly","weight":2},{"item":"Asked about alcohol","weight":1},{"item":"Explained the likely picture and what to watch for","weight":1}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-139', 'History through a Nepali interpreter: a rescued survivor', 'Ms Maya, 19, from Nepal, was rescued from a trafficking ring in Kolkata and is in a shelter. She speaks only Nepali. A female interpreter is available. Take a history of her current difficulties.', 600, '[{"item":"Briefed the interpreter before starting: confidentiality, word-for-word, no advice","weight":2},{"item":"Arranged seating and spoke directly to Maya in short sentences","weight":2},{"item":"Explained who they are, why they are there and that she can stop at any time","weight":2},{"item":"Did not ask for details of the abuse","weight":2},{"item":"Asked about current symptoms: sleep, nightmares, fear, numbness, shame, pain","weight":2},{"item":"Asked about suicide clearly and safely","weight":2},{"item":"Asked about her immediate safety concerns and wishes","weight":1},{"item":"Debriefed the interpreter afterwards","weight":1}]'::jsonb, '{"label":"Global trauma-informed interview competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-140', 'History: a boy with sudden noises and jerks', 'Kabir, 11, blinks hard, jerks his neck and makes throat-clearing noises. His mother has brought him from Lucknow. Take a history from his mother.', 420, '[{"item":"Asked about types of movements and sounds and when they began","weight":2},{"item":"Asked about the urge before tics and ability to suppress","weight":2},{"item":"Asked about duration (more than a year) and waxing and waning","weight":1},{"item":"Asked about attention, hyperactivity and checking behaviours","weight":2},{"item":"Asked about impact at school and teasing","weight":1},{"item":"Asked about family history","weight":1},{"item":"Explained that tics are not deliberate","weight":1}]'::jsonb, '{"label":"Global child history competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-141', 'History: tired all day and snoring at night', 'Mr Mahesh Patel, 52, a businessman from Surat, was told he has depression because he is tired and irritable. Take a sleep history.', 420, '[{"item":"Asked about sleep pattern and daytime sleepiness","weight":2},{"item":"Asked about snoring, choking and witnessed pauses in breathing","weight":2},{"item":"Asked about falling asleep while driving","weight":2},{"item":"Asked about morning headaches","weight":1},{"item":"Asked about weight, blood pressure, alcohol and sedatives","weight":1},{"item":"Screened for core depressive symptoms","weight":1},{"item":"Suggested a sleep study and advised on driving safety","weight":2}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-142', 'History through a Bhojpuri interpreter: fear or delusion?', 'Mr Ramesh Paswan, 30, a construction worker from Bihar living in Pune, was brought by his contractor because he ''thinks people are after him''. He speaks Bhojpuri. A hospital interpreter is present. Take a history.', 420, '[{"item":"Worked with the interpreter properly: short phrases, speaking to the patient","weight":2},{"item":"Asked about the facts behind the fear: what happened, to whom, when","weight":2},{"item":"Asked whether the fear could be checked by others","weight":1},{"item":"Screened for features of delusion: fixed belief, special meaning, cameras, thought interference","weight":2},{"item":"Asked about mood, sleep and homesickness","weight":1},{"item":"Asked about wages and working conditions (social stress)","weight":1},{"item":"Avoided labelling realistic fear as paranoia","weight":2}]'::jsonb, '{"label":"Global history-taking competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-143', 'MSE: describe appearance and behaviour', 'Spend three minutes talking with Mr Gopal, 58, on the ward. Then describe his appearance and behaviour to the examiner. Describe only what you observed.', 420, '[{"item":"Introduced self and asked permission to talk","weight":1},{"item":"Described clothing, grooming and hygiene objectively","weight":2},{"item":"Described posture, eye contact and movement","weight":2},{"item":"Described rapport and attitude (cooperative, guarded, hostile)","weight":1},{"item":"Noted any abnormal movements or repetitive behaviour","weight":1},{"item":"Avoided interpretation such as ''he looks depressed'' in this section","weight":2},{"item":"Presented in a clear, ordered way","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-144', 'MSE: speech in a man who will not stop talking', 'Mr Ronak Shah, 33, was admitted last night. Talk with him for four minutes and then describe his speech and the form of his thought to the examiner.', 420, '[{"item":"Let him talk at first to sample speech","weight":1},{"item":"Described rate, volume and difficulty interrupting (pressure of speech)","weight":2},{"item":"Described the jumps between topics with understandable links (flight of ideas)","weight":2},{"item":"Noted rhyming or punning (clang associations)","weight":1},{"item":"Separated speech description from thought form","weight":1},{"item":"Tested whether he could be redirected","weight":1},{"item":"Remained calm and courteous","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-145', 'MSE: mood and affect are not the same', 'Ms Lalitha, 34, has been referred by her gynaecologist. Assess her mood and affect and present them to the examiner.', 420, '[{"item":"Asked about mood in her own words","weight":1},{"item":"Asked for a rating, such as out of ten","weight":1},{"item":"Observed affect: range, reactivity and tearfulness","weight":2},{"item":"Noted the mismatch between her words and her affect","weight":2},{"item":"Explored the topic that brought tears with sensitivity","weight":1},{"item":"Recorded subjective and objective parts separately","weight":2}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-146', 'MSE: the man who answers after a long silence', 'Mr Subramaniam, 61, a retired clerk in Madurai, has been ''very quiet'' for a month. Conduct a mental state examination focusing on behaviour, speech, mood and thought content.', 420, '[{"item":"Allowed time for answers and did not rush","weight":2},{"item":"Described slowed movements, long answer delay and reduced speech","weight":2},{"item":"Assessed mood and affect","weight":1},{"item":"Explored guilt and worthlessness and judged whether they are delusional","weight":2},{"item":"Elicited the nihilistic belief about his body","weight":2},{"item":"Asked about suicide clearly","weight":2},{"item":"Noted poor food intake as a physical risk","weight":2}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-147', 'MSE: obsession, delusion or overvalued idea?', 'Ms Mehak Arora, 23, fears she is contaminated. Explore the belief and tell the examiner whether it is an obsession, a delusion or an overvalued idea, with your reasons.', 420, '[{"item":"Asked whether the thought feels like her own","weight":2},{"item":"Asked whether she tries to resist it","weight":2},{"item":"Assessed how certain she is and whether evidence could change her view","weight":2},{"item":"Asked whether the thought is unwanted and distressing","weight":1},{"item":"Asked about related actions such as washing","weight":1},{"item":"Gave a reasoned conclusion with the features that separate the three","weight":2}]'::jsonb, '{"label":"Global phenomenology competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-148', 'MSE: someone is putting thoughts in my head', 'Mr Jayesh Patil, 26, says his thoughts ''are not safe''. Explore his experiences and describe them to the examiner using the correct terms.', 420, '[{"item":"Used open questions, then specific clarifying questions","weight":1},{"item":"Elicited thought insertion: thoughts that are not his own placed into his mind","weight":2},{"item":"Elicited thought withdrawal: thoughts taken out","weight":2},{"item":"Elicited thought broadcast: others can hear or know his thoughts","weight":2},{"item":"Distinguished these from ordinary intrusive thoughts","weight":1},{"item":"Assessed distress and any action on commands","weight":1},{"item":"Used correct terms when presenting","weight":1}]'::jsonb, '{"label":"Global phenomenology competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-149', 'MSE: my arm moves but it is not me', 'Ms Noor Fatima, 29, from Aligarh, says ''someone controls me''. Explore the experiences and present them to the examiner.', 420, '[{"item":"Asked about feelings of being controlled in clear words","weight":1},{"item":"Elicited made actions: movements controlled by an outside force","weight":2},{"item":"Elicited made feelings: emotions imposed from outside","weight":2},{"item":"Elicited somatic passivity: bodily sensations imposed from outside","weight":2},{"item":"Explored her explanation and cultural context","weight":1},{"item":"Distinguished passivity from ordinary religious beliefs and dissociative possession states","weight":2},{"item":"Assessed risk towards the neighbour","weight":1}]'::jsonb, '{"label":"Global phenomenology competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-150', 'MSE: real voice or inner voice?', 'Ms Asha Kumari, 32, says she ''hears her dead son''. Explore the experience and tell the examiner whether it is a true hallucination, a pseudohallucination or something else.', 420, '[{"item":"Approached the grief gently first","weight":1},{"item":"Asked where the voice seems to come from: inside or outside the head","weight":2},{"item":"Asked whether it seems as real as a real voice","weight":1},{"item":"Asked whether she knows it comes from her own mind","weight":2},{"item":"Asked when it happens and how she feels about it","weight":1},{"item":"Screened for other psychotic symptoms","weight":1},{"item":"Asked about mood, guilt and suicide","weight":2}]'::jsonb, '{"label":"Global phenomenology competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-151', 'MSE: the quiet young man on the rehab ward', 'Mr Anil, 30, has had schizophrenia for eight years and is at a day centre in Thrissur. Assess him for negative symptoms and present your findings.', 420, '[{"item":"Noted poverty of speech (alogia)","weight":1},{"item":"Noted blunted affect: reduced facial expression and vocal tone","weight":2},{"item":"Asked about motivation and daily activity (avolition)","weight":2},{"item":"Asked about enjoyment (anhedonia) and social contact (asociality)","weight":2},{"item":"Screened for depression, which can look similar","weight":2},{"item":"Considered medicine side effects such as slowness and stiffness","weight":1},{"item":"Presented findings using correct terms","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-152', 'MSE: the intoxicated man in casualty', 'Mr Santosh, 40, was brought to a Kolkata emergency room by police after a fight. He smells of alcohol. The medical team wants your view. Do a mental state examination and report what you can and cannot conclude.', 420, '[{"item":"Checked safety: staff present, exit clear","weight":1},{"item":"Checked medical priorities: head injury, glucose, airway","weight":3},{"item":"Described level of consciousness and speech","weight":2},{"item":"Assessed orientation","weight":1},{"item":"Noted the forehead cut and the vomiting","weight":2},{"item":"Recorded the hopeless comment and planned to reassess when sober","weight":2},{"item":"Explained the limits of an MSE during intoxication","weight":1}]'::jsonb, '{"label":"Global emergency assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-153', 'MSE: a six-year-old through play', 'Diya, 6, has had nightmares and bedwetting since a fire in her Ahmedabad apartment block. Spend five minutes with her using the toys provided, then report her mental state.', 420, '[{"item":"Got down to the child''s level and let her approach","weight":2},{"item":"Used play and drawing rather than direct questions","weight":2},{"item":"Observed separation, relating and attachment behaviour","weight":1},{"item":"Observed play themes such as repetitive rescue play","weight":2},{"item":"Noted startle and arousal","weight":1},{"item":"Assessed speech and development for age","weight":1},{"item":"Reported findings in plain terms","weight":1}]'::jsonb, '{"label":"Global child mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-154', 'MSE: a young man with intellectual disability', 'Mr Rahul, 22, has moderate intellectual disability. His care home in Pune reports he has become aggressive in the last month. His key worker is present. Assess his mental state.', 420, '[{"item":"Introduced self simply and involved the key worker","weight":1},{"item":"Used short sentences, pictures and yes or no questions","weight":2},{"item":"Observed behaviour, including holding his cheek","weight":2},{"item":"Considered pain and physical causes first (for example dental pain)","weight":3},{"item":"Assessed mood using simple aids","weight":1},{"item":"Asked the key worker about change from his usual baseline","weight":2},{"item":"Avoided putting the change down to his disability alone","weight":2}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-155', 'MSE: the cognitive section at the bedside', 'Mrs Rukmini, 70, is on a medical ward in Hyderabad. Complete the cognitive part of the mental state examination: orientation, attention, concentration and memory.', 420, '[{"item":"Explained the purpose and asked permission","weight":1},{"item":"Tested orientation to time, place and person","weight":2},{"item":"Tested attention, for example months backwards or digit span","weight":2},{"item":"Registered three items and tested recall after a delay","weight":2},{"item":"Was tactful about her embarrassment","weight":1},{"item":"Summarised findings accurately","weight":1}]'::jsonb, '{"label":"Global cognitive assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-156', 'MSE: present a full mental state to the consultant', 'You have just interviewed Ms Shalini, 38 (the examiner will play her briefly for any checks). Present her full mental state examination to the consultant in under four minutes, then answer questions.', 600, '[{"item":"Presented in the standard order: appearance, behaviour, speech, mood, affect, thought, perception, cognition, insight","weight":2},{"item":"Described observations rather than opinions","weight":1},{"item":"Separated form and content of thought","weight":1},{"item":"Described the hallucination accurately (third person, commentary)","weight":2},{"item":"Included risk to self and others in the MSE","weight":2},{"item":"Assessed insight in a graded way","weight":1},{"item":"Answered the risk and differential questions sensibly","weight":2},{"item":"Kept to time and was organised","weight":1}]'::jsonb, '{"label":"Global case presentation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-157', 'MSE: the woman who says she is already dead', 'Mrs Kamala, 74, from Coimbatore, has stopped eating. Her daughter says ''she talks strange''. Conduct a mental state examination, then tell the examiner your concerns and immediate plan.', 600, '[{"item":"Approached slowly and respectfully","weight":1},{"item":"Elicited the nihilistic belief about her body","weight":2},{"item":"Elicited guilt and catastrophe themes","weight":1},{"item":"Explored suicide in a way that fits her belief","weight":2},{"item":"Asked about food and fluid intake","weight":3},{"item":"Checked orientation to look for delirium","weight":1},{"item":"Stated the urgency: dehydration and severe psychotic depression","weight":2},{"item":"Proposed medical review and urgent psychiatric treatment","weight":2}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-158', 'MSE: tics, stereotypies or mannerisms?', 'The examiner will act out three repetitive movements seen in three patients. Describe each one and name it, giving your reasons.', 420, '[{"item":"Asked about purpose, urge and control for each","weight":2},{"item":"Named the rhythmic, purposeless movement a stereotypy","weight":2},{"item":"Named the odd, stylised version of a normal action a mannerism","weight":2},{"item":"Named the sudden movement with an urge and brief suppression a tic","weight":2},{"item":"Named tardive dyskinesia as the look-alike on antipsychotics","weight":1},{"item":"Explained the distinctions clearly","weight":1}]'::jsonb, '{"label":"Global phenomenology competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-159', 'MSE: an anxious patient in the clinic', 'Mr Imtiaz, 29, a call centre worker, is waiting for his first appointment. Talk to him for three minutes and describe the anxiety you observe.', 420, '[{"item":"Greeted him and put him at ease","weight":1},{"item":"Described motor signs: restlessness, tremor, fidgeting","weight":2},{"item":"Described autonomic signs: sweating, sighing","weight":2},{"item":"Noted reassurance seeking","weight":1},{"item":"Described mood and affect accurately (anxious, not depressed)","weight":2},{"item":"Used calm, reassuring communication","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-160', 'MSE through a Tamil interpreter', 'Mr Murugan, 45, from Tirunelveli, was admitted to a Delhi hospital after a road accident and is now behaving oddly. He speaks only Tamil. A hospital interpreter is present. Conduct a focused MSE.', 420, '[{"item":"Briefed the interpreter to translate exactly, including confused or odd words","weight":3},{"item":"Spoke to the patient, not the interpreter, in short questions","weight":2},{"item":"Asked the interpreter whether the speech is clear or jumbled in Tamil","weight":2},{"item":"Assessed orientation and attention","weight":2},{"item":"Elicited visual hallucinations and observed picking behaviour","weight":1},{"item":"Recognised a likely delirium after injury","weight":2},{"item":"Noted cultural and language limits in the report","weight":1}]'::jsonb, '{"label":"Global interview with an interpreter competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-161', 'MSE: the patient who will not speak', 'Ms Saraswati, 27, has not spoken for three days. She is in the emergency room in Bhubaneswar. Assess her and tell the examiner the possible causes and what you would look for.', 600, '[{"item":"Explained what they were doing even though she did not reply","weight":1},{"item":"Observed posture, staring, response to the examiner and eye tracking","weight":2},{"item":"Tested for posturing, waxy flexibility, resistance and echo phenomena","weight":2},{"item":"Asked the examiner for the history from the family","weight":1},{"item":"Considered catatonia, severe depression, organic causes and dissociation","weight":2},{"item":"Noted dehydration and a fast pulse as physical risks","weight":2},{"item":"Mentioned a lorazepam challenge and checks for NMS and encephalitis","weight":2}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-162', 'MSE: the quiet patient after surgery', 'Mr Chandrakant, 78, had hip surgery four days ago in a Pune hospital. Nurses think he is ''depressed'' because he is withdrawn. Conduct an MSE and give your opinion.', 420, '[{"item":"Assessed level of alertness","weight":2},{"item":"Tested attention with a simple task","weight":2},{"item":"Assessed orientation","weight":1},{"item":"Asked about mood and depressive thoughts","weight":1},{"item":"Asked about his usual state before surgery","weight":2},{"item":"Concluded hypoactive delirium rather than depression","weight":2},{"item":"Suggested medical causes to check, including opioids, infection and urine retention","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-163', 'MSE: sort the observations into the right sections', 'The examiner will read out ten observations about a patient. Say which section of the MSE each belongs to, and correct any wrongly worded findings.', 420, '[{"item":"Placed appearance, speech and behaviour items correctly","weight":1},{"item":"Separated mood (her words) from affect (observed)","weight":2},{"item":"Placed the radio messages under thought content","weight":1},{"item":"Placed the man by the window under perception","weight":1},{"item":"Called item 6 circumstantiality, a disorder of thought form","weight":2},{"item":"Placed item 8 under insight","weight":1},{"item":"Reworded item 10 to person-first language","weight":1},{"item":"Described item 3 as incongruent affect","weight":1}]'::jsonb, '{"label":"Global case-sheet writing competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-164', 'MSE: a woman in a trance in the emergency room', 'Mrs Lakshmi, 25, was brought from a village near Warangal. Her family says a goddess comes on her. She is swaying and speaking in a different voice. Assess her and report your findings.', 420, '[{"item":"Ensured safety and stayed calm and respectful of beliefs","weight":1},{"item":"Observed the episode: responsiveness, voice change, movement","weight":2},{"item":"Assessed between episodes for psychotic symptoms","weight":2},{"item":"Checked for seizure features and physical causes","weight":1},{"item":"Asked privately about stresses, including violence at home","weight":3},{"item":"Asked about safety and suicide","weight":2},{"item":"Summarised as likely dissociative trance linked to stress","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-165', 'MSE: a man who fills memory gaps', 'Mr Thomas, 55, a former bus conductor in Kochi, has drunk heavily for 25 years. He is on the medical ward after a fall. Assess his memory and thinking.', 420, '[{"item":"Assessed alertness and attention","weight":1},{"item":"Tested new learning and recall","weight":2},{"item":"Asked about recent events and noted confident false memories","weight":2},{"item":"Tested older memories","weight":1},{"item":"Distinguished confabulation from lying","weight":2},{"item":"Linked findings to thiamine deficiency and alcohol","weight":2},{"item":"Mentioned thiamine treatment and checking for Wernicke features","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-166', 'MSE: crying that comes from nowhere after a stroke', 'Mr Iqbal, 63, had a stroke two months ago. His family say he cries all the time. Assess his mood and affect and explain your findings.', 420, '[{"item":"Asked about the crying episodes: triggers, length and control","weight":2},{"item":"Asked whether the feeling inside matches the crying","weight":2},{"item":"Screened for core depressive symptoms","weight":2},{"item":"Asked about suicide","weight":1},{"item":"Considered post-stroke depression as a separate possibility","weight":1},{"item":"Explained the finding with sensitivity","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-167', 'MSE: insects under the skin', 'Mrs Saroj, 60, from Indore, was referred by a dermatologist. She has brought a small box of ''insects'' from her skin. Assess her beliefs and screen for causes.', 420, '[{"item":"Looked at the specimen respectfully","weight":1},{"item":"Explored the belief, certainty and evidence","weight":2},{"item":"Asked about harmful self-treatment such as kerosene","weight":2},{"item":"Asked about other psychotic symptoms","weight":1},{"item":"Screened for medical causes: diabetes control, kidney, thyroid, B12, drugs","weight":2},{"item":"Asked about mood","weight":1},{"item":"Avoided argument and kept the dermatologist involved","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-168', 'MSE: a teenager in long sleeves in June', 'Ishita, 15, was brought to clinic in Jaipur because her grades dropped. Do a brief mental state examination and report it.', 420, '[{"item":"Explained confidentiality and its limits","weight":2},{"item":"Observed appearance and behaviour, including the sleeves","weight":2},{"item":"Assessed mood and affect","weight":1},{"item":"Asked about self-harm in a calm, direct way","weight":2},{"item":"Asked about suicidal thoughts separately","weight":2},{"item":"Asked about home and school stresses","weight":1},{"item":"Reported findings without judgement","weight":1}]'::jsonb, '{"label":"Global adolescent mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-169', 'MSE: testing abstract thinking fairly', 'Mr Bhola, 50, a farmer from a village near Ujjain, studied up to class 4. The team wants abstract thinking assessed. Do it fairly and report.', 420, '[{"item":"Asked about education and language before testing","weight":2},{"item":"Chose a familiar local proverb rather than an English one","weight":2},{"item":"Used a similarities task","weight":1},{"item":"Asked a practical judgement question","weight":1},{"item":"Interpreted results in light of schooling","weight":2},{"item":"Did not label him as having concrete thinking unfairly","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-170', 'MSE: grandiose beliefs without an argument', 'Mr Devendra, 37, a clerk in Raipur, says he is ''the next Prime Minister''. Explore this belief and describe it.', 420, '[{"item":"Showed interest without laughing or arguing","weight":2},{"item":"Explored the belief and its basis","weight":1},{"item":"Assessed conviction and whether he could consider other explanations","weight":2},{"item":"Asked about plans and actions based on the belief","weight":2},{"item":"Asked about sleep and mood","weight":1},{"item":"Identified risks: trip to Delhi, job loss, conflict","weight":1}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-171', 'MSE: a new mother who seems confused', 'Mrs Priyanka, 26, delivered her first baby eight days ago in a Lucknow hospital. Her mother says she is ''not herself''. Conduct an MSE and tell the examiner your concerns and plan.', 600, '[{"item":"Approached gently and observed perplexity and lability","weight":2},{"item":"Assessed orientation","weight":1},{"item":"Elicited the belief about the baby","weight":2},{"item":"Asked about voices and their content","weight":2},{"item":"Asked directly and kindly about thoughts of harming the baby and herself","weight":3},{"item":"Asked about past mood episodes","weight":1},{"item":"Stated that this is an emergency needing same-day admission, ideally to a mother and baby unit","weight":3}]'::jsonb, '{"label":"Global mental state examination competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-172', 'MSE: on a video call', 'You are doing a follow-up video consultation with Ms Rehana, 40, in a village in Kashmir. The connection is patchy. Assess her mental state and say what you could not assess.', 420, '[{"item":"Confirmed identity and location at the start","weight":2},{"item":"Asked about privacy and whether she can speak freely","weight":2},{"item":"Observed what was visible: face, grooming, eye contact, affect","weight":1},{"item":"Checked speech quality versus connection problems","weight":1},{"item":"Asked about mood and risk","weight":2},{"item":"Recorded what could not be assessed, such as gait and fine tremor","weight":1},{"item":"Arranged a safer time to talk","weight":1}]'::jsonb, '{"label":"Global telepsychiatry assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-173', 'Risk: following up a screening form answer', 'At a diabetes camp in Rajkot, Mrs Hansa Desai, 50, ticked ''more than half the days'' for the item about being better off dead on a depression questionnaire. Follow this up.', 420, '[{"item":"Raised the answer openly and kindly","weight":1},{"item":"Asked what she meant by the answer","weight":2},{"item":"Asked about thoughts of ending her life and any plans","weight":2},{"item":"Asked about intent and past attempts","weight":1},{"item":"Asked about protective factors","weight":1},{"item":"Asked about other depressive symptoms","weight":1},{"item":"Agreed a clear next step and gave a helpline number","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-174', 'Risk: a farmer after crop failure', 'Mr Dnyaneshwar Jadhav, 46, a cotton farmer in Yavatmal, was brought by the ASHA worker after his crop failed for the second year. Assess his suicide risk.', 420, '[{"item":"Showed respect and understanding of the farming crisis","weight":1},{"item":"Asked directly about suicidal thoughts and plans","weight":2},{"item":"Asked about access to pesticide and other means","weight":3},{"item":"Asked about alcohol use","weight":2},{"item":"Asked about the recent suicide in the village (exposure)","weight":1},{"item":"Explored debt, shame and supports","weight":1},{"item":"Agreed means safety, such as locked storage held by someone else","weight":2},{"item":"Linked to practical help: debt advice, farmer helplines, local health worker","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-175', 'Risk: a junior doctor who says she is fine', 'Dr Ayesha Siddiqui, 27, a second-year surgery resident in Hyderabad, was referred by her head of department after crying in theatre. Assess her mental state and risk.', 420, '[{"item":"Addressed confidentiality and fear of career impact early","weight":2},{"item":"Treated her as a patient, not a colleague, without over-familiarity","weight":1},{"item":"Asked about suicidal thoughts and research into methods","weight":2},{"item":"Asked directly about access to drugs at work","weight":3},{"item":"Asked about workplace bullying and hours","weight":1},{"item":"Assessed depressive symptoms","weight":1},{"item":"Agreed removal of the vials and urgent follow-up","weight":2},{"item":"Discussed time off work and support","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-176', 'Risk: an older man who has stopped looking after himself', 'Mr Jagdish Prasad, 79, lives alone in Patna. A neighbour called the clinic because he has not been out for a week. Assess him at home.', 420, '[{"item":"Assessed home conditions, food, hygiene and medicines respectfully","weight":2},{"item":"Asked about weight loss and eating","weight":1},{"item":"Asked about mood, grief and loneliness","weight":2},{"item":"Screened memory","weight":1},{"item":"Asked about suicidal thoughts and passive death wishes","weight":2},{"item":"Explored stopping his tablets as possible indirect self-harm","weight":1},{"item":"Agreed practical help with his consent: meals, medicines, contact with son","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-177', 'Risk: a mother who says she will take the children with her', 'Mrs Rani, 31, from a slum settlement in Chennai, has severe depression. Her husband left her with two children aged 6 and 3. She says she cannot go on. Assess risk to her and to the children.', 600, '[{"item":"Asked about suicidal thoughts clearly","weight":2},{"item":"Asked whether her thoughts include the children","weight":3},{"item":"Explored the ''altruistic'' reasoning without judgement","weight":2},{"item":"Assessed plan, timing and intent","weight":2},{"item":"Assessed psychotic features","weight":1},{"item":"Did not leave her alone with the children while risk is high","weight":3},{"item":"Involved senior staff and child protection, with an explanation to her","weight":2},{"item":"Identified supports such as the aunt","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-178', 'Risk: domestic violence after she tries to leave', 'Mrs Sunita, 34, attends a psychiatric OPD in Delhi with anxiety. She says her husband ''gets angry''. Assess her risk and make a safety plan.', 600, '[{"item":"Made sure she was seen alone","weight":2},{"item":"Asked about violence directly and believed her","weight":1},{"item":"Asked about strangulation, threats to kill, weapons and escalation","weight":3},{"item":"Recognised pregnancy and separation as high-risk times","weight":2},{"item":"Asked about children''s safety","weight":2},{"item":"Made a safety plan: safe place, documents, phone numbers","weight":2},{"item":"Gave information on the women''s helpline 181, police 112 and the Protection Officer","weight":1},{"item":"Respected her choices while being clear about danger","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-179', 'Risk: a man who will not let go of his former colleague', 'Mr Varun, 35, an IT engineer in Bengaluru, was referred by HR after a colleague complained. Assess his beliefs and behaviour, and the risk he poses.', 600, '[{"item":"Explored the belief and his relationship with her calmly","weight":2},{"item":"Asked about contact behaviours: messages, following, waiting outside","weight":2},{"item":"Asked about anger, jealousy and threats","weight":2},{"item":"Took the ''no one should have her'' statement seriously and explored it","weight":3},{"item":"Asked about weapons, violence history and alcohol","weight":1},{"item":"Considered the differential: erotomanic delusion or a rejected stalker","weight":2},{"item":"Planned to inform a senior and consider warning the victim","weight":2}]'::jsonb, '{"label":"Global violence risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-180', 'Risk: a constable who carries a service weapon', 'Head Constable Rajpal Singh, 44, from Haryana, was sent by his superintendent after drinking on duty. Assess his mental state and risk.', 420, '[{"item":"Explained confidentiality and its limits honestly","weight":2},{"item":"Asked about suicidal thoughts and rehearsal with the weapon","weight":3},{"item":"Asked about alcohol use and drinking on duty","weight":2},{"item":"Asked about grief and depressive symptoms","weight":1},{"item":"Asked about anger towards others","weight":1},{"item":"Advised temporary removal of weapon access through the proper channel","weight":3},{"item":"Arranged urgent follow-up and support","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-181', 'Risk: a school bus driver who drinks', 'Mr Vijay, 50, drives a school bus in Coimbatore. He attends for ''stomach pain''. On questioning he drinks every morning. Discuss the risk with him and what must happen next.', 420, '[{"item":"Clarified the drinking pattern and morning use","weight":2},{"item":"Explained the danger to children on the bus clearly","weight":2},{"item":"Advised him not to drive until safe","weight":2},{"item":"Discussed treatment for dependence and safe withdrawal","weight":1},{"item":"Explained the limits of confidentiality where others are at serious risk","weight":2},{"item":"Tried to gain his agreement before any disclosure","weight":1},{"item":"Documented and planned senior advice","weight":1}]'::jsonb, '{"label":"Global risk and ethics competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-182', 'Risk: a young woman with intellectual disability and a new ''friend''', 'Ms Sapna, 20, has mild intellectual disability and lives with her mother in Vadodara. Her mother says an older man gives her gifts and phone credit. Speak with Sapna.', 420, '[{"item":"Used simple language and checked understanding","weight":2},{"item":"Asked about the friendship openly without judgement","weight":1},{"item":"Asked about secrets, gifts and being asked to keep quiet","weight":2},{"item":"Asked gently about touching and what happened in the room","weight":2},{"item":"Assessed her understanding of consent and safety","weight":2},{"item":"Recognised possible sexual abuse and grooming","weight":2},{"item":"Explained next steps, including reporting, in simple words","weight":2}]'::jsonb, '{"label":"Global safeguarding assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-183', 'Risk: a patient who wants to leave the ward at night', 'It is 11 pm. Mr Kishore, 28, a voluntary patient on an open ward in Kochi, is standing at the door with his bag. The nurse has asked you to speak with him.', 420, '[{"item":"Approached calmly and introduced self","weight":1},{"item":"Asked why he wants to leave now","weight":2},{"item":"Assessed current mood and suicidal thoughts","weight":2},{"item":"Considered his status and rights as an independent patient","weight":1},{"item":"Offered practical solutions","weight":1},{"item":"Agreed a plan and informed the team","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-184', 'Risk: a college student who cuts', 'Ms Pallavi, 19, a B.Com student in Indore, was sent by the college counsellor after a friend saw cuts on her thighs. Assess her.', 420, '[{"item":"Responded calmly and without disgust","weight":2},{"item":"Asked what the self-harm does for her (its function)","weight":2},{"item":"Asked about frequency, wound care and infection","weight":1},{"item":"Asked separately about suicidal thoughts","weight":2},{"item":"Asked about stresses and supports","weight":1},{"item":"Discussed safer coping alternatives without demanding she stop at once","weight":1},{"item":"Agreed a follow-up plan","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-185', 'Risk: chronic suicidal thoughts and a new crisis', 'Ms Rhea, 24, has emotionally unstable personality disorder and is known to the Mumbai service. She attends casualty saying she wants to die. Assess her and decide on a plan.', 600, '[{"item":"Validated her distress without dismissing her","weight":2},{"item":"Clarified her usual baseline of suicidal thinking","weight":2},{"item":"Asked what is different now (acute factors)","weight":2},{"item":"Asked about plans, means and intent","weight":2},{"item":"Explored skills and supports that have helped before","weight":1},{"item":"Discussed admission honestly, including past effects","weight":1},{"item":"Agreed a collaborative crisis plan with follow-up","weight":2}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-186', 'Risk: present a formulation to the consultant', 'You assessed Mr Haroon, 42, after he was found standing on a railway bridge in Lucknow. Present your risk formulation and plan to the consultant (the examiner).', 600, '[{"item":"Summarised the event and intent","weight":1},{"item":"Grouped factors: background (static), current (changeable) and protective","weight":2},{"item":"Explained why these factors matter for this man","weight":2},{"item":"Described likely scenarios: what could raise risk soon","weight":2},{"item":"Gave a plan linked to each changeable factor","weight":2},{"item":"Avoided relying on a single risk label","weight":1},{"item":"Included follow-up, family and means","weight":1}]'::jsonb, '{"label":"Global risk formulation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-187', 'Risk: a teenager being blackmailed with photos', 'Arjun, 16, from Nagpur, was brought by his mother because he stopped eating and locks himself in his room. Speak with him alone.', 420, '[{"item":"Explained confidentiality and its limits for a minor","weight":1},{"item":"Created safety for disclosure with a non-judgemental stance","weight":2},{"item":"Asked about suicidal thoughts directly","weight":3},{"item":"Recognised sextortion as a crime against him, not his fault","weight":2},{"item":"Advised not to pay further and to keep evidence","weight":1},{"item":"Discussed reporting to the cyber crime helpline 1930 and police","weight":2},{"item":"Planned how to tell his parents with support","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-188', 'Risk: an older man after a cancer diagnosis', 'Mr Srinivasan, 68, was told last week at a Chennai cancer hospital that he has spread prostate cancer. The oncologist is worried after he said ''I will not suffer like my brother''. Assess him.', 420, '[{"item":"Explored his understanding of the illness and fears","weight":2},{"item":"Asked about suicidal thoughts, plan and timing","weight":2},{"item":"Asked about access to the stored morphine","weight":2},{"item":"Screened for depression","weight":1},{"item":"Addressed fears of pain and burden with honest information about palliative care","weight":2},{"item":"Discussed involving his wife","weight":1},{"item":"Agreed safe disposal of the stored tablets","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-189', 'Risk: the week after discharge', 'Mr Abhishek, 33, was discharged five days ago from a Kolkata psychiatric ward after a suicide attempt. This is his first follow-up. Review him.', 420, '[{"item":"Recognised the period after discharge as high risk","weight":2},{"item":"Asked about current suicidal thoughts and plans","weight":2},{"item":"Asked about means still kept at home","weight":2},{"item":"Asked about medicine adherence and side effects","weight":1},{"item":"Asked about isolation and changes since discharge","weight":1},{"item":"Updated the safety plan","weight":1},{"item":"Arranged closer follow-up","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-190', 'Risk: a transgender young person thrown out of home', 'Ms Ananya, 19, a trans woman, was brought by a friend to a Pune clinic after being thrown out by her family. Assess her mental state and risk.', 420, '[{"item":"Asked her name and pronouns and used them","weight":2},{"item":"Asked about rejection, discrimination and violence","weight":2},{"item":"Asked about suicidal thoughts and the past attempt","weight":3},{"item":"Asked about housing and immediate safety","weight":1},{"item":"Identified supports: friend, community groups","weight":1},{"item":"Avoided treating gender identity as the problem","weight":2},{"item":"Linked to practical help such as a shelter for transgender persons","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-191', 'Risk: a remand prisoner in his first week', 'You are the visiting psychiatrist at a central jail. Mr Sameer, 23, was remanded four days ago on a theft charge. The jail warden asked you to see him because he is not eating. Assess him.', 600, '[{"item":"Explained their role and confidentiality limits in custody","weight":2},{"item":"Recognised the early days of custody as high risk","weight":2},{"item":"Asked directly about suicidal thoughts and plans","weight":3},{"item":"Asked about substance withdrawal","weight":1},{"item":"Asked about family contact, legal help and fears","weight":1},{"item":"Recommended increased observation and removal of ligature risks with jail staff","weight":2},{"item":"Planned treatment, follow-up and contact with family and legal aid","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-192', 'Risk: a man demanding tablets in the OPD', 'Mr Vikram, 36, is shouting at the registration desk of a district hospital in Meerut, demanding ''the sleeping tablets'' he got before. Speak with him.', 420, '[{"item":"Kept a safe distance and positioned near an exit","weight":2},{"item":"Used a calm voice, open posture and his name","weight":1},{"item":"Acknowledged his distress and need","weight":2},{"item":"Assessed for withdrawal and risk of seizures","weight":2},{"item":"Held the boundary on prescribing benzodiazepines on demand","weight":1},{"item":"Offered a realistic alternative plan","weight":1},{"item":"Called for help if needed and documented","weight":1}]'::jsonb, '{"label":"Global de-escalation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-193', 'Risk: frightening thoughts of harming the baby', 'Mrs Harpreet, 29, is six weeks after the birth of her son in Chandigarh. She told her health visitor she has ''terrible thoughts about the baby''. Assess her and decide the level of risk.', 600, '[{"item":"Thanked her for sharing and reduced shame","weight":2},{"item":"Explored the thoughts: content, how they feel, her reaction","weight":2},{"item":"Asked about avoidance, checking and neutralising","weight":2},{"item":"Assessed for psychotic features and for intent","weight":2},{"item":"Assessed mood and suicide","weight":1},{"item":"Explained that unwanted harm thoughts are common in perinatal OCD and are not intentions","weight":2},{"item":"Avoided an unnecessary child protection referral while keeping a safety review","weight":2}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-194', 'Risk: a drawer full of old medicines', 'Mrs Kusum, 64, with depression, lives with her son in Nashik. She mentions she has ''lots of tablets saved up''. Discuss this with her and her son.', 420, '[{"item":"Asked Kusum about the stored tablets and the reasons","weight":2},{"item":"Asked about suicidal thoughts directly","weight":2},{"item":"Discussed safe disposal and storage with her agreement","weight":2},{"item":"Suggested weekly supplies or a blister pack held by the son","weight":1},{"item":"Respected her dignity during the discussion","weight":1},{"item":"Agreed follow-up","weight":1}]'::jsonb, '{"label":"Global safety planning competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-195', 'Risk: ''I will kill myself if you leave me''', 'Mr Naveen, 30, from Visakhapatnam, was brought by his wife after he said he would kill himself if she goes to her parents. Assess him.', 420, '[{"item":"Assessed the threat seriously rather than dismissing it as manipulation","weight":2},{"item":"Asked about current thoughts, plans and past acts","weight":2},{"item":"Explored the relationship and controlling behaviour","weight":2},{"item":"Assessed alcohol use","weight":1},{"item":"Considered risk to his wife as well","weight":2},{"item":"Saw the wife separately to ask about her safety","weight":2},{"item":"Made a plan that did not make his wife responsible for his safety","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-196', 'Risk: suicide and alcohol dependence', 'Mr Rajan, 52, attends a de-addiction OPD in Thrissur. He mentions he ''thinks dark thoughts when drunk''. Assess his risk.', 420, '[{"item":"Asked about suicidal thoughts when drunk and sober","weight":2},{"item":"Explained that alcohol lowers inhibition and raises risk","weight":2},{"item":"Asked about means such as driving while drunk","weight":1},{"item":"Asked about losses and depression","weight":1},{"item":"Discussed treatment for dependence and safe withdrawal","weight":1},{"item":"Agreed a safety plan that includes not driving after drinking","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-197', 'Risk: a first-episode psychosis, risk in every direction', 'Mr Tenzin, 21, a student from Sikkim in Delhi, was brought by friends after living in his room without eating for days. He believes he is being watched. Assess all areas of risk.', 600, '[{"item":"Built trust and acknowledged real experiences of discrimination","weight":2},{"item":"Asked about suicidal thoughts","weight":2},{"item":"Asked about the knife and any thoughts of using it to defend himself","weight":2},{"item":"Asked about self-neglect: food, fluids, sleep","weight":2},{"item":"Considered risk from others: exploitation, violence, racial abuse","weight":2},{"item":"Asked about substances","weight":1},{"item":"Planned urgent treatment and safety with a clear explanation","weight":2}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-198', 'Risk: a home nurse worried about an older woman', 'Mrs Leela, 81, has dementia and lives with her son''s family in Bhopal. Her home nurse, Mary, calls you with concerns. Take the history from Mary and decide what to do.', 420, '[{"item":"Took a clear account of what was seen and heard","weight":2},{"item":"Asked about types of abuse: physical, neglect, financial, emotional","weight":2},{"item":"Asked about Leela''s capacity and her wishes","weight":1},{"item":"Asked about immediate danger","weight":2},{"item":"Advised accurate documentation","weight":1},{"item":"Discussed safeguarding routes: senior citizens'' law, Elderline 14567, police if in danger","weight":2},{"item":"Supported the nurse","weight":1}]'::jsonb, '{"label":"Global safeguarding assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-199', 'Risk: a school counsellor calls about a note', 'Ms Fernandes, a school counsellor in Goa, phones the clinic. A Class 9 girl left a note saying ''I won''t be here next week''. Take the information and advise her.', 420, '[{"item":"Stayed calm and gathered facts: who, what, when, where is the child now","weight":2},{"item":"Asked whether the child is safe and supervised now","weight":2},{"item":"Advised not to leave her alone","weight":2},{"item":"Advised contacting parents and bringing her for same-day assessment","weight":2},{"item":"Asked about any known means, past attempts and recent events","weight":1},{"item":"Advised what to say to the child","weight":1}]'::jsonb, '{"label":"Global telephone triage competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-200', 'Risk: asking about thoughts of harming others', 'Mr Rafiq, 38, a mechanic in Hyderabad, says he is furious with his boss for cutting his pay. Ask about thoughts of harming others.', 420, '[{"item":"Let him express his anger","weight":1},{"item":"Asked directly about thoughts of harming his boss","weight":2},{"item":"Asked about plans, intent and weapons","weight":2},{"item":"Asked about past violence and alcohol","weight":1},{"item":"Asked about what stops him","weight":1},{"item":"Agreed next steps for anger and stress","weight":1}]'::jsonb, '{"label":"Global risk assessment competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-201', 'Risk: triage in a busy OPD', 'You are the first contact in a crowded psychiatry OPD at a district hospital in Jharkhand. Mrs Baby Devi, 40, is next. You have two minutes. Find out whether she needs to be seen urgently.', 420, '[{"item":"Introduced self and the purpose of the quick check","weight":1},{"item":"Asked about thoughts of self-harm or suicide","weight":2},{"item":"Asked about thoughts of harming others","weight":1},{"item":"Asked about unusual experiences or confusion","weight":1},{"item":"Asked about eating, drinking and physical danger signs","weight":1},{"item":"Gave a clear outcome: routine queue with an explanation","weight":1}]'::jsonb, '{"label":"Global triage competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-202', 'Risk: when the only interpreter is her husband', 'Mrs Rupa Begum, 30, speaks only Bengali. She is in a Bengaluru emergency room after taking a large number of tablets. Her husband offers to interpret. Assess her risk.', 420, '[{"item":"Recognised that the husband should not interpret a risk assessment","weight":3},{"item":"Politely asked the husband to wait outside","weight":2},{"item":"Arranged a professional or telephone interpreter","weight":2},{"item":"Briefed the interpreter on confidentiality and exact translation","weight":1},{"item":"Asked about intent, current suicidal thoughts and violence at home","weight":2},{"item":"Planned safety, including not discharging her to an unsafe home without a plan","weight":2}]'::jsonb, '{"label":"Global interview with an interpreter competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-203', 'Breaking news: telling a man he has dementia', 'Mr Rajendra Bhatt, 71, a retired school principal in Dehradun, has completed memory tests and a scan. They show Alzheimer''s disease in the mild stage. He has asked to be told himself. Share the diagnosis.', 420, '[{"item":"Prepared the setting and asked who he wanted present","weight":1},{"item":"Checked what he already knows or suspects","weight":2},{"item":"Gave a warning shot and then the diagnosis in plain words","weight":2},{"item":"Allowed silence and responded to emotion","weight":2},{"item":"Answered ''how long'' honestly without false precision","weight":2},{"item":"Discussed what he can still do and planning ahead while he can decide","weight":2},{"item":"Agreed next steps and follow-up","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-204', 'Breaking news: a positive Huntington''s test', 'Ms Neelam Saxena, 32, from Noida, had predictive testing because her father had Huntington''s disease. The result shows she carries the expanded gene. Give her the result.', 600, '[{"item":"Checked she wanted the result today and who should be present","weight":1},{"item":"Gave the result clearly after a warning shot","weight":2},{"item":"Responded to emotion and allowed time","weight":2},{"item":"Explained the 50 percent chance for each child honestly","weight":2},{"item":"Explained that age of onset cannot be predicted precisely","weight":1},{"item":"Explained that there is no cure yet, but there is treatment for symptoms and support","weight":1},{"item":"Asked about suicidal thoughts clearly","weight":3},{"item":"Arranged follow-up with genetic counselling","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-205', 'Breaking news: telling parents their child has intellectual disability', 'Krish, 5, from Ranchi, has had a full assessment. He has moderate intellectual disability. Share the result with his parents.', 420, '[{"item":"Asked what they understood so far","weight":1},{"item":"Gave the diagnosis clearly in plain words","weight":2},{"item":"Explained what it means for learning and daily life","weight":1},{"item":"Responded to grief and the ''is it our fault'' question","weight":2},{"item":"Respected the family''s beliefs while giving accurate information","weight":1},{"item":"Discussed schooling, therapy and the disability certificate","weight":2},{"item":"Gave hope based on support and strengths","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-206', 'Breaking news: a death by suicide after discharge', 'Mr Pratik Dubey, 26, died by suicide two days after discharge from your Jabalpur unit. His parents have come to the ward. The police have already informed them of the death. Meet them.', 600, '[{"item":"Introduced self, expressed sincere condolence and used his name","weight":2},{"item":"Found a private space and allowed silence","weight":1},{"item":"Listened to anger without being defensive","weight":2},{"item":"Was honest about what is known and what will be reviewed","weight":2},{"item":"Did not blame the family or other staff","weight":2},{"item":"Addressed self-blame gently","weight":1},{"item":"Offered support: bereavement help, a named contact, a follow-up meeting","weight":2}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-207', 'Breaking news: clozapine has to stop', 'Mr Roshan, 31, from Nagpur, has done well on clozapine for eight months. Today''s blood test shows his neutrophil count has fallen below the safe level. Tell him and his brother.', 420, '[{"item":"Explained the result in plain words","weight":2},{"item":"Explained why clozapine must stop now","weight":2},{"item":"Advised urgent reporting of fever, sore throat or infection","weight":2},{"item":"Explained repeat blood tests and possible repeat confirmation","weight":1},{"item":"Acknowledged the loss of a medicine that worked","weight":2},{"item":"Discussed the plan for treating psychosis from now on","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-208', 'Breaking news: illness has come back', 'Ms Smita, 42, from Kolhapur, has been well on lithium for six years. Her husband reports she is sleeping three hours and spending heavily. Your assessment confirms early mania. Tell her.', 420, '[{"item":"Explored her view first","weight":1},{"item":"Gave the news gently and clearly","weight":2},{"item":"Linked it to the signs she and her husband noticed","weight":1},{"item":"Explored stopping lithium without blame","weight":2},{"item":"Discussed treatment options and what happens next","weight":1},{"item":"Addressed her work worries","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-209', 'Breaking news: no driving for now', 'Mr Raju, 45, a taxi driver in Mangaluru, is being treated for a manic episode and is sedated by his medicines. Tell him he should not drive until he has recovered.', 420, '[{"item":"Gave the advice clearly","weight":2},{"item":"Explained the reasons: slowed reactions, judgement","weight":1},{"item":"Acknowledged the impact on income","weight":2},{"item":"Gave a likely timeframe linked to recovery","weight":1},{"item":"Explored practical solutions","weight":1},{"item":"Documented the advice","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-210', 'Breaking news: a new mother needs admission', 'Mrs Divya, 28, in Bengaluru, is two weeks postpartum and has psychosis. You recommend admission to a mother and baby unit. Explain this to her and her husband.', 420, '[{"item":"Explained the illness and why admission is needed now","weight":2},{"item":"Explained the risks of waiting","weight":2},{"item":"Described the mother and baby unit","weight":2},{"item":"Addressed breastfeeding and medicines","weight":1},{"item":"Answered fears about stigma","weight":1},{"item":"Involved Divya in the discussion as far as possible","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-211', 'Breaking news: the scan shows a growth in the brain', 'Mr Thomas Kurian, 58, was referred to you in Kottayam for ''late-onset depression and personality change''. His MRI shows a large frontal meningioma. Tell him and his wife.', 600, '[{"item":"Prepared both and checked what they understand","weight":1},{"item":"Gave a warning shot and explained the finding clearly","weight":2},{"item":"Explained the link between the frontal growth and his changes","weight":2},{"item":"Explained what a meningioma usually is without false certainty","weight":2},{"item":"Responded to anger about the delay honestly","weight":1},{"item":"Arranged urgent neurosurgical referral","weight":2},{"item":"Checked the husband''s understanding and capacity sensitively","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-212', 'Breaking news: we gave the wrong dose', 'Mrs Sheela, 60, on your ward in Jaipur, was given her lithium twice last night by mistake. She is well, and her level is being checked. Tell her and her daughter.', 420, '[{"item":"Told them promptly and plainly what happened","weight":2},{"item":"Apologised sincerely without blaming individuals","weight":2},{"item":"Explained the possible effects and monitoring","weight":2},{"item":"Answered the fit question honestly","weight":1},{"item":"Explained what will be done to learn from the error","weight":1},{"item":"Offered a named contact and further meeting","weight":1}]'::jsonb, '{"label":"Global open disclosure competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-213', 'Breaking news: an HIV-positive result on the ward', 'Mr Sunil, 34, admitted to your Mumbai unit with depression, consented to an HIV test. It is positive on the confirmatory test. Give him the result.', 420, '[{"item":"Confirmed consent and privacy before giving the result","weight":1},{"item":"Gave the result clearly","weight":2},{"item":"Responded to shock and allowed time","weight":1},{"item":"Explained that HIV is a long-term treatable condition with free treatment at ART centres","weight":2},{"item":"Discussed confidentiality and the importance of partner testing","weight":2},{"item":"Asked about suicidal thoughts","weight":3},{"item":"Linked him to counselling and the ART centre","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-214', 'Breaking news: a student has not passed the placement', 'You supervise trainee counsellors at a clinic in Ahmedabad. Riddhi, 23, has not met the standard for her clinical placement. Tell her and plan the next steps.', 420, '[{"item":"Set up a private meeting and gave the result early","weight":2},{"item":"Gave specific reasons with examples","weight":2},{"item":"Explained why confidentiality matters so much","weight":1},{"item":"Acknowledged her effort and feelings","weight":1},{"item":"Agreed a clear plan to repeat or remediate","weight":1},{"item":"Checked she has support","weight":1}]'::jsonb, '{"label":"Global giving feedback competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-215', 'Breaking news: he has left the ward', 'Mr Amit, 24, admitted under supported admission in Lucknow, left the ward an hour ago. Police and family have been informed by phone. His father has arrived. Speak with him.', 420, '[{"item":"Introduced self and acknowledged the father''s fear","weight":1},{"item":"Explained what happened honestly and briefly","weight":2},{"item":"Explained what is being done: police, search, contacts","weight":2},{"item":"Asked for information on where he might go","weight":2},{"item":"Explained he is not being punished; the aim is his safety","weight":1},{"item":"Agreed how they will keep in touch","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-216', 'Breaking news: telling a man with dementia that his wife has died', 'Mr Shankar, 82, has moderate dementia and lives in a care home in Pune. His wife died last night. His son asks you to help tell him, and to advise what to do when he forgets.', 600, '[{"item":"Discussed with the son first: what to say and whether to tell","weight":2},{"item":"Told Shankar simply and kindly, with the son present","weight":2},{"item":"Allowed grief and stayed with him","weight":1},{"item":"Advised on responding when he asks again","weight":2},{"item":"Explained that re-telling may cause fresh grief each time","weight":2},{"item":"Considered involving him in rituals as he wishes","weight":1},{"item":"Arranged support for both","weight":1}]'::jsonb, '{"label":"Global breaking bad news competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-217', 'Breaking news: helping parents tell a child about a death', 'Mrs Fatima''s husband died in a road accident in Srinagar two days ago. She has not told her son Zaid, 7, who thinks his father is ''at work''. Help her plan what to say.', 420, '[{"item":"Acknowledged her grief before planning","weight":2},{"item":"Advised telling soon, with honest and simple words","weight":2},{"item":"Explained why phrases like ''sleeping'' or ''gone for a while'' can confuse or frighten","weight":2},{"item":"Explained what a seven-year-old understands about death","weight":1},{"item":"Discussed including him in rituals by his choice","weight":1},{"item":"Described normal grief reactions in children and when to seek help","weight":1}]'::jsonb, '{"label":"Global family guidance competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-218', 'Breaking news: the fits are not epilepsy', 'Ms Manisha, 22, from Agra, had a video EEG that showed her typical attacks are functional seizures. Explain the diagnosis to her.', 420, '[{"item":"Started by stating that the attacks are real and not deliberate","weight":2},{"item":"Named the diagnosis: functional or dissociative seizures","weight":2},{"item":"Explained the brain-based mechanism in plain words","weight":1},{"item":"Explained what the video EEG showed","weight":1},{"item":"Discussed carefully stopping anti-epileptic medicines with the neurologist","weight":1},{"item":"Explained that psychological therapy helps","weight":1},{"item":"Checked her understanding","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-219', 'Breaking news: naming depression for the first time', 'Mr Govind, 35, a shopkeeper in Varanasi, has the features of a moderate depressive episode. Tell him what you think is going on.', 420, '[{"item":"Asked what he thinks is causing his symptoms","weight":1},{"item":"Named depression in plain words","weight":2},{"item":"Linked it to his own symptoms","weight":2},{"item":"Addressed the ''not mad'' concern","weight":1},{"item":"Explained it is common and treatable","weight":1},{"item":"Checked understanding and invited questions","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-220', 'Breaking news: he needs long-term care', 'Mr Rakesh, 48, has had schizophrenia for 25 years with little response to treatment. His elderly parents in Delhi can no longer care for him. Discuss a long-stay rehabilitation home with them.', 420, '[{"item":"Acknowledged their years of care","weight":2},{"item":"Explained the recommendation and why","weight":2},{"item":"Addressed guilt and stigma","weight":1},{"item":"Described what the home offers and their rights to visit","weight":1},{"item":"Explored Rakesh''s own wishes","weight":1},{"item":"Discussed future planning: guardianship and finances","weight":1}]'::jsonb, '{"label":"Global family discussion competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-221', 'Explain: bipolar II disorder to a young woman', 'Ms Ruchi, 24, from Bhubaneswar, has had depressions and short highs that fit bipolar II disorder. Explain the diagnosis.', 420, '[{"item":"Asked what she knows about bipolar disorder","weight":1},{"item":"Explained the difference between hypomania and mania","weight":2},{"item":"Explained why an antidepressant alone may not be suitable","weight":2},{"item":"Explained mood stabiliser options","weight":1},{"item":"Discussed early warning signs","weight":1},{"item":"Discussed what to tell her fiance","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-222', 'Explain: borderline personality disorder without stigma', 'Ms Tanvi, 23, in Mumbai, has had many crises. Her team thinks she has borderline personality disorder. She has asked what her ''real diagnosis'' is. Explain.', 420, '[{"item":"Asked what she has heard about the diagnosis","weight":1},{"item":"Described the pattern using her own experiences","weight":2},{"item":"Addressed the stigma directly","weight":2},{"item":"Explained possible causes without blame","weight":1},{"item":"Gave hope: many people improve a lot over time","weight":2},{"item":"Explained effective therapies such as DBT","weight":1},{"item":"Checked her reaction","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-223', 'Explain: PTSD after the floods', 'Mr Joy, 40, a fisherman in Alappuzha, lost his house in the Kerala floods. He has nightmares and avoids the river. Explain what PTSD is and that it can be treated.', 420, '[{"item":"Normalised the reaction","weight":2},{"item":"Named PTSD and described its main features","weight":2},{"item":"Explained why memories keep returning","weight":1},{"item":"Explained that it is treatable","weight":1},{"item":"Linked treatment to his goal of fishing","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-224', 'Explain: generalised anxiety disorder', 'Mrs Shobha, 46, a homemaker in Vijayawada, worries about everything. Explain that she has generalised anxiety disorder and how it can be treated.', 420, '[{"item":"Named GAD and linked it to her symptoms","weight":2},{"item":"Explained the worry cycle in plain words","weight":1},{"item":"Explored her belief that worry protects","weight":2},{"item":"Described treatment: CBT, relaxation and medicines","weight":1},{"item":"Addressed the ''tablets for life'' question","weight":1},{"item":"Checked understanding","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-225', 'Explain: chest pain with normal tests', 'Mr Sudhir, 50, from Gwalior, has had chest pain for a year. Cardiology tests are normal. He is very worried and goes to the emergency room weekly. Explain what may be happening and what will help.', 420, '[{"item":"Acknowledged that the pain is real","weight":2},{"item":"Summarised the normal tests clearly","weight":1},{"item":"Explained how stress, attention and body tension can cause and amplify pain","weight":2},{"item":"Named somatic symptom disorder in plain words","weight":1},{"item":"Explained what helps: regular reviews, therapy, gradual activity","weight":2},{"item":"Agreed a plan for when to seek emergency help","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-226', 'Explain: delusional disorder to a worried sister', 'Mr Satish, 52, in Kanpur, believes neighbours are poisoning his water. He works and functions normally otherwise. His sister wants to understand. Explain, with his consent.', 420, '[{"item":"Confirmed consent","weight":1},{"item":"Explained delusional disorder in plain words","weight":2},{"item":"Explained why arguing does not work","weight":2},{"item":"Suggested ways to talk without arguing or agreeing","weight":2},{"item":"Discussed treatment and engagement","weight":1},{"item":"Addressed the violence question honestly","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-227', 'Explain: alcohol dependence is an illness', 'Mrs Rekha, 40, from Bhopal, says her husband ''has no willpower''. He has alcohol dependence and has agreed you can talk to her. Explain the condition.', 420, '[{"item":"Acknowledged her strain","weight":2},{"item":"Explained dependence in plain words: craving, tolerance, withdrawal, loss of control","weight":2},{"item":"Addressed responsibility and illness together","weight":1},{"item":"Explained safe withdrawal and treatment options","weight":1},{"item":"Discussed support for her, such as family groups","weight":1},{"item":"Checked her safety at home","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-228', 'Explain: a specific learning disorder to parents', 'Aditi, 10, from Kolkata, has been assessed. She has a specific learning disorder with impairment in reading. Explain this to her parents.', 420, '[{"item":"Explained that her intelligence is normal","weight":2},{"item":"Explained the reading difficulty in plain words","weight":1},{"item":"Addressed the ''lazy'' belief","weight":2},{"item":"Explained school accommodations such as extra time or a reader","weight":1},{"item":"Explained the disability certificate and its use","weight":1},{"item":"Discussed remedial teaching and her strengths","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-229', 'Explain: schizophrenia through an Odia interpreter', 'Mr Bikash, 23, from a village in Kandhamal, Odisha, is in a Hyderabad hospital with his first episode of schizophrenia. His parents speak Odia. An interpreter is present. Explain the diagnosis and treatment.', 600, '[{"item":"Briefed the interpreter: no jargon, exact meaning, confidentiality","weight":2},{"item":"Spoke to the parents directly with short sentences and pauses","weight":2},{"item":"Asked about their understanding and beliefs","weight":2},{"item":"Explained the illness simply, avoiding jargon","weight":1},{"item":"Explained treatment and side effects, including dullness","weight":1},{"item":"Discussed traditional healing without dismissing it","weight":2},{"item":"Checked understanding through teach-back","weight":2}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-230', 'Explain: Lewy body dementia and the danger of some medicines', 'Mr Joseph, 74, in Chennai, has fluctuating confusion, sees children in the room and has stiffness. A local doctor gave haloperidol last week and he became very rigid and fell. The diagnosis is dementia with Lewy bodies. Explain this to his wife.', 600, '[{"item":"Explained the diagnosis and its main features in plain words","weight":2},{"item":"Linked fluctuations, visual hallucinations, stiffness and sleep behaviour to the diagnosis","weight":2},{"item":"Explained serious sensitivity to antipsychotics","weight":3},{"item":"Advised that the haloperidol should stop and other doctors be informed","weight":2},{"item":"Discussed treatment options such as cholinesterase inhibitors","weight":1},{"item":"Advised on handling hallucinations calmly","weight":1},{"item":"Discussed falls and safety","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-231', 'Explain: is it the cannabis or schizophrenia?', 'Mr Karan, 20, from Shimla, had a psychotic episode after heavy charas use. Symptoms are settling after three weeks of treatment. He and his mother want to know ''what he has''. Explain.', 600, '[{"item":"Asked what they think caused it","weight":1},{"item":"Explained the two main possibilities honestly","weight":2},{"item":"Explained that time and staying off cannabis help clarify the diagnosis","weight":2},{"item":"Explained the link between cannabis and psychosis risk","weight":2},{"item":"Discussed a plan for medicine duration","weight":1},{"item":"Used motivational interviewing about cannabis","weight":1},{"item":"Agreed follow-up and warning signs","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into osce_stations (slug, title, task, duration_seconds, checklist, global_rating, status) values ('osce-232', 'Explain: Tourette syndrome to a teacher', 'Kabir, 11, has Tourette syndrome. His parents have given consent for you to speak to his class teacher in Lucknow. Explain the condition and how she can help.', 420, '[{"item":"Confirmed parental consent","weight":1},{"item":"Explained tics are involuntary","weight":2},{"item":"Explained that holding them in is tiring and leads to more later","weight":1},{"item":"Advised against punishment and drawing attention to tics","weight":2},{"item":"Suggested practical help: breaks, exam room, class education","weight":1},{"item":"Answered her questions respectfully","weight":1}]'::jsonb, '{"label":"Global diagnosis explanation competence","max":5}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, task = excluded.task, duration_seconds = excluded.duration_seconds, checklist = excluded.checklist, global_rating = excluded.global_rating, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-1', 'Ravi: ''the heaviness'' (somatic depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"f1","text":"Body ache, heaviness, poor sleep, 6kg weight loss","bucket":"presenting"},{"id":"f2","text":"Promotion added night shifts 8 months ago","bucket":"precipitating"},{"id":"f3","text":"Father had a ''nervous breakdown'' in his 40s","bucket":"predisposing"},{"id":"f4","text":"Avoids talking about feelings; keeps working while exhausted","bucket":"perpetuating"},{"id":"f5","text":"Supportive wife who ''keeps asking''","bucket":"protective"},{"id":"f6","text":"GP visits for ''gas'' and ''weakness'' without improvement","bucket":"perpetuating"},{"id":"f7","text":"Core belief: ''I am failing my family''","bucket":"predisposing"},{"id":"f8","text":"The weather is unusually hot this summer","bucket":"distractor"},{"id":"f9","text":"Employee has a steady job and a roof","bucket":"protective"},{"id":"f10","text":"Two-year help-seeking delay before any mental-health contact","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ravi presents with somatic depression: 8 months of body ache, broken sleep and weight loss following a promotion that added night shifts (precipitant). A family history of paternal ''nervous breakdown'' and a core belief of failing his family (predisposing) shape his coping: he avoids disclosing distress and keeps working through exhaustion (perpetuating), and a two-year help-seeking delay reinforced it. Protective factors include a supportive wife and stable employment. The formulation explains why he presents somatically: the heaviness is the only acceptable language his belief system permits for distress.","hint":"Somatic depression in a man who won''t talk about feelings","tags":{"topic":"depression","difficulty":2,"objective":"Link a somatic presentation of depression to its 5 Ps","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"depression","diagnosis":"Moderate depressive episode with somatic presentation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-2', 'Meera: the exam that never ends (panic disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"m1","text":"Sudden attacks of racing heart, breathlessness and fear of dying, 3 to 4 times a week","bucket":"presenting"},{"id":"m2","text":"Now avoids the coaching centre and travels only with her mother","bucket":"presenting"},{"id":"m3","text":"First attack in the exam hall, two months before her second NEET attempt","bucket":"precipitating"},{"id":"m4","text":"Mother has ''BP and tension'' and checks her own pulse often","bucket":"predisposing"},{"id":"m5","text":"Anxious, perfectionistic temperament since childhood","bucket":"predisposing"},{"id":"m6","text":"Three ECGs and an echo, all normal; each one calms her for a day only","bucket":"perpetuating"},{"id":"m7","text":"Carries a water bottle and sits near doors ''just in case'' (safety behaviours)","bucket":"perpetuating"},{"id":"m8","text":"Reads about heart attacks in young women late at night","bucket":"perpetuating"},{"id":"m9","text":"Close friend who has offered to sit with her in class","bucket":"protective"},{"id":"m10","text":"Bright, motivated, and asked for help herself","bucket":"protective"},{"id":"m11","text":"Her blood group is B positive","bucket":"distractor"},{"id":"m12","text":"The family recently bought a new scooter","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Meera, 19, presents with panic disorder with growing agoraphobic avoidance: frequent surges of palpitations, breathlessness and fear of dying, and she now avoids the coaching centre. An anxious, perfectionistic temperament and a mother who models health vigilance (predisposing) set the stage; the first attack came in the exam hall during a high-stakes repeat attempt (precipitating). The cycle is kept going by repeated reassurance-seeking through normal cardiac tests, safety behaviours that stop her learning the attacks are harmless, and night-time symptom searching (perpetuating). Her own help-seeking, intelligence and a supportive friend are strengths to build exposure work on (protective).","hint":"Panic attacks before NEET, a heart she is sure is failing","tags":{"topic":"anxiety","difficulty":2,"objective":"Show how safety behaviours and reassurance keep panic going","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Panic disorder with early agoraphobic avoidance"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-3', 'Arjun: the voices after the hostel (first-episode psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"a1","text":"Hears two men discussing him; believes classmates put a chip in his laptop","bucket":"presenting"},{"id":"a2","text":"Stopped attending college, poor sleep, speaks less, 4 months","bucket":"presenting"},{"id":"a3","text":"Paternal uncle with schizophrenia","bucket":"predisposing"},{"id":"a4","text":"Daily cannabis use since second year","bucket":"predisposing"},{"id":"a5","text":"Moved to a distant hostel and failed two subjects last semester","bucket":"precipitating"},{"id":"a6","text":"Heavier cannabis use after the exam results","bucket":"precipitating"},{"id":"a7","text":"Family took him to a faith healer first; 3-month delay before a psychiatrist","bucket":"perpetuating"},{"id":"a8","text":"Ongoing cannabis use and no fixed sleep routine","bucket":"perpetuating"},{"id":"a9","text":"Believes medicine is ''for mad people'' and skips doses","bucket":"perpetuating"},{"id":"a10","text":"Parents are worried but involved and come to every visit","bucket":"protective"},{"id":"a11","text":"Good school record and friends from before college","bucket":"protective"},{"id":"a12","text":"He prefers Android phones","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arjun, 21, presents with a first episode of psychosis: auditory hallucinations in the third person, a persecutory delusion about a chip in his laptop, and four months of withdrawal, poor sleep and dropping out. A family history of schizophrenia and regular adolescent cannabis use (predisposing) raised his vulnerability; moving away from home, academic failure and heavier cannabis use after the results (precipitating) came just before onset. The duration of untreated psychosis was lengthened by the faith-healer route, and continuing cannabis, irregular sleep and his belief that medicine is for ''mad people'' (perpetuating) risk relapse. Engaged parents and a good premorbid level of functioning (protective) predict a better outcome and make early family work possible.","hint":"A 21-year-old engineering student who stopped attending","tags":{"topic":"psychosis","difficulty":3,"objective":"Separate vulnerability, triggers and relapse drivers in first-episode psychosis","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"psychosis","diagnosis":"First-episode psychosis (schizophreniform picture)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-4', 'Sunita: ''I just want to sleep'' (postpartum depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"s1","text":"Low mood, crying, no interest in the baby''s care, poor appetite for 6 weeks","bucket":"presenting"},{"id":"s2","text":"Thoughts that the baby would be better off with her mother-in-law","bucket":"presenting"},{"id":"s3","text":"Depressive episode in college that settled without treatment","bucket":"predisposing"},{"id":"s4","text":"Emergency caesarean and a 5-day NICU stay for the baby","bucket":"precipitating"},{"id":"s5","text":"Criticism from in-laws after the baby was a girl","bucket":"precipitating"},{"id":"s6","text":"Husband works away; night feeds are hers alone, sleep 3 to 4 hours","bucket":"perpetuating"},{"id":"s7","text":"Feels guilty and hides her tears so she is ''not a bad mother''","bucket":"perpetuating"},{"id":"s8","text":"Her own mother calls every day and wants to visit","bucket":"protective"},{"id":"s9","text":"Breastfeeding well; the baby is gaining weight","bucket":"protective"},{"id":"s10","text":"The house is being painted","bucket":"distractor"},{"id":"s11","text":"She studied commerce","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sunita, 27, presents ten weeks postpartum with a moderate depressive episode: low mood, tearfulness, poor appetite, loss of interest in caring for her baby and thoughts that the baby would be better off with others, which need a careful risk assessment. A previous untreated depressive episode (predisposing) left her vulnerable; a traumatic emergency caesarean with a NICU stay and criticism over the baby''s sex (precipitating) came just before onset. Severe sleep loss with no one to share night feeds and guilt-driven concealment of her distress (perpetuating) keep it going. Her mother''s daily support and the fact that feeding and the baby''s growth are going well (protective) are footholds for treatment and for practical help at night.","hint":"A new mother, 10 weeks after a caesarean, in a joint family","tags":{"topic":"perinatal","difficulty":3,"objective":"Formulate postpartum depression with risk to self and baby in view","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"depression","diagnosis":"Moderate depressive episode, postpartum onset"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-5', 'Mr Khan: the drink after the shop shut (alcohol dependence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"k1","text":"Drinks a quarter bottle of whisky daily, morning tremor relieved by a drink","bucket":"presenting"},{"id":"k2","text":"First withdrawal seizure last week after 2 days without alcohol","bucket":"presenting"},{"id":"k3","text":"Father drank heavily and died of liver disease","bucket":"predisposing"},{"id":"k4","text":"Started drinking with friends at 18; drinking was the way to unwind","bucket":"predisposing"},{"id":"k5","text":"Shop closed during a long market slump 2 years ago; drinking doubled","bucket":"precipitating"},{"id":"k6","text":"Evenings at the same friend''s place where everyone drinks","bucket":"perpetuating"},{"id":"k7","text":"Drinks to stop the shaking and sleeplessness of withdrawal","bucket":"perpetuating"},{"id":"k8","text":"Says ''I can stop when I want'' and refused help before","bucket":"perpetuating"},{"id":"k9","text":"Wife and teenage son want him well; son came to the appointment","bucket":"protective"},{"id":"k10","text":"Frightened by the seizure and now asking how to stop","bucket":"protective"},{"id":"k11","text":"His shop sold stationery","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Khan, 45, presents with alcohol dependence with physiological withdrawal, shown by morning tremor relieved by drinking and a recent withdrawal seizure. A father who drank heavily and an early learned habit of drinking to unwind (predisposing) built the pattern; the loss of his shop two years ago (precipitating) doubled his intake. Drinking to relieve withdrawal, an evening routine centred on a drinking circle, and minimisation of the problem (perpetuating) maintain it. The fright of the seizure has opened a window of motivation, and a wife and son who are involved (protective) give a base for supervised detoxification, relapse-prevention medicine and family work.","hint":"A 45-year-old shopkeeper brought in after a withdrawal fit","tags":{"topic":"substance","difficulty":2,"objective":"Place withdrawal relief and social cues as perpetuating factors","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"substance","diagnosis":"Alcohol dependence with withdrawal seizure"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-6', 'Riya: washing until her hands bleed (OCD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"r1","text":"Intrusive thoughts of germs and of harming her family by passing on illness","bucket":"presenting"},{"id":"r2","text":"Washes hands 40 times a day and showers for an hour; hands cracked and bleeding","bucket":"presenting"},{"id":"r3","text":"Mother has always been very particular about cleanliness and order","bucket":"predisposing"},{"id":"r4","text":"Rigid, rule-bound and anxious as a child","bucket":"predisposing"},{"id":"r5","text":"Grandfather fell seriously ill with an infection a year ago","bucket":"precipitating"},{"id":"r6","text":"Family washes the vegetables again for her and answers ''Is it clean?'' many times a day","bucket":"perpetuating"},{"id":"r7","text":"Each wash brings relief for a few minutes, so the urge comes back stronger","bucket":"perpetuating"},{"id":"r8","text":"Avoids school because the toilets feel ''contaminated''","bucket":"perpetuating"},{"id":"r9","text":"Knows the thoughts are excessive and wants to stop (good insight)","bucket":"protective"},{"id":"r10","text":"A teacher she trusts has kept in touch","bucket":"protective"},{"id":"r11","text":"She is learning the sitar","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Riya, 16, presents with obsessive-compulsive disorder with good insight: contamination obsessions and fears of harming her family, with washing compulsions that take four hours a day and have damaged her skin. An anxious, rule-bound temperament and a household with strong cleanliness rules (predisposing) form the background; her grandfather''s serious infection (precipitating) gave the fears their content. The cycle is maintained because each wash brings brief relief that strengthens the urge, the family''s reassurance and re-washing accommodate the rituals, and avoiding school prevents her ever testing her fears (perpetuating). Good insight, her wish to stop and a trusted teacher (protective) make her a strong candidate for exposure and response prevention, with the family taught to step back from reassurance.","hint":"A 16-year-old whose rituals now take 4 hours a day","tags":{"topic":"ocd","difficulty":2,"objective":"Show how family accommodation maintains compulsions","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder with good insight"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-7', 'Kavitha: the nurse who stopped eating lunch (moderate depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-7-1","text":"Replays the night of the death every evening","bucket":"perpetuating"},{"id":"form-7-2","text":"Tends to hold herself responsible for everything on the ward","bucket":"predisposing"},{"id":"form-7-3","text":"Volunteers for extra night shifts so she has no time to think","bucket":"perpetuating"},{"id":"form-7-4","text":"Has asked her GP for help herself","bucket":"protective"},{"id":"form-7-5","text":"A young patient in her care died after a cardiac arrest on her night shift","bucket":"precipitating"},{"id":"form-7-6","text":"Her hospital is changing to electronic records next year","bucket":"distractor"},{"id":"form-7-7","text":"Has stopped eating lunch and lost 4 kg","bucket":"presenting"},{"id":"form-7-8","text":"Low mood, early waking at 4 am and loss of interest for seven weeks","bucket":"presenting"},{"id":"form-7-9","text":"A ward sister who checks on her daily","bucket":"protective"},{"id":"form-7-10","text":"Previous low spell at 19 after her father''s illness","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kavitha, 32, presents with a moderate depressive episode: seven weeks of low mood, early waking, loss of interest and weight loss. An earlier low spell and a habit of taking personal responsibility for outcomes (predisposing) left her vulnerable, and the death of a young patient on her shift (precipitating) began the episode. Taking extra night shifts to avoid thinking and replaying the event each evening (perpetuating) disturb sleep and feed guilt. A caring ward sister and her own help-seeking (protective) are the base for treatment.","hint":"A staff nurse after a ward death she blames herself for","tags":{"topic":"depression","difficulty":1,"objective":"Sort a clear depressive presentation into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-8', 'Suresh: the farmer and the second failed crop (depression with risk)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-8-1","text":"Second consecutive cotton crop failure from pest attack","bucket":"precipitating"},{"id":"form-8-2","text":"Hopelessness, poor sleep and thoughts that his family would be better off without him","bucket":"presenting"},{"id":"form-8-3","text":"Has always kept worries to himself","bucket":"predisposing"},{"id":"form-8-4","text":"Two daughters he wants to see educated","bucket":"protective"},{"id":"form-8-5","text":"Stopped going to the village meetings","bucket":"presenting"},{"id":"form-8-6","text":"Wife who brought him to the health centre","bucket":"protective"},{"id":"form-8-7","text":"Drinks more in the evenings to sleep","bucket":"perpetuating"},{"id":"form-8-8","text":"Pesticide stored in the shed beside the house","bucket":"perpetuating"},{"id":"form-8-9","text":"The village got a new tar road last year","bucket":"distractor"},{"id":"form-8-10","text":"His elder brother died by suicide after crop loss","bucket":"predisposing"},{"id":"form-8-11","text":"Debt of three lakh to a private lender who visits often","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Suresh, 46, presents with a moderate depressive episode with suicidal ideation: hopelessness, broken sleep, withdrawal and thoughts that his family would be better off without him. A brother''s suicide after crop loss and a lifelong habit of hiding worry (predisposing) raise his risk; the second crop failure (precipitating) triggered the episode. Ongoing debt pressure, evening drinking and easy access to pesticide (perpetuating) keep both the mood and the risk high. His daughters'' future and a wife who sought help (protective) give reasons for living; the plan must include removing the pesticide, debt support and treatment.","hint":"A cotton farmer in debt who keeps pesticide in the shed","tags":{"topic":"depression","difficulty":3,"objective":"Show how social stressors and means access belong in a formulation","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"suicide","diagnosis":"Moderate depressive episode with suicidal ideation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-9', 'Mrs Banerjee: grey for twenty years (persistent depressive disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-9-1","text":"She prefers reading on paper rather than on screens","bucket":"distractor"},{"id":"form-9-2","text":"Grew up with a critical, cold mother","bucket":"predisposing"},{"id":"form-9-3","text":"No single trigger; worsened slightly after her son left for college","bucket":"precipitating"},{"id":"form-9-4","text":"Steady job she does well","bucket":"protective"},{"id":"form-9-5","text":"Lost her father at nine with little chance to grieve","bucket":"predisposing"},{"id":"form-9-6","text":"Self-critical thinking that she is a mediocre person","bucket":"perpetuating"},{"id":"form-9-7","text":"Low, joyless mood most days for over twenty years","bucket":"presenting"},{"id":"form-9-8","text":"Low self-esteem and constant tiredness without full collapse","bucket":"presenting"},{"id":"form-9-9","text":"Believes ''this is just my nature'' so never sought help","bucket":"perpetuating"},{"id":"form-9-10","text":"A close friend from college who calls weekly","bucket":"protective"},{"id":"form-9-11","text":"Withdraws from colleagues'' invitations","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Banerjee, 51, presents with persistent depressive disorder: over twenty years of low, joyless mood, poor self-esteem and fatigue without a single severe episode. A cold, critical mother and an early, ungrieved loss of her father (predisposing) shaped a self-critical view of herself. There is no clear precipitant, though her son leaving home made it more noticeable. Her belief that this is simply her nature, social withdrawal and self-critical thinking (perpetuating) have kept it going untreated for decades. A job she does well and a loyal friend (protective) are strengths for treatment, which can help even a long-standing low mood.","hint":"A school librarian who says she has always been gloomy","tags":{"topic":"depression","difficulty":2,"objective":"Formulate a chronic low-grade mood problem","exams":["mcp-entrance","ugc-net","ma-semester"],"module":"depression","diagnosis":"Persistent depressive disorder (dysthymia)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-10', 'Ankit: the topper who failed placement (depression in a student)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-10-1","text":"Froze and failed a campus placement interview","bucket":"precipitating"},{"id":"form-10-2","text":"Avoids his parents'' calls so the shame grows","bucket":"perpetuating"},{"id":"form-10-3","text":"Loss of interest, poor sleep and missing classes for six weeks","bucket":"presenting"},{"id":"form-10-4","text":"His college changed its canteen contractor","bucket":"distractor"},{"id":"form-10-5","text":"Core belief that he is worthless unless he comes first","bucket":"predisposing"},{"id":"form-10-6","text":"Night-time gaming that wrecks his sleep","bucket":"perpetuating"},{"id":"form-10-7","text":"Ignores calls from home and games through the night","bucket":"presenting"},{"id":"form-10-8","text":"Close bond with his younger sister","bucket":"protective"},{"id":"form-10-9","text":"Compares himself to friends who got placed","bucket":"perpetuating"},{"id":"form-10-10","text":"Father''s harsh expectations through school","bucket":"predisposing"},{"id":"form-10-11","text":"A roommate who brought him to the counsellor","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ankit, 21, presents with a moderate depressive episode: six weeks of anhedonia, poor sleep, missed classes and withdrawal. A belief that his worth depends on coming first, shaped by a father''s harsh expectations (predisposing), made a single failure feel catastrophic, and freezing in a placement interview (precipitating) set it off. Night gaming that ruins sleep, avoidance of his parents and constant comparison with placed friends (perpetuating) keep him stuck. A loyal roommate and his sister (protective) are allies; the plan should include a risk check, sleep routine and work on his all-or-nothing beliefs.","hint":"A final-year engineering student who games all night","tags":{"topic":"depression","difficulty":2,"objective":"Link academic pressure and avoidance in a young man''s depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-11', 'Mr Iqbal: since the stroke (post-stroke depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-11-1","text":"Long-standing high blood pressure and diabetes","bucket":"predisposing"},{"id":"form-11-2","text":"Identity built entirely around his tailoring skill","bucket":"predisposing"},{"id":"form-11-3","text":"Says he is ''useless now''","bucket":"presenting"},{"id":"form-11-4","text":"Cannot sew, so has lost his main source of pride","bucket":"perpetuating"},{"id":"form-11-5","text":"Left-sided stroke three months ago with weakness of the right hand","bucket":"precipitating"},{"id":"form-11-6","text":"Strong faith and regular prayer","bucket":"protective"},{"id":"form-11-7","text":"Grandson who sits with him every evening","bucket":"protective"},{"id":"form-11-8","text":"Low mood, crying and refusing physiotherapy on most days","bucket":"presenting"},{"id":"form-11-9","text":"His shop sign was repainted last year","bucket":"distractor"},{"id":"form-11-10","text":"Family do everything for him, so he does nothing","bucket":"perpetuating"},{"id":"form-11-11","text":"Skips physiotherapy, which slows recovery","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Iqbal, 68, presents with post-stroke depression: low mood, tearfulness, refusal of physiotherapy and a sense of being useless three months after a left-sided stroke. Vascular risk factors and an identity built on his craft (predisposing) set the stage; the stroke itself, which damaged the hand he sewed with (precipitating), brought on the episode both through brain injury and through loss of role. Loss of his work, well-meant over-helping by family and missed physiotherapy (perpetuating) keep him inactive and hopeless. His grandson and his faith (protective) can be built into rehabilitation goals and activity scheduling.","hint":"A retired tailor three months after a stroke","tags":{"topic":"depression","difficulty":3,"objective":"Include medical illness and role loss in a formulation","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Post-stroke depression"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-12', 'Leena: the winter months in Oslo (seasonal pattern)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-12-1","text":"Full recovery each spring","bucket":"presenting"},{"id":"form-12-2","text":"Cancels social plans in winter, so she becomes isolated","bucket":"perpetuating"},{"id":"form-12-3","text":"Moved from Kochi, where daylight is steady all year","bucket":"predisposing"},{"id":"form-12-4","text":"Stays indoors after night shifts and sees almost no daylight","bucket":"perpetuating"},{"id":"form-12-5","text":"Understanding manager who allows shift changes","bucket":"protective"},{"id":"form-12-6","text":"Clear insight into the pattern","bucket":"protective"},{"id":"form-12-7","text":"Low mood, oversleeping and craving for sweets each winter for three years","bucket":"presenting"},{"id":"form-12-8","text":"Mother had recurrent low spells","bucket":"predisposing"},{"id":"form-12-9","text":"She owns a second-hand bicycle","bucket":"distractor"},{"id":"form-12-10","text":"Onset each year as daylight shortens in November","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Leena, 34, presents with recurrent depressive disorder with a seasonal pattern: three winters of low mood, oversleeping and carbohydrate craving with full spring recovery. A family history of mood disorder and a move from a stable-daylight region (predisposing) leave her sensitive to light changes; shortening daylight each November (precipitating) triggers each episode. Night shifts with little daylight and winter social withdrawal (perpetuating) deepen it. A flexible manager and her own insight (protective) support a plan of light therapy, daytime light exposure, social scheduling and medicine if needed.","hint":"An Indian nurse in Norway whose low mood comes every November","tags":{"topic":"depression","difficulty":3,"objective":"Show a biological rhythm as a predisposing and perpetuating factor","exams":["md-psychiatry","ugc-net","cuet-pg"],"module":"depression","diagnosis":"Recurrent depressive disorder with seasonal pattern"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-13', 'Rajesh: four ECGs and still afraid (panic disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-13-1","text":"Avoids the metro and crowded places","bucket":"presenting"},{"id":"form-13-2","text":"Repeated ECGs that calm him for a day only","bucket":"perpetuating"},{"id":"form-13-3","text":"Anxious temperament since school","bucket":"predisposing"},{"id":"form-13-4","text":"Sits near exits as a safety behaviour","bucket":"perpetuating"},{"id":"form-13-5","text":"He supports a cricket team from Chennai","bucket":"distractor"},{"id":"form-13-6","text":"First attack in a crowded metro coach during a heat wave","bucket":"precipitating"},{"id":"form-13-7","text":"Wife who joins him for therapy sessions","bucket":"protective"},{"id":"form-13-8","text":"Checks his pulse many times a day","bucket":"perpetuating"},{"id":"form-13-9","text":"Father had a heart attack at 50","bucket":"predisposing"},{"id":"form-13-10","text":"Sudden surges of racing heart, breathlessness and fear of dying, several times a week","bucket":"presenting"},{"id":"form-13-11","text":"Good understanding when the cycle is explained","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rajesh, 38, presents with panic disorder: frequent sudden surges of palpitations, breathlessness and fear of dying, with growing avoidance of the metro. An anxious temperament and his father''s heart attack (predisposing) made heart symptoms frightening; the first attack in a crowded, hot coach (precipitating) set the cycle off. Reassurance from repeated ECGs, pulse checking and sitting near exits (perpetuating) prevent him learning the attacks are harmless. His wife''s support and his quick grasp of the panic cycle (protective) favour CBT with graded exposure.","hint":"A bank clerk who now avoids the metro","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort a clear panic cycle into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Panic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-14', 'Mrs Thomas: the woman who worries about everything (generalised anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-14-1","text":"Her mother was a constant worrier","bucket":"predisposing"},{"id":"form-14-2","text":"Calls her children every evening for reassurance","bucket":"perpetuating"},{"id":"form-14-3","text":"Constant hard-to-control worry about health, money and her children for over a year","bucket":"presenting"},{"id":"form-14-4","text":"Believes worrying keeps her family safe","bucket":"perpetuating"},{"id":"form-14-5","text":"Husband who is calm and patient","bucket":"protective"},{"id":"form-14-6","text":"Childhood with an unpredictable, drinking father","bucket":"predisposing"},{"id":"form-14-7","text":"Retired from teaching and lost her daily structure","bucket":"precipitating"},{"id":"form-14-8","text":"Avoids news and then worries about what she missed","bucket":"perpetuating"},{"id":"form-14-9","text":"She grows tomatoes on her balcony","bucket":"distractor"},{"id":"form-14-10","text":"Muscle tension, poor sleep and irritability","bucket":"presenting"},{"id":"form-14-11","text":"Active in her church choir","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Thomas, 62, presents with generalised anxiety disorder: a year of uncontrollable worry across many topics with tension, poor sleep and irritability. A worried mother and an unpredictable childhood home (predisposing) taught her that vigilance keeps danger away; retirement removed her structure and gave worry room (precipitating). Positive beliefs about worry, nightly reassurance calls and avoidance (perpetuating) keep the cycle running. Her choir and a calm husband (protective) can support CBT that targets beliefs about worry and reassurance seeking.","hint":"A retired teacher who calls her children every evening","tags":{"topic":"anxiety","difficulty":2,"objective":"Show how beliefs about worry keep it going","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Generalised anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-15', 'Rohan: red-faced in every presentation (social anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-15-1","text":"Blushes, trembles and avoids presentations","bucket":"presenting"},{"id":"form-15-2","text":"Shy and inhibited since early childhood","bucket":"predisposing"},{"id":"form-15-3","text":"Rehearses every sentence and avoids eye contact (safety behaviours)","bucket":"perpetuating"},{"id":"form-15-4","text":"Intense fear of being judged when speaking or eating in front of others","bucket":"presenting"},{"id":"form-15-5","text":"Avoids presentations, so never learns he can cope","bucket":"perpetuating"},{"id":"form-15-6","text":"He lives on the third floor of his building","bucket":"distractor"},{"id":"form-15-7","text":"Teased harshly in middle school","bucket":"predisposing"},{"id":"form-15-8","text":"Motivated to finish his degree","bucket":"protective"},{"id":"form-15-9","text":"Two close childhood friends","bucket":"protective"},{"id":"form-15-10","text":"Laughed at after forgetting lines in a school speech","bucket":"precipitating"},{"id":"form-15-11","text":"Replays each social event looking for mistakes","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rohan, 19, presents with social anxiety disorder: intense fear of judgement when speaking or eating in front of others, with blushing, trembling and avoidance. An inhibited temperament and teasing in school (predisposing) built a fear of scrutiny; public laughter after a failed speech (precipitating) fixed it. Safety behaviours, avoidance and post-event rumination (perpetuating) keep the fear alive by blocking disconfirming experiences. Close friends and his wish to finish college (protective) support CBT focused on dropping safety behaviours and graded exposure.","hint":"A first-year college student who eats lunch in the library","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort the social anxiety cycle into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Social anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-16', 'Fatima: the Eid bazaar and the locked gate (agoraphobia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-16-1","text":"Cannot leave the house without her husband for two years","bucket":"presenting"},{"id":"form-16-2","text":"First panic attack in a crowded bazaar during Eid shopping","bucket":"precipitating"},{"id":"form-16-3","text":"Husband wants her to get better and will join sessions","bucket":"protective"},{"id":"form-16-4","text":"Avoidance has spread from the bazaar to the street","bucket":"perpetuating"},{"id":"form-16-5","text":"Anxious as a child, clung to her mother at school","bucket":"predisposing"},{"id":"form-16-6","text":"Panic attacks in crowded places","bucket":"presenting"},{"id":"form-16-7","text":"Her house is painted light green","bucket":"distractor"},{"id":"form-16-8","text":"Husband now does all errands and takes the children to school","bucket":"perpetuating"},{"id":"form-16-9","text":"Mother also feared going out alone","bucket":"predisposing"},{"id":"form-16-10","text":"Wants to attend her daughter''s school events","bucket":"protective"},{"id":"form-16-11","text":"Takes an unknown ''nerve tablet'' from the chemist","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Fatima, 38, presents with agoraphobia with panic attacks: two years of being unable to leave home alone after panic in crowds. An anxious, clinging childhood and a mother with similar fears (predisposing) shaped her vulnerability; a panic attack in the Eid bazaar (precipitating) started the avoidance. Her husband doing all the errands, an unknown chemist sedative and the spreading of avoidance (perpetuating) keep her housebound. Her husband''s willingness to help and her wish to attend her daughter''s events (protective) support graded exposure with the family as coaches, not rescuers.","hint":"A homemaker who cannot leave the house alone","tags":{"topic":"anxiety","difficulty":2,"objective":"Show how family accommodation maintains avoidance","exams":["mcp-entrance","ma-semester"],"module":"anxiety","diagnosis":"Agoraphobia with panic attacks"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-17', 'Neha: hands washed raw before exams (OCD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-17-1","text":"Washes hands 30 times a day and asks others if things are clean","bucket":"presenting"},{"id":"form-17-2","text":"Intrusive fears of contaminating others with germs","bucket":"presenting"},{"id":"form-17-3","text":"Knows the fears are excessive","bucket":"protective"},{"id":"form-17-4","text":"Roommates answer ''yes it''s clean'' many times a day","bucket":"perpetuating"},{"id":"form-17-5","text":"A hepatitis outbreak at her hostel during exams","bucket":"precipitating"},{"id":"form-17-6","text":"Avoids the hostel kitchen entirely","bucket":"perpetuating"},{"id":"form-17-7","text":"She plays badminton on weekends","bucket":"distractor"},{"id":"form-17-8","text":"Supportive mother who will learn to step back","bucket":"protective"},{"id":"form-17-9","text":"Uncle with similar checking habits","bucket":"predisposing"},{"id":"form-17-10","text":"Perfectionistic and rule-bound since childhood","bucket":"predisposing"},{"id":"form-17-11","text":"Each wash brings brief relief so the urge returns stronger","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Neha, 20, presents with obsessive-compulsive disorder with contamination fears and washing and reassurance-seeking compulsions. A perfectionistic temperament and a family history of similar traits (predisposing) made her vulnerable; a hepatitis outbreak at her hostel (precipitating) gave the fears their content. Relief from washing, roommates'' reassurance and avoidance of the kitchen (perpetuating) strengthen the cycle. Good insight and a mother willing to stop accommodating (protective) make exposure and response prevention a strong option.","hint":"A pharmacy student with contamination fears","tags":{"topic":"ocd","difficulty":2,"objective":"Show how neutralising and reassurance maintain obsessions","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder, contamination type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-18', 'Dinesh: the stove, the lock, the stove again (checking OCD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-18-1","text":"Takes photos of the locked door to look at later","bucket":"perpetuating"},{"id":"form-18-2","text":"Wife does a final check for him to save time","bucket":"perpetuating"},{"id":"form-18-3","text":"Strong belief that if anything goes wrong it will be his fault","bucket":"predisposing"},{"id":"form-18-4","text":"Each check raises doubt rather than settling it","bucket":"perpetuating"},{"id":"form-18-5","text":"A small kitchen fire at a neighbour''s flat","bucket":"precipitating"},{"id":"form-18-6","text":"Arrives late daily and has received warnings at work","bucket":"presenting"},{"id":"form-18-7","text":"He commutes by scooter","bucket":"distractor"},{"id":"form-18-8","text":"Strict, punishing father","bucket":"predisposing"},{"id":"form-18-9","text":"Checks the gas, locks and taps up to 20 times before leaving","bucket":"presenting"},{"id":"form-18-10","text":"Employer willing to adjust timing during treatment","bucket":"protective"},{"id":"form-18-11","text":"Good insight and wants to stop","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Dinesh, 35, presents with obsessive-compulsive disorder with checking compulsions that make him late every day. An inflated sense of personal responsibility shaped by a punishing father (predisposing) gave fertile ground; a neighbour''s kitchen fire (precipitating) turned the fear onto gas and locks. His wife''s final checks, photos of the locked door and the way checking breeds more doubt (perpetuating) keep it going. Good insight and an accommodating employer (protective) support exposure and response prevention plus work on responsibility beliefs.","hint":"An accountant late for work every day","tags":{"topic":"ocd","difficulty":3,"objective":"Separate the inflated sense of responsibility from the rituals","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"ocd","diagnosis":"Obsessive-compulsive disorder, checking type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-19', 'Captain Rana: the convoy ambush (PTSD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-19-1","text":"Ambush on his convoy in which two of his men died","bucket":"precipitating"},{"id":"form-19-2","text":"Avoids talking or thinking about the ambush","bucket":"perpetuating"},{"id":"form-19-3","text":"Culture of ''soldiers don''t complain''","bucket":"predisposing"},{"id":"form-19-4","text":"He was posted in Leh before the ambush","bucket":"distractor"},{"id":"form-19-5","text":"Drinks six pegs nightly to sleep","bucket":"presenting"},{"id":"form-19-6","text":"Unit medical officer who referred him","bucket":"protective"},{"id":"form-19-7","text":"Alcohol blocks emotional processing and worsens sleep","bucket":"perpetuating"},{"id":"form-19-8","text":"Wife who has not given up","bucket":"protective"},{"id":"form-19-9","text":"Nightmares and flashbacks of an ambush, startle and irritability for two years","bucket":"presenting"},{"id":"form-19-10","text":"Lost his mother suddenly at 12","bucket":"predisposing"},{"id":"form-19-11","text":"Survivor guilt: believes he should have saved them","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Captain Rana, 36, presents with post-traumatic stress disorder: two years of nightmares, flashbacks, startle and irritability after an ambush, with heavy drinking to sleep. An early sudden loss and a culture of silence about distress (predisposing) shaped how he copes; the ambush and the deaths of his men (precipitating) caused the disorder. Avoidance, alcohol that blocks processing, and survivor guilt (perpetuating) keep the memory raw. A loyal wife and a referring medical officer (protective) support trauma-focused therapy, alcohol treatment and a risk plan that covers his weapon.","hint":"An army officer who drinks to sleep","tags":{"topic":"trauma","difficulty":3,"objective":"Formulate trauma symptoms with substance use and risk","exams":["md-psychiatry","mcp-entrance"],"module":"trauma","diagnosis":"Post-traumatic stress disorder with harmful alcohol use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-20', 'Pooja: the flood that took the house (adjustment disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-20-1","text":"Tends to worry when routines break","bucket":"predisposing"},{"id":"form-20-2","text":"Lost her grandparents'' home in an earlier flood as a child","bucket":"predisposing"},{"id":"form-20-3","text":"Tearfulness, worry and poor sleep since the flood","bucket":"presenting"},{"id":"form-20-4","text":"Living in her in-laws'' crowded home with little privacy","bucket":"perpetuating"},{"id":"form-20-5","text":"Struggles to concentrate on teaching","bucket":"presenting"},{"id":"form-20-6","text":"Strong local community rebuilding together","bucket":"protective"},{"id":"form-20-7","text":"Floodwater damaged her home and the family moved to a relief camp","bucket":"precipitating"},{"id":"form-20-8","text":"Her son is learning Bharatanatyam","bucket":"distractor"},{"id":"form-20-9","text":"Supportive school principal","bucket":"protective"},{"id":"form-20-10","text":"Slow insurance and compensation process","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pooja, 35, presents with an adjustment disorder with mixed anxiety and low mood after floodwater damaged her home: tearfulness, worry, poor sleep and poor concentration that exceed what she expected but do not meet criteria for a depressive episode. A tendency to worry when routines break and an earlier flood loss in childhood (predisposing) made this harder; the flood and displacement (precipitating) began it. Slow compensation and crowded living (perpetuating) prolong it. Her principal''s support and the community''s rebuilding (protective) favour practical help, problem-solving and brief supportive therapy.","hint":"A teacher three months after floods in Kerala","tags":{"topic":"trauma","difficulty":2,"objective":"Formulate distress in response to a clear stressor","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"trauma","diagnosis":"Adjustment disorder with mixed anxiety and low mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-21', 'Arvind: the heart he is sure is failing (illness anxiety)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-21-1","text":"Fixed fear that he has undiagnosed heart disease despite normal tests","bucket":"presenting"},{"id":"form-21-2","text":"Father died of a sudden heart attack at 52","bucket":"predisposing"},{"id":"form-21-3","text":"Has had 14 tests in two years","bucket":"presenting"},{"id":"form-21-4","text":"He collects old coins","bucket":"distractor"},{"id":"form-21-5","text":"Wife who wants him to stop testing","bucket":"protective"},{"id":"form-21-6","text":"Avoids exercise in case it strains his heart","bucket":"perpetuating"},{"id":"form-21-7","text":"Searches symptoms online for hours at night","bucket":"perpetuating"},{"id":"form-21-8","text":"Tendency to read bodily sensations as danger","bucket":"predisposing"},{"id":"form-21-9","text":"Each normal test calms him for only a day","bucket":"perpetuating"},{"id":"form-21-10","text":"Responds well when the cycle is drawn out","bucket":"protective"},{"id":"form-21-11","text":"A colleague of his age died of a heart attack","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arvind, 41, presents with illness anxiety disorder: a fixed fear of undiagnosed heart disease despite fourteen normal tests. His father''s sudden cardiac death and a habit of reading body sensations as danger (predisposing) made him vulnerable; a colleague''s heart attack (precipitating) set it off. Night-time online searching, short-lived reassurance from tests and avoidance of exercise (perpetuating) keep attention fixed on his heart. His wife''s support and his response to seeing the cycle (protective) suit CBT that reduces checking and reassurance and rebuilds activity.","hint":"A software lead who has had 14 cardiac tests","tags":{"topic":"somatic","difficulty":3,"objective":"Show checking and reassurance as perpetuating factors in health anxiety","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"more-disorders","diagnosis":"Illness anxiety disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-22', 'Meera: the band around the head (somatic symptom disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-22-1","text":"Pain began after her son moved abroad and her husband retired","bucket":"precipitating"},{"id":"form-22-2","text":"Long-standing difficulty putting feelings into words","bucket":"predisposing"},{"id":"form-22-3","text":"Enjoys her temple bhajan group when she goes","bucket":"protective"},{"id":"form-22-4","text":"Her house faces east","bucket":"distractor"},{"id":"form-22-5","text":"Visits doctors several times a month","bucket":"presenting"},{"id":"form-22-6","text":"Grew up in a home where only physical illness earned care","bucket":"predisposing"},{"id":"form-22-7","text":"Family attention increases when pain is worse","bucket":"perpetuating"},{"id":"form-22-8","text":"A daughter-in-law she trusts","bucket":"protective"},{"id":"form-22-9","text":"Rests in bed most afternoons, so fitness falls","bucket":"perpetuating"},{"id":"form-22-10","text":"Daily headaches and body pain for four years with excessive worry about them","bucket":"presenting"},{"id":"form-22-11","text":"Repeated tests and painkiller injections that bring short relief","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Meera, 56, presents with somatic symptom disorder: four years of daily headaches and body pain with heavy worry and frequent doctor visits. A childhood where only physical illness earned care and difficulty naming feelings (predisposing) shaped a bodily way of expressing distress; pain began as her son left and her husband retired (precipitating). Repeated tests and injections, daytime resting and extra family attention when pain rises (perpetuating) keep it going. A trusted daughter-in-law and her bhajan group (protective) can support a plan built on one regular doctor, graded activity and gentle work on emotions.","hint":"A homemaker with years of headaches and many doctors","tags":{"topic":"somatic","difficulty":4,"objective":"Formulate persistent somatic symptoms without dismissing them","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Somatic symptom disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-23', 'Kiran: the legs that stopped after the wedding news (functional weakness)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-23-1","text":"Previous episode of losing her voice at 15 during exams","bucket":"predisposing"},{"id":"form-23-2","text":"Little say in family decisions","bucket":"predisposing"},{"id":"form-23-3","text":"She was born in the month of Shravan","bucket":"distractor"},{"id":"form-23-4","text":"Wheelchair use and bed rest leading to deconditioning","bucket":"perpetuating"},{"id":"form-23-5","text":"Told her marriage had been fixed to a man she has not met","bucket":"precipitating"},{"id":"form-23-6","text":"Motivated to return to her nursing course","bucket":"protective"},{"id":"form-23-7","text":"Sudden weakness of both legs for three weeks, unable to walk","bucket":"presenting"},{"id":"form-23-8","text":"A cousin she confides in","bucket":"protective"},{"id":"form-23-9","text":"Normal scans, nerve tests and positive Hoover''s sign","bucket":"presenting"},{"id":"form-23-10","text":"Fear that walking again means the wedding goes ahead","bucket":"perpetuating"},{"id":"form-23-11","text":"Family believe it is a curse and await a ritual cure","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kiran, 20, presents with functional neurological symptom disorder: three weeks of leg weakness with normal investigations and positive signs of functional weakness. A previous functional voice loss and having little voice in family decisions (predisposing) suggest a vulnerability to expressing overwhelming conflict through the body; news of an arranged marriage she did not choose (precipitating) came just before onset. Wheelchair use, family belief in a curse and her fear that recovery means the wedding (perpetuating) maintain it. A confiding cousin and her nursing ambitions (protective) support physiotherapy-led rehabilitation, a clear explanation of the condition and safe exploration of the marriage conflict.","hint":"A young woman who cannot walk, with normal scans","tags":{"topic":"somatic","difficulty":4,"objective":"Formulate functional neurological symptoms without blame","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Functional neurological symptom disorder (functional weakness)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-24', 'Shalini: ''I am too fat'' at 38 kg (anorexia nervosa)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-24-1","text":"Starvation narrows her thinking to food and weight","bucket":"perpetuating"},{"id":"form-24-2","text":"Close relationship with her father","bucket":"protective"},{"id":"form-24-3","text":"Intense fear of gaining weight; periods stopped","bucket":"presenting"},{"id":"form-24-4","text":"Praise from friends for ''looking fit''","bucket":"perpetuating"},{"id":"form-24-5","text":"Over-exercises two hours daily","bucket":"perpetuating"},{"id":"form-24-6","text":"Perfectionism and high achievement at school","bucket":"predisposing"},{"id":"form-24-7","text":"Wants to keep dancing, which needs strength","bucket":"protective"},{"id":"form-24-8","text":"Dance teacher said she needed to be ''lighter'' for a competition","bucket":"precipitating"},{"id":"form-24-9","text":"Her school has a new principal","bucket":"distractor"},{"id":"form-24-10","text":"Weight 38 kg (BMI about 15) after losing 12 kg in a year","bucket":"presenting"},{"id":"form-24-11","text":"Mother diets constantly and comments on weight","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shalini, 17, presents with anorexia nervosa, restricting type: weight loss to a BMI near 15, fear of weight gain and loss of periods. Perfectionism and a family focus on dieting (predisposing) shaped her vulnerability; a dance teacher''s comment about being lighter (precipitating) started the restriction. The effects of starvation on thinking, praise for her appearance and excessive exercise (perpetuating) maintain it. Her bond with her father and her wish to dance with strength (protective) support family-based treatment with medical monitoring for refeeding risks.","hint":"A 17-year-old dancer who has lost 12 kg","tags":{"topic":"eating","difficulty":3,"objective":"Show how starvation itself maintains an eating disorder","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"more-disorders","diagnosis":"Anorexia nervosa, restricting type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-25', 'Ritu: the midnight binges and the guilt (bulimia nervosa)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-25-1","text":"Binge eating three to four nights a week followed by vomiting","bucket":"presenting"},{"id":"form-25-2","text":"She has a pet parrot","bucket":"distractor"},{"id":"form-25-3","text":"Skips meals all day after a binge, which sets up the next binge","bucket":"perpetuating"},{"id":"form-25-4","text":"Low self-esteem tied to appearance","bucket":"predisposing"},{"id":"form-25-5","text":"Teased about weight as a child","bucket":"predisposing"},{"id":"form-25-6","text":"Vomiting makes her believe she can binge ''safely''","bucket":"perpetuating"},{"id":"form-25-7","text":"Normal weight but intense concern about shape","bucket":"presenting"},{"id":"form-25-8","text":"A sister who knows and wants to help","bucket":"protective"},{"id":"form-25-9","text":"Wishes to stop and asked for help","bucket":"protective"},{"id":"form-25-10","text":"Binges when stressed by night shifts","bucket":"perpetuating"},{"id":"form-25-11","text":"Break-up with a partner who criticised her body","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ritu, 25, presents with bulimia nervosa: frequent binges followed by vomiting, at a normal weight, with self-worth tied to shape. Childhood teasing and appearance-based self-esteem (predisposing) set the ground; a critical partner and the break-up (precipitating) intensified body concern. Daytime restriction that drives night binges, the false safety of vomiting and stress from night shifts (perpetuating) keep the cycle turning. Her sister''s support and her own wish to change (protective) favour CBT for eating disorders with regular eating as the first step, plus checks on potassium.","hint":"A call-centre worker who vomits after eating","tags":{"topic":"eating","difficulty":3,"objective":"Map the binge, purge and restrict cycle","exams":["md-psychiatry","mcp-entrance","ma-semester"],"module":"more-disorders","diagnosis":"Bulimia nervosa"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-26', 'Vinod: four hours of sleep and blaming the mattress (insomnia disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-26-1","text":"Tired and irritable at work","bucket":"presenting"},{"id":"form-26-2","text":"Mother had sleep problems","bucket":"predisposing"},{"id":"form-26-3","text":"Months of stress during a school inspection","bucket":"precipitating"},{"id":"form-26-4","text":"Checks the clock and calculates lost sleep","bucket":"perpetuating"},{"id":"form-26-5","text":"He bought a new mattress twice","bucket":"distractor"},{"id":"form-26-6","text":"Difficulty falling and staying asleep for eight months","bucket":"presenting"},{"id":"form-26-7","text":"Wife willing to change routines together","bucket":"protective"},{"id":"form-26-8","text":"Light sleeper and worrier all his life","bucket":"predisposing"},{"id":"form-26-9","text":"Naps in the afternoon and drinks tea late","bucket":"perpetuating"},{"id":"form-26-10","text":"Motivated and organised","bucket":"protective"},{"id":"form-26-11","text":"Spends nine hours in bed to ''catch up''","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vinod, 50, presents with insomnia disorder: eight months of trouble falling and staying asleep with daytime fatigue. A lifelong light-sleeping, worrying style and a family pattern of poor sleep (predisposing) left him vulnerable; inspection stress (precipitating) began it. Long hours in bed, clock-watching, afternoon naps and late tea (perpetuating) weaken his sleep drive and condition his bed for wakefulness. His organised nature and a supportive wife (protective) make CBT for insomnia, with sleep restriction and stimulus control, a good fit. The new mattresses were a reasonable guess but not a cause.","hint":"A school principal who lies awake for hours","tags":{"topic":"sleep","difficulty":2,"objective":"Show how behaviour in bed keeps insomnia going","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"more-disorders","diagnosis":"Insomnia disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-27', 'Asha: the mood that drops every month (PMDD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-27-1","text":"Tracks her cycle on an app","bucket":"protective"},{"id":"form-27-2","text":"Symptoms worsened after stopping the contraceptive pill","bucket":"precipitating"},{"id":"form-27-3","text":"High-pressure perfectionism at work","bucket":"predisposing"},{"id":"form-27-4","text":"She drives an automatic car","bucket":"distractor"},{"id":"form-27-5","text":"Schedules her heaviest work in the bad week without noticing","bucket":"perpetuating"},{"id":"form-27-6","text":"Partner who wants to understand","bucket":"protective"},{"id":"form-27-7","text":"Well in the week after periods","bucket":"presenting"},{"id":"form-27-8","text":"Arguments with her partner in the bad week leave lasting tension","bucket":"perpetuating"},{"id":"form-27-9","text":"Severe irritability, sadness and anxiety in the week before periods","bucket":"presenting"},{"id":"form-27-10","text":"Sensitivity to hormonal change; mother had similar problems","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Asha, 30, presents with premenstrual dysphoric disorder: severe irritability, sadness and anxiety in the luteal week with clear wellness after menstruation. Sensitivity to hormonal shifts with a family history and a perfectionistic style (predisposing) shaped her vulnerability; stopping the pill (precipitating) unmasked worse symptoms. Heavy workloads and arguments falling in the bad week (perpetuating) compound the distress. Her cycle tracking and a willing partner (protective) support confirmation by prospective charting and treatment options including SSRIs and planning around the cycle.","hint":"A lawyer whose worst week is the same week each cycle","tags":{"topic":"depression","difficulty":3,"objective":"Include a biological cycle in the formulation","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Premenstrual dysphoric disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-28', 'Baba Ji: grief at four weeks (normal bereavement)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-28-1","text":"Waves of yearning when he sees her things","bucket":"presenting"},{"id":"form-28-2","text":"No past mental illness","bucket":"predisposing"},{"id":"form-28-3","text":"Laughs with grandchildren at times","bucket":"protective"},{"id":"form-28-4","text":"His scooter needs servicing","bucket":"distractor"},{"id":"form-28-5","text":"Wife died after a short illness","bucket":"precipitating"},{"id":"form-28-6","text":"Married for 48 years; she managed the household","bucket":"predisposing"},{"id":"form-28-7","text":"Has not yet had to learn household tasks she did","bucket":"perpetuating"},{"id":"form-28-8","text":"Visits the temple and his brother daily","bucket":"protective"},{"id":"form-28-9","text":"Crying, poor appetite and poor sleep four weeks after his wife''s death","bucket":"presenting"},{"id":"form-28-10","text":"Avoids her room, which is still as she left it","bucket":"perpetuating"},{"id":"form-28-11","text":"Keeps self-esteem: says he was a good husband","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Baba Ji, 70, presents four weeks after his wife''s death with crying, poor sleep and poor appetite in waves of yearning linked to reminders of her: a normal grief reaction, not a mental disorder. Forty-eight years of marriage and her management of the home (predisposing) shape the size of the loss; her death after a short illness is the clear precipitant. Practical gaps and avoidance of her room (perpetuating) are expected early features. Preserved self-esteem, daily contact with his brother and the temple and moments of warmth with grandchildren (protective) all point away from depression; the plan is support, practical help and review if grief does not soften.","hint":"A 70-year-old man whose wife died last month","tags":{"topic":"grief","difficulty":4,"objective":"Use a formulation to show why this is not a disorder","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"depression","diagnosis":"Normal grief (no mental disorder)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-29', 'Shreya: the two-week highs she misses (bipolar II)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-29-1","text":"Her bakery has a blue awning","bucket":"distractor"},{"id":"form-29-2","text":"Low mood began after a slow business month","bucket":"precipitating"},{"id":"form-29-3","text":"Mother with mood swings","bucket":"predisposing"},{"id":"form-29-4","text":"Previously treated with an antidepressant alone","bucket":"perpetuating"},{"id":"form-29-5","text":"Values the highs and tries to recreate them with late nights","bucket":"perpetuating"},{"id":"form-29-6","text":"Past spells of four to seven days with high energy and little sleep","bucket":"presenting"},{"id":"form-29-7","text":"Irregular sleep from baking at night","bucket":"perpetuating"},{"id":"form-29-8","text":"Good insight into the lows","bucket":"protective"},{"id":"form-29-9","text":"Depressive episode for a month","bucket":"presenting"},{"id":"form-29-10","text":"Early adult onset of low spells","bucket":"predisposing"},{"id":"form-29-11","text":"Husband who recognises the early signs","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shreya, 31, presents with bipolar II disorder in a depressive episode; the history of several short hypomanic spells changes both the diagnosis and the treatment. A family history of mood instability and early-onset low spells (predisposing) raise her risk; a slow business month (precipitating) came before this episode. Valuing and chasing the highs, irregular night-time sleep and past antidepressant-only treatment (perpetuating) destabilise her mood. A husband who spots early signs and her insight into lows (protective) support mood-stabilising treatment, regular sleep and a relapse-signature plan.","hint":"A baker who comes only when she is low","tags":{"topic":"bipolar","difficulty":4,"objective":"Show why a missed history of highs changes the formulation","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Bipolar II disorder, current depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-30', 'Mr Rao: the lithium and the heat wave (lithium toxicity)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-30-1","text":"Coarse tremor, unsteady walking, vomiting and confusion over two days","bucket":"presenting"},{"id":"form-30-2","text":"Wife who noticed the change quickly","bucket":"protective"},{"id":"form-30-3","text":"Drinking little water in the heat","bucket":"perpetuating"},{"id":"form-30-4","text":"Chemist unaware of his lithium","bucket":"perpetuating"},{"id":"form-30-5","text":"No lithium level for over a year","bucket":"perpetuating"},{"id":"form-30-6","text":"Long-term lithium treatment","bucket":"predisposing"},{"id":"form-30-7","text":"Diarrhoea in a heat wave plus a new painkiller (ibuprofen) from the chemist","bucket":"precipitating"},{"id":"form-30-8","text":"Previously stable and engaged with care","bucket":"protective"},{"id":"form-30-9","text":"Age 66 with reduced kidney function","bucket":"predisposing"},{"id":"form-30-10","text":"He enjoys Carnatic music","bucket":"distractor"},{"id":"form-30-11","text":"Stable bipolar disorder on lithium for 20 years","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Rao, 66, presents with lithium toxicity: coarse tremor, ataxia, vomiting and confusion after two days of diarrhoea in a heat wave. Older age, reduced kidney function and long-term lithium (predisposing) narrowed his safety margin; dehydration plus a new anti-inflammatory painkiller (precipitating) raised lithium levels. Poor fluid intake, lapsed monitoring and a chemist who did not know about lithium (perpetuating) allowed it to build. An observant wife and a history of good engagement (protective) help now, and prevention needs regular levels, sick-day rules and a medicine card.","hint":"A retired clerk confused after diarrhoea and a painkiller","tags":{"topic":"bipolar","difficulty":3,"objective":"Formulate an iatrogenic emergency","exams":["md-psychiatry","mcp-entrance"],"module":"stabilisers","diagnosis":"Lithium toxicity"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-31', 'Rakesh: the voices after the hostel move (first-episode psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-31-1","text":"Eight months untreated while the family tried a temple first","bucket":"perpetuating"},{"id":"form-31-2","text":"Hears two voices commenting on his actions","bucket":"presenting"},{"id":"form-31-3","text":"Parents who came quickly when called","bucket":"protective"},{"id":"form-31-4","text":"Aunt with a long psychotic illness","bucket":"predisposing"},{"id":"form-31-5","text":"Believes professors insert thoughts into his head","bucket":"presenting"},{"id":"form-31-6","text":"Good school record before onset","bucket":"protective"},{"id":"form-31-7","text":"Shy, isolated adolescence","bucket":"predisposing"},{"id":"form-31-8","text":"Stopped eating in the mess, sleeps little","bucket":"perpetuating"},{"id":"form-31-9","text":"Believes medicine is ''for mad people''","bucket":"perpetuating"},{"id":"form-31-10","text":"His hostel room faces the football ground","bucket":"distractor"},{"id":"form-31-11","text":"Moved to a distant hostel and lost his usual supports","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rakesh, 20, presents with a first episode of schizophrenia: running-commentary voices and delusions of thought insertion after an eight-month prodrome of withdrawal and decline. A family history of psychotic illness and an isolated adolescence (predisposing) raised his vulnerability; moving far from home (precipitating) removed his supports. A long duration of untreated psychosis, poor sleep and eating, and stigma about medicine (perpetuating) worsen the outlook. Responsive parents and a good premorbid record (protective) support early intervention with medicine, family work and a return-to-study plan.","hint":"A 20-year-old who taped his laptop camera","tags":{"topic":"psychosis","difficulty":2,"objective":"Sort a first episode with prodrome into the 5 Ps","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"psychosis","diagnosis":"Schizophrenia, first episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-32', 'Shabana: back again after stopping (relapse of schizophrenia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-32-1","text":"Voices and beliefs about black magic by a neighbour have returned","bucket":"presenting"},{"id":"form-32-2","text":"Poor sleep and angry outbursts for six weeks","bucket":"presenting"},{"id":"form-32-3","text":"Brother hides tablets in her food, which destroyed trust","bucket":"perpetuating"},{"id":"form-32-4","text":"Three years of good stability when on treatment","bucket":"protective"},{"id":"form-32-5","text":"Stopped her antipsychotic two months ago","bucket":"precipitating"},{"id":"form-32-6","text":"Weight gain of 12 kg and slowness that hurt her sewing income","bucket":"perpetuating"},{"id":"form-32-7","text":"Ten-year history of schizophrenia with three admissions","bucket":"predisposing"},{"id":"form-32-8","text":"Her sewing machine is a 1990s model","bucket":"distractor"},{"id":"form-32-9","text":"Tailoring skill and pride in her work","bucket":"protective"},{"id":"form-32-10","text":"A peer told her the tablets are poison","bucket":"perpetuating"},{"id":"form-32-11","text":"Father had a similar illness","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shabana, 37, presents with a relapse of schizophrenia after stopping medicine: returning voices and persecutory beliefs about black magic. A long illness and a family history (predisposing) make relapse likely without treatment; stopping her antipsychotic (precipitating) began this episode. The side effects that cost her work, covert medication that broke trust and peer misinformation (perpetuating) all drive non-adherence. Three stable years on treatment and her pride in her craft (protective) support a plan that switches to a medicine with fewer metabolic effects, rebuilds trust openly and links treatment to her work goals.","hint":"A tailor who gained 12 kg on her tablets","tags":{"topic":"psychosis","difficulty":3,"objective":"Put side effects at the centre of a relapse formulation","exams":["mcp-entrance","md-psychiatry"],"module":"antipsychotics","diagnosis":"Schizophrenia, relapse after stopping medicine"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-33', 'Mr Bhatt: the wife and the milkman (delusional disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-33-1","text":"Onset after erectile difficulties began","bucket":"precipitating"},{"id":"form-33-2","text":"His shop sells paint and hardware","bucket":"distractor"},{"id":"form-33-3","text":"Sons who moved home to protect their mother","bucket":"protective"},{"id":"form-33-4","text":"Each ''piece of evidence'' he finds confirms the belief","bucket":"perpetuating"},{"id":"form-33-5","text":"Drinking at weekends increases interrogations","bucket":"perpetuating"},{"id":"form-33-6","text":"Shame stops him discussing his sexual health","bucket":"perpetuating"},{"id":"form-33-7","text":"Checks her phone and clothes and follows her","bucket":"presenting"},{"id":"form-33-8","text":"Works steadily and keeps his business","bucket":"protective"},{"id":"form-33-9","text":"Long-standing feelings of inadequacy","bucket":"predisposing"},{"id":"form-33-10","text":"Fixed belief that his wife is having an affair, for a year","bucket":"presenting"},{"id":"form-33-11","text":"Suspicious, sensitive personality","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Bhatt, 52, presents with delusional disorder, jealous type: a year of fixed belief in his wife''s infidelity with checking and following, and a serious risk of violence to her. A suspicious, sensitive personality and feelings of inadequacy (predisposing) shaped vulnerability; the onset of erectile difficulties (precipitating) appears to have fed the belief. Confirmation from ''evidence'', weekend drinking and shame about sexual health (perpetuating) keep it fixed. His sons'' protection and his intact working life (protective) help engagement, but the first priority is the wife''s safety plan, then treatment and support for sexual health.","hint":"A shop owner who checks his wife''s phone nightly","tags":{"topic":"psychosis","difficulty":4,"objective":"Include risk to others in a delusional disorder formulation","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Delusional disorder, jealous type"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-34', 'Mohan: the man who sits all day (negative symptoms)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-34-1","text":"Sedation from medicine adds to inactivity","bucket":"perpetuating"},{"id":"form-34-2","text":"Illness onset at 22 with two early admissions","bucket":"predisposing"},{"id":"form-34-3","text":"Gradual decline after his father''s retirement reduced outings","bucket":"precipitating"},{"id":"form-34-4","text":"The family owns a black-and-white photo album","bucket":"distractor"},{"id":"form-34-5","text":"Devoted parents","bucket":"protective"},{"id":"form-34-6","text":"Parents do everything for him out of love","bucket":"perpetuating"},{"id":"form-34-7","text":"Apathy, poverty of speech and poor self-care","bucket":"presenting"},{"id":"form-34-8","text":"No structured activity or rehabilitation in the day","bucket":"perpetuating"},{"id":"form-34-9","text":"Enjoyed kite flying and music earlier","bucket":"protective"},{"id":"form-34-10","text":"Limited education and no work history since onset","bucket":"predisposing"},{"id":"form-34-11","text":"Voices well controlled for years","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mohan, 45, presents with schizophrenia with predominant negative symptoms: apathy, poverty of speech and poor self-care, with positive symptoms controlled. Early onset and loss of education and work (predisposing) limited his skills; reduced outings after his father retired (precipitating) deepened the withdrawal. No day structure, sedation and loving over-care by parents (perpetuating) reinforce inactivity. Devoted parents and old interests in kites and music (protective) are routes into psychosocial rehabilitation, a medicine review for sedation and future-care planning.","hint":"A 45-year-old with 20 years of illness and ageing parents","tags":{"topic":"psychosis","difficulty":3,"objective":"Formulate negative symptoms and the future of care","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"psychosis","diagnosis":"Schizophrenia with predominant negative symptoms"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-35', 'Sai: the joints during exams (cannabis-induced psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-35-1","text":"A friend who brought him","bucket":"protective"},{"id":"form-35-2","text":"Poor sleep and fear","bucket":"presenting"},{"id":"form-35-3","text":"Fear of his parents finding out stops him seeking help","bucket":"perpetuating"},{"id":"form-35-4","text":"Binge of heavy cannabis and MDMA at a beach party","bucket":"precipitating"},{"id":"form-35-5","text":"He studies typography","bucket":"distractor"},{"id":"form-35-6","text":"Social anxiety eased by smoking","bucket":"predisposing"},{"id":"form-35-7","text":"Daily cannabis since 18","bucket":"predisposing"},{"id":"form-35-8","text":"Stopped cannabis himself out of fear","bucket":"protective"},{"id":"form-35-9","text":"Two weeks of believing friends film him and hearing whispers","bucket":"presenting"},{"id":"form-35-10","text":"Friends in his circle still smoke daily","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sai, 19, presents with a cannabis-induced psychotic disorder: persecutory ideas and whispering voices starting after a heavy binge. Daily cannabis use since 18 and social anxiety that smoking eased (predisposing) increased vulnerability; a beach-party binge with MDMA (precipitating) triggered it. A smoking peer group and fear of parental discovery (perpetuating) risk continued use and delay. Stopping use himself and a caring friend (protective) give an opening for treatment, a month of abstinence with reassessment, and work on social anxiety.","hint":"A design student in Goa sure his friends film him","tags":{"topic":"psychosis","difficulty":3,"objective":"Show substance use across several Ps","exams":["md-psychiatry","mcp-entrance"],"module":"substance","diagnosis":"Cannabis-induced psychotic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-36', 'Raju: the auto driver''s morning quarter (alcohol dependence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-36-1","text":"Drinks daily from morning, with tremor relieved by drinking","bucket":"presenting"},{"id":"form-36-2","text":"Daily evenings at the auto stand bar","bucket":"perpetuating"},{"id":"form-36-3","text":"Income fell when ride apps came; drinking rose","bucket":"precipitating"},{"id":"form-36-4","text":"His auto is painted green and yellow","bucket":"distractor"},{"id":"form-36-5","text":"Father drank heavily","bucket":"predisposing"},{"id":"form-36-6","text":"Saw insects on the wall when he tried to stop","bucket":"presenting"},{"id":"form-36-7","text":"Ashamed about his son''s silence, which can fuel change","bucket":"protective"},{"id":"form-36-8","text":"Believes he can stop when he wants","bucket":"perpetuating"},{"id":"form-36-9","text":"Wife still with him","bucket":"protective"},{"id":"form-36-10","text":"Drinks to stop withdrawal shakes","bucket":"perpetuating"},{"id":"form-36-11","text":"Drinking normal among his auto stand friends","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Raju, 42, presents with alcohol dependence with a history of complicated withdrawal: daily morning drinking to relieve tremor and visual disturbances when he stopped. A father who drank and a drinking peer culture (predisposing) laid the base; falling income when ride apps arrived (precipitating) increased his drinking. Drinking to avoid withdrawal, a bar at the auto stand and minimisation (perpetuating) maintain it. His wife and his shame about his son (protective) can power change, starting with medically supervised detox with thiamine.","hint":"A driver who saw insects on the wall when he stopped","tags":{"topic":"substance","difficulty":1,"objective":"Sort a clear alcohol dependence case into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"substance","diagnosis":"Alcohol dependence with complicated withdrawal"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-37', 'Gurpreet: chitta in Tarn Taran (opioid dependence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-37-1","text":"Stealing from home","bucket":"presenting"},{"id":"form-37-2","text":"Past forced rehab with chaining and beatings made him distrust treatment","bucket":"perpetuating"},{"id":"form-37-3","text":"Father drinks; little supervision as a teen","bucket":"predisposing"},{"id":"form-37-4","text":"Injecting heroin daily with tolerance and withdrawal","bucket":"presenting"},{"id":"form-37-5","text":"Shares needles with friends","bucket":"perpetuating"},{"id":"form-37-6","text":"The family farm grows wheat and paddy","bucket":"distractor"},{"id":"form-37-7","text":"Withdrawal drives daily use","bucket":"perpetuating"},{"id":"form-37-8","text":"Brother abroad who could support recovery","bucket":"protective"},{"id":"form-37-9","text":"Failed Class 12 and joined friends who used","bucket":"precipitating"},{"id":"form-37-10","text":"Mother who keeps bringing him for help","bucket":"protective"},{"id":"form-37-11","text":"Easy local availability of heroin","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Gurpreet, 24, presents with opioid dependence with injecting: tolerance, withdrawal, theft and needle sharing. High local availability and little supervision with a drinking father (predisposing) shaped the risk; failing Class 12 and joining using friends (precipitating) began it. Distrust after an abusive private rehab, needle sharing and withdrawal-driven use (perpetuating) keep him using and at risk of infection and overdose. A persistent mother and a supportive brother (protective) support opioid substitution treatment, naloxone, testing for blood-borne infections and family work.","hint":"A young man injecting heroin after a failed rehab","tags":{"topic":"substance","difficulty":2,"objective":"Include harmful treatment history in the formulation","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"substance","diagnosis":"Opioid dependence, injecting"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-38', 'Vishal: the rummy app and six loan apps (gambling disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-38-1","text":"Wife likely to support him once told","bucket":"protective"},{"id":"form-38-2","text":"A large win of 40,000 early on","bucket":"precipitating"},{"id":"form-38-3","text":"Easy loan apps that lend in minutes","bucket":"perpetuating"},{"id":"form-38-4","text":"Stable job","bucket":"protective"},{"id":"form-38-5","text":"Believes he is ''lucky with numbers''","bucket":"predisposing"},{"id":"form-38-6","text":"Secrecy from his wife increases shame and stress","bucket":"perpetuating"},{"id":"form-38-7","text":"Uncle who gambled","bucket":"predisposing"},{"id":"form-38-8","text":"Debts of six lakh hidden from his new wife","bucket":"presenting"},{"id":"form-38-9","text":"A year of online card gambling with chasing losses","bucket":"presenting"},{"id":"form-38-10","text":"He works at a branch near the railway station","bucket":"distractor"},{"id":"form-38-11","text":"Chasing losses to win it back","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Vishal, 29, presents with gambling disorder: a year of online card gambling, chasing losses, lying and six lakh of hidden debt, with suicidal thoughts when loan agents threaten him. A family history of gambling and a belief in his own luck (predisposing) set the ground; an early big win (precipitating) hooked him. Chasing losses, instant loan apps and secrecy (perpetuating) deepen the hole. A likely supportive wife and stable job (protective) support a plan of safety planning, financial controls, telling his wife with help, and CBT.","hint":"A bank cashier hiding six lakh of debt","tags":{"topic":"substance","difficulty":3,"objective":"Formulate a behavioural addiction with suicide risk","exams":["mcp-entrance","ma-semester"],"module":"substance","diagnosis":"Gambling disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-39', 'Aarav: the game squad at 10 pm (gaming disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-39-1","text":"Parents'' sudden router shutdowns lead to fights","bucket":"perpetuating"},{"id":"form-39-2","text":"His bedroom has blue walls","bucket":"distractor"},{"id":"form-39-3","text":"Both parents work long hours","bucket":"predisposing"},{"id":"form-39-4","text":"Interested in coding","bucket":"protective"},{"id":"form-39-5","text":"Plays 8 to 10 hours daily and has not attended school for a month","bucket":"presenting"},{"id":"form-39-6","text":"Shy child with few friends","bucket":"predisposing"},{"id":"form-39-7","text":"Aggressive when the internet is cut","bucket":"presenting"},{"id":"form-39-8","text":"Sleeps through mornings, so school feels impossible","bucket":"perpetuating"},{"id":"form-39-9","text":"Online squad is his only social contact","bucket":"perpetuating"},{"id":"form-39-10","text":"Responds to a counsellor who asks about the game","bucket":"protective"},{"id":"form-39-11","text":"Moved to a new school where he knows no one","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aarav, 15, presents with gaming disorder: very long daily play, school refusal for a month and aggression when access is cut. A shy temperament and long parental work hours (predisposing) left him with little offline connection; moving to a new school without friends (precipitating) pushed him online. An online squad as his only social world, reversed sleep and abrupt router shutdowns (perpetuating) maintain the pattern. Interest in coding and responsiveness to curious adults (protective) support family work, a gradual sleep and school plan and building offline friendships.","hint":"A 15-year-old who stopped going to school","tags":{"topic":"substance","difficulty":3,"objective":"Show loneliness behind a behavioural addiction","exams":["mcp-entrance","ma-semester"],"module":"child","diagnosis":"Gaming disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-40', 'Tanvi: the girl in the group chat (adolescent low mood and bullying)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-40-1","text":"Cries after checking her phone","bucket":"presenting"},{"id":"form-40-2","text":"Avoids school, where the teasing happens","bucket":"perpetuating"},{"id":"form-40-3","text":"Low mood, staying in her room and falling marks for two months","bucket":"presenting"},{"id":"form-40-4","text":"Keeps checking the group at night","bucket":"perpetuating"},{"id":"form-40-5","text":"Edited photos of her shared in a class group chat","bucket":"precipitating"},{"id":"form-40-6","text":"Parents who are concerned and willing","bucket":"protective"},{"id":"form-40-7","text":"Recent move away from her close friends","bucket":"predisposing"},{"id":"form-40-8","text":"Her school uniform is maroon","bucket":"distractor"},{"id":"form-40-9","text":"Sensitive temperament","bucket":"predisposing"},{"id":"form-40-10","text":"Trusting relationship with her class teacher","bucket":"protective"},{"id":"form-40-11","text":"Fear her parents will take her phone stops her telling them","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Tanvi, 15, presents with a mild depressive episode in the context of cyberbullying: low mood, withdrawal and falling marks. A sensitive temperament and the loss of close friends after a move (predisposing) left her isolated; edited photos shared in a class group (precipitating) began it. Night-time checking, secrecy for fear of losing her phone and school avoidance (perpetuating) keep it going. A trusted teacher and caring parents (protective) support a plan of school action against the bullying, a safety check, and supportive therapy with agreed limits on phone use.","hint":"A 15-year-old whose marks fell after online teasing","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Formulate an adolescent''s distress with school and online factors","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Depressive episode, mild, in the context of cyberbullying"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-41', 'Ishaan: the boy who won''t go to school (school refusal)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-41-1","text":"Stomach aches and crying every school morning for two months","bucket":"presenting"},{"id":"form-41-2","text":"Mother also anxious","bucket":"predisposing"},{"id":"form-41-3","text":"Each missed day makes returning harder","bucket":"perpetuating"},{"id":"form-41-4","text":"Father willing to do the school drop","bucket":"protective"},{"id":"form-41-5","text":"Likes his class teacher","bucket":"protective"},{"id":"form-41-6","text":"His favourite colour is orange","bucket":"distractor"},{"id":"form-41-7","text":"Mother was in hospital for a week with dengue","bucket":"precipitating"},{"id":"form-41-8","text":"Missed 20 days of school","bucket":"presenting"},{"id":"form-41-9","text":"Clingy, anxious temperament from toddlerhood","bucket":"predisposing"},{"id":"form-41-10","text":"Allowed to stay home when he cries, with TV and snacks","bucket":"perpetuating"},{"id":"form-41-11","text":"Mother checks on him by phone from work all day","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ishaan, 10, presents with school refusal driven by separation anxiety: morning stomach aches, crying and many missed days. An anxious, clingy temperament and an anxious mother (predisposing) set the ground; his mother''s hospital stay with dengue (precipitating) made separation feel dangerous. Comfortable days at home, mounting missed work and frequent phone checking (perpetuating) reward avoidance. A liked class teacher and a father willing to do drop-offs (protective) support a graded return plan with the school, making home days dull and coaching the mother to tolerate his distress.","hint":"A 10-year-old with stomach aches every Monday","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Show how staying home rewards avoidance","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"School refusal with separation anxiety"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-42', 'Arjun: the boy who can''t sit still in class (ADHD)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-42-1","text":"Father had similar problems as a boy","bucket":"predisposing"},{"id":"form-42-2","text":"Daily scolding and punishment lower his self-esteem","bucket":"perpetuating"},{"id":"form-42-3","text":"Screen time late at night reduces sleep","bucket":"perpetuating"},{"id":"form-42-4","text":"Very good at football and drawing","bucket":"protective"},{"id":"form-42-5","text":"Born premature at 33 weeks","bucket":"predisposing"},{"id":"form-42-6","text":"He was born in Jaipur","bucket":"distractor"},{"id":"form-42-7","text":"Falling behind in reading","bucket":"presenting"},{"id":"form-42-8","text":"Grandmother who praises him","bucket":"protective"},{"id":"form-42-9","text":"Teacher seats him at the back","bucket":"perpetuating"},{"id":"form-42-10","text":"Restless, impulsive and easily distracted at home and school since age 4","bucket":"presenting"},{"id":"form-42-11","text":"Moved to a stricter school with longer seated lessons","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Arjun, 8, presents with ADHD, combined presentation: restlessness, impulsivity and distractibility across settings since early childhood, now affecting reading. A family history and prematurity (predisposing) raise his risk; a stricter school with longer seated lessons (precipitating) made the difficulties more visible. Constant punishment, late screens that cut sleep and being seated at the back (perpetuating) worsen behaviour and self-esteem. Talent in football and drawing and a praising grandmother (protective) support parent training, school adjustments and, if needed, medicine.","hint":"An 8-year-old the teacher calls naughty","tags":{"topic":"child-adolescent","difficulty":1,"objective":"Sort a neurodevelopmental presentation into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Attention-deficit hyperactivity disorder, combined presentation"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-43', 'Riya: the girl who lines up her toys (autism)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-43-1","text":"Limited speech, little eye contact and no pretend play","bucket":"presenting"},{"id":"form-43-2","text":"Long screen time in place of interaction","bucket":"perpetuating"},{"id":"form-43-3","text":"Starting playschool made differences obvious","bucket":"precipitating"},{"id":"form-43-4","text":"The family''s flat is near a temple","bucket":"distractor"},{"id":"form-43-5","text":"Parents now motivated and informed","bucket":"protective"},{"id":"form-43-6","text":"Strong memory for numbers and songs","bucket":"protective"},{"id":"form-43-7","text":"Elder cousin with autism","bucket":"predisposing"},{"id":"form-43-8","text":"Early signs noticed from 18 months","bucket":"predisposing"},{"id":"form-43-9","text":"Grandparents fear stigma and resist assessment","bucket":"perpetuating"},{"id":"form-43-10","text":"Distress when routines change; lines up toys","bucket":"presenting"},{"id":"form-43-11","text":"Family told ''she''ll talk late, wait'' delayed help","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Riya, 4, presents with autism spectrum disorder: limited speech, reduced social reciprocity, no pretend play, rigid routines and repetitive play. A family history (predisposing) suggests genetic vulnerability; starting playschool (precipitating) made her differences clear rather than causing them. Advice to wait, long screen time and family stigma (perpetuating) have delayed early intervention. Her memory for songs and numbers and newly motivated parents (protective) support early intervention with speech and occupational therapy and parent-mediated play.","hint":"A 4-year-old with few words and strong routines","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Formulate autism with strengths and family needs","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Autism spectrum disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-44', 'Sunita: the baby and the thoughts she can''t say (postpartum depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-44-1","text":"Unwanted images of the baby being hurt that horrify her","bucket":"presenting"},{"id":"form-44-2","text":"Difficult delivery and a week of NICU care for the baby","bucket":"precipitating"},{"id":"form-44-3","text":"Avoids bathing the baby alone because of the thoughts","bucket":"perpetuating"},{"id":"form-44-4","text":"Sleeps three hours a night","bucket":"perpetuating"},{"id":"form-44-5","text":"Husband who takes leave to help","bucket":"protective"},{"id":"form-44-6","text":"Low mood, tearfulness and exhaustion for six weeks","bucket":"presenting"},{"id":"form-44-7","text":"Bonded with the baby and breastfeeding well","bucket":"protective"},{"id":"form-44-8","text":"Previous anxiety in college","bucket":"predisposing"},{"id":"form-44-9","text":"Perfectionistic standards for herself","bucket":"predisposing"},{"id":"form-44-10","text":"The hospital was in another district","bucket":"distractor"},{"id":"form-44-11","text":"Hides the thoughts for fear the baby will be taken away","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sunita, 28, presents with a postpartum depressive episode with intrusive obsessional thoughts: low mood and exhaustion with horrifying, unwanted images of harm to her baby that she avoids and hides. Past anxiety and perfectionism (predisposing) increased her vulnerability; a difficult delivery with NICU care (precipitating) began it. Avoidance, secrecy for fear of losing the baby and severe sleep loss (perpetuating) maintain both mood and thoughts. Her bond with the baby and a supportive husband (protective) are strengths; the plan explains that these thoughts are not intentions, assesses risk carefully, protects sleep and treats both conditions.","hint":"A mother eight weeks after delivery with intrusive harm thoughts","tags":{"topic":"perinatal","difficulty":4,"objective":"Separate intrusive harm thoughts from intent in a perinatal formulation","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Postpartum depressive episode with intrusive obsessional thoughts"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-45', 'Anita: certain the baby is not hers (postpartum psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-45-1","text":"Continued sleep loss with night feeds","bucket":"perpetuating"},{"id":"form-45-2","text":"Husband who called the doctor","bucket":"protective"},{"id":"form-45-3","text":"Bipolar disorder diagnosed at 24, stopped treatment before pregnancy","bucket":"predisposing"},{"id":"form-45-4","text":"Childbirth with severe sleep loss over four nights","bucket":"precipitating"},{"id":"form-45-5","text":"Rapidly changing mood, at times elated","bucket":"presenting"},{"id":"form-45-6","text":"The baby was born on a Tuesday","bucket":"distractor"},{"id":"form-45-7","text":"From day five after delivery, confused, sleepless, believes the baby was swapped","bucket":"presenting"},{"id":"form-45-8","text":"Family believe it is the evil eye and plan a ritual first","bucket":"perpetuating"},{"id":"form-45-9","text":"Obstetric team alert to the change","bucket":"protective"},{"id":"form-45-10","text":"Mother had a ''breakdown'' after childbirth","bucket":"predisposing"},{"id":"form-45-11","text":"No psychiatric plan made during pregnancy","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Anita, 30, presents with postpartum psychosis: from day five, confusion, sleeplessness, rapid mood change and a delusion that her baby was swapped. Known bipolar disorder off treatment and a mother with a similar postpartum illness (predisposing) made her very high risk; childbirth with severe sleep loss (precipitating) triggered the episode. Family belief in the evil eye with delay for a ritual, continuing sleep loss and no pregnancy plan (perpetuating) increase danger to her and the baby. A husband who acted and an alert obstetric team (protective) allow urgent admission, ideally to a mother and baby setting, with treatment and close safety for both.","hint":"A new mother sleepless and confused on day five","tags":{"topic":"perinatal","difficulty":5,"objective":"Formulate a perinatal psychiatric emergency","exams":["md-psychiatry"],"module":"psychosis","diagnosis":"Postpartum psychosis (likely bipolar spectrum)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-46', 'Mr Dsouza: the mind that started slipping (Alzheimer''s dementia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-46-1","text":"Hearing loss limits conversation","bucket":"perpetuating"},{"id":"form-46-2","text":"Untreated hearing loss and high blood pressure","bucket":"predisposing"},{"id":"form-46-3","text":"Repeats questions; struggles with bills","bucket":"presenting"},{"id":"form-46-4","text":"Two years of worsening memory for recent events; got lost on his usual walk","bucket":"presenting"},{"id":"form-46-5","text":"Social isolation since he stopped visiting the club","bucket":"perpetuating"},{"id":"form-46-6","text":"Enjoys music and his garden","bucket":"protective"},{"id":"form-46-7","text":"Family correct and argue with him, causing distress","bucket":"perpetuating"},{"id":"form-46-8","text":"He worked on the Konkan railway","bucket":"distractor"},{"id":"form-46-9","text":"Devoted daughter nearby","bucket":"protective"},{"id":"form-46-10","text":"Age 76; mother had memory problems late in life","bucket":"predisposing"},{"id":"form-46-11","text":"Decline became obvious after his wife was hospitalised and his routine broke","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Dsouza, 76, presents with mild dementia due to Alzheimer''s disease: two years of progressive recent memory loss, getting lost and difficulty with finances. Age, a family history and untreated hearing loss and blood pressure (predisposing) raise his risk; his wife''s admission broke his routine and unmasked the decline (precipitating). Isolation, hearing loss and arguments when he forgets (perpetuating) worsen function and mood. A devoted daughter and his love of music and gardening (protective) support a plan of medical review, hearing aids, routine, carer education and future planning while he has capacity.","hint":"A retired engineer lost on his usual walk","tags":{"topic":"neurocognitive","difficulty":2,"objective":"Formulate early dementia with carer factors","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"neurocognitive","diagnosis":"Mild dementia due to Alzheimer''s disease"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-47', 'Mrs Kapoor: confused since the urine infection (delirium)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-47-1","text":"Age 82 with mild memory problems","bucket":"predisposing"},{"id":"form-47-2","text":"Dehydrated; drinking little water","bucket":"perpetuating"},{"id":"form-47-3","text":"Urinary tract infection with fever","bucket":"precipitating"},{"id":"form-47-4","text":"Poor eyesight from cataracts","bucket":"predisposing"},{"id":"form-47-5","text":"Sudden confusion over two days, worse at night","bucket":"presenting"},{"id":"form-47-6","text":"Sees children in her room; drowsy by day","bucket":"presenting"},{"id":"form-47-7","text":"Her son''s flat is on the fifth floor","bucket":"distractor"},{"id":"form-47-8","text":"Moved to an unfamiliar room at her son''s flat","bucket":"perpetuating"},{"id":"form-47-9","text":"Family noticed the sudden change","bucket":"protective"},{"id":"form-47-10","text":"Good recovery after a past infection","bucket":"protective"},{"id":"form-47-11","text":"Given a sleeping tablet at night by a relative","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Kapoor, 82, presents with delirium: two days of fluctuating confusion, night-time worsening, drowsiness and visual hallucinations. Age, mild cognitive impairment and poor eyesight (predisposing) leave her brain vulnerable; a urinary infection with fever (precipitating) triggered it. A sedative tablet, dehydration and an unfamiliar room (perpetuating) prolong the confusion. A family who spotted the sudden change and her past recovery (protective) support treating the infection, stopping the sedative, fluids, glasses and a calm, familiar setting.","hint":"An 82-year-old suddenly seeing children in her room","tags":{"topic":"neurocognitive","difficulty":3,"objective":"Formulate an acute confusional state","exams":["md-psychiatry","mcp-entrance"],"module":"neurocognitive","diagnosis":"Delirium due to urinary tract infection"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-48', 'Anil: the colleague who changed after the accident (frontal head injury)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-48-1","text":"Family argue with him as if he chooses to behave badly","bucket":"perpetuating"},{"id":"form-48-2","text":"Impulsive, irritable and socially inappropriate since a bike accident","bucket":"presenting"},{"id":"form-48-3","text":"No prior psychiatric illness","bucket":"predisposing"},{"id":"form-48-4","text":"No structured rehabilitation after discharge","bucket":"perpetuating"},{"id":"form-48-5","text":"Poor planning; lost his job","bucket":"presenting"},{"id":"form-48-6","text":"Wife committed to him","bucket":"protective"},{"id":"form-48-7","text":"No helmet habit; risk-taking as a young man","bucket":"predisposing"},{"id":"form-48-8","text":"His bike was a red model","bucket":"distractor"},{"id":"form-48-9","text":"Retains good practical skills with machines","bucket":"protective"},{"id":"form-48-10","text":"Head injury with frontal contusions in a road accident a year ago","bucket":"precipitating"},{"id":"form-48-11","text":"Drinks at weekends, which worsens control","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Anil, 34, presents with personality change due to a frontal brain injury: impulsivity, irritability, social disinhibition and poor planning since a road accident. Risk-taking without a helmet (predisposing) set the stage; the frontal injury (precipitating) caused the change. Family misunderstanding of the behaviour as chosen, weekend drinking and absent rehabilitation (perpetuating) worsen it. A committed wife and preserved practical skills (protective) support neuropsychological rehabilitation, family education, alcohol abstinence and supported work.","hint":"A once-gentle man now crude and impulsive","tags":{"topic":"neurocognitive","difficulty":4,"objective":"Formulate personality change after brain injury","exams":["md-psychiatry","ugc-net","mcp-entrance"],"module":"brain","diagnosis":"Personality change due to traumatic brain injury (frontal)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-49', 'Mansi: three hours without a text (borderline personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-49-1","text":"Mood shifts within hours triggered by fear of abandonment","bucket":"presenting"},{"id":"form-49-2","text":"Self-harm brings quick relief, which reinforces it","bucket":"perpetuating"},{"id":"form-49-3","text":"Parents'' bitter divorce and an emotionally unavailable mother","bucket":"predisposing"},{"id":"form-49-4","text":"Previously labelled bipolar and given medicines that did not help","bucket":"perpetuating"},{"id":"form-49-5","text":"Keeps attending appointments","bucket":"protective"},{"id":"form-49-6","text":"Binge drinking when distressed","bucket":"perpetuating"},{"id":"form-49-7","text":"She studies at a business school","bucket":"distractor"},{"id":"form-49-8","text":"Strong academic ability","bucket":"protective"},{"id":"form-49-9","text":"Partner was late replying during a fight","bucket":"precipitating"},{"id":"form-49-10","text":"Cuts her thighs and has chronic emptiness","bucket":"presenting"},{"id":"form-49-11","text":"Sensitive, intense temperament","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mansi, 23, presents with borderline personality disorder: rapid mood shifts tied to fears of abandonment, self-harm and chronic emptiness. An invalidating early environment through her parents'' divorce and an intense temperament (predisposing) shaped her emotional sensitivity; a partner''s delayed reply in a fight (precipitating) triggered the latest crisis. Self-harm as fast relief, binge drinking and a past misdiagnosis with ineffective medicines (perpetuating) keep the pattern going. Her engagement and ability (protective) support a safety plan and a structured therapy such as dialectical behaviour therapy.","hint":"A 23-year-old whose moods swing within hours","tags":{"topic":"personality","difficulty":4,"objective":"Formulate a personality disorder with self-harm","exams":["md-psychiatry","mcp-entrance","ugc-net"],"module":"personality","diagnosis":"Borderline personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-50', 'Shalini: the friend she has never met (avoidant personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-50-1","text":"Avoids meeting her online friend, so never tests her fears","bucket":"perpetuating"},{"id":"form-50-2","text":"Reliable, skilled worker","bucket":"protective"},{"id":"form-50-3","text":"Offered a team-lead promotion, which she refused","bucket":"precipitating"},{"id":"form-50-4","text":"Shy, inhibited temperament","bucket":"predisposing"},{"id":"form-50-5","text":"Lifelong fear of rejection with avoidance of jobs and relationships","bucket":"presenting"},{"id":"form-50-6","text":"A six-year online friendship","bucket":"protective"},{"id":"form-50-7","text":"Critical father who called her useless","bucket":"predisposing"},{"id":"form-50-8","text":"She types at 90 words a minute","bucket":"distractor"},{"id":"form-50-9","text":"Wants friends but believes she is boring","bucket":"presenting"},{"id":"form-50-10","text":"Work-from-home job removes contact","bucket":"perpetuating"},{"id":"form-50-11","text":"Interprets neutral reactions as rejection","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Shalini, 32, presents with avoidant personality disorder: lifelong fear of rejection, feelings of inadequacy and avoidance of roles and relationships she wants. A critical father and an inhibited temperament (predisposing) shaped a core belief of being unlikeable; a promotion offer (precipitating) brought the pattern into focus. Isolation through home working, avoidance of testing her fears and reading neutral cues as rejection (perpetuating) maintain it. A long online friendship and her reliability at work (protective) support schema-focused or CBT work with gradual social exposure.","hint":"A transcriptionist who refused promotion","tags":{"topic":"personality","difficulty":3,"objective":"Formulate a lifelong avoidant pattern","exams":["md-psychiatry","ugc-net","mcp-entrance"],"module":"personality","diagnosis":"Avoidant personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-51', 'Zoya: twelve hours of sleep and a broken engagement (atypical depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-51-1","text":"Cancels plans when friends reply late, so she grows isolated","bucket":"perpetuating"},{"id":"form-51-2","text":"Agrees with the ''moody'' label and criticises herself","bucket":"perpetuating"},{"id":"form-51-3","text":"Close grandmother","bucket":"protective"},{"id":"form-51-4","text":"Low mood that brightens with good news, oversleeping and eating more","bucket":"presenting"},{"id":"form-51-5","text":"Similar spell after board exams","bucket":"predisposing"},{"id":"form-51-6","text":"Long-standing sensitivity to rejection","bucket":"predisposing"},{"id":"form-51-7","text":"Heavy, leaden limbs","bucket":"presenting"},{"id":"form-51-8","text":"Engagement broken by the groom''s family, who called her ''moody''","bucket":"precipitating"},{"id":"form-51-9","text":"Night-time sweet binges and long sleep worsen energy","bucket":"perpetuating"},{"id":"form-51-10","text":"Work she is good at and gets praise for","bucket":"protective"},{"id":"form-51-11","text":"She lives in a house with a courtyard","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Zoya, 24, presents with a depressive episode with atypical features: mood reactivity, oversleeping, increased appetite, leaden limbs and rejection sensitivity. Long-standing sensitivity to rejection and an earlier episode (predisposing) set the vulnerability; the broken engagement with a hurtful label (precipitating) triggered it. Withdrawal after perceived rejection, night eating and oversleeping and self-criticism (perpetuating) maintain it. Rewarding work and a close grandmother (protective) support treatment that includes activity scheduling, regular sleep and work on rejection sensitivity, with screening for bipolarity.","hint":"A writer whose mood lifts with praise then crashes","tags":{"topic":"depression","difficulty":3,"objective":"Formulate atypical features and rejection sensitivity","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Depressive episode with atypical features"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-52', 'Sanjay: the cardiologist sent him (depression after a heart attack)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-52-1","text":"Low mood, fatigue and poor sleep since a heart attack two months ago","bucket":"presenting"},{"id":"form-52-2","text":"His car is a white sedan","bucket":"distractor"},{"id":"form-52-3","text":"Smoker with diabetes","bucket":"predisposing"},{"id":"form-52-4","text":"Skips medicines on low days","bucket":"perpetuating"},{"id":"form-52-5","text":"Stopped cardiac rehabilitation sessions","bucket":"presenting"},{"id":"form-52-6","text":"Withdrawn from friends who ''treat him like an invalid''","bucket":"perpetuating"},{"id":"form-52-7","text":"Heart attack two months ago","bucket":"precipitating"},{"id":"form-52-8","text":"Wife who attends rehab with him","bucket":"protective"},{"id":"form-52-9","text":"Fear that exercise will cause another attack","bucket":"perpetuating"},{"id":"form-52-10","text":"Previous low spell after his business failed","bucket":"predisposing"},{"id":"form-52-11","text":"Grandchild born last month","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sanjay, 55, presents with a depressive episode two months after a heart attack: low mood, fatigue and poor sleep, with dropping out of cardiac rehabilitation. Vascular risk factors and an earlier depressive spell (predisposing) raised his risk; the heart attack (precipitating) triggered the episode. Fear of exercise, missed medicines and social withdrawal (perpetuating) maintain low mood and threaten his heart health. A supportive wife and a new grandchild (protective) give motivation for treatment that is safe in heart disease, return to rehab and risk-factor work.","hint":"A 55-year-old who stopped cardiac rehab","tags":{"topic":"depression","difficulty":3,"objective":"Formulate depression that worsens a medical outcome","exams":["md-psychiatry","mcp-entrance"],"module":"depression","diagnosis":"Depressive episode after myocardial infarction"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-53', 'Lalitha: ten years on the chemist''s tablet (benzodiazepine dependence)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-53-1","text":"She makes excellent rasam","bucket":"distractor"},{"id":"form-53-2","text":"Dose increased during her daughter''s wedding preparations","bucket":"precipitating"},{"id":"form-53-3","text":"Chemist supplies without prescription","bucket":"perpetuating"},{"id":"form-53-4","text":"Daughters'' scolding increases shame and secrecy","bucket":"perpetuating"},{"id":"form-53-5","text":"Willing to try a slow plan","bucket":"protective"},{"id":"form-53-6","text":"Takes three alprazolam tablets daily for ten years","bucket":"presenting"},{"id":"form-53-7","text":"Started after her mother''s death on a doctor''s prescription","bucket":"predisposing"},{"id":"form-53-8","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-53-9","text":"Anxious and shaky when she misses doses; recent night fall","bucket":"presenting"},{"id":"form-53-10","text":"Withdrawal symptoms feel like proof she needs it","bucket":"perpetuating"},{"id":"form-53-11","text":"Daughters who want her well","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Lalitha, 55, presents with benzodiazepine dependence: ten years of alprazolam with dose escalation, withdrawal on missing doses and a fall. An anxious temperament and starting the tablet in grief (predisposing) shaped the pattern; dose increases during wedding stress (precipitating) deepened dependence. Easy chemist supply, withdrawal mistaken for ''needing it'' and shame from family scolding (perpetuating) maintain it. Daughters who care and her willingness (protective) support a slow, supervised taper with psychological treatment for anxiety and fall prevention.","hint":"A homemaker who fell at night","tags":{"topic":"substance","difficulty":3,"objective":"Formulate iatrogenic dependence","exams":["md-psychiatry","mcp-entrance"],"module":"substance","diagnosis":"Benzodiazepine dependence"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-54', 'Nikhil: the antidepressant that made him fly (switch to mania)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-54-1","text":"Wife who noticed early","bucket":"protective"},{"id":"form-54-2","text":"SSRI started for depression six weeks ago","bucket":"precipitating"},{"id":"form-54-3","text":"Irritable at home","bucket":"presenting"},{"id":"form-54-4","text":"No mood stabiliser; the antidepressant continues","bucket":"perpetuating"},{"id":"form-54-5","text":"Past summer of little sleep and many projects at 24","bucket":"predisposing"},{"id":"form-54-6","text":"Values his job","bucket":"protective"},{"id":"form-54-7","text":"Praise from some staff reinforces him","bucket":"perpetuating"},{"id":"form-54-8","text":"Father with mood problems","bucket":"predisposing"},{"id":"form-54-9","text":"The school has 1,200 pupils","bucket":"distractor"},{"id":"form-54-10","text":"Lack of sleep feeds the high","bucket":"perpetuating"},{"id":"form-54-11","text":"Elated, sleeping three hours, pressured speech and spending for ten days","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Nikhil, 35, presents with a manic episode after starting an antidepressant: elation, little sleep, pressured speech and spending. A past unrecognised hypomanic summer and a family history of mood problems (predisposing) point to underlying bipolar disorder; the SSRI (precipitating) triggered the switch. Continuing the antidepressant without a mood stabiliser, praise that rewards the high and ongoing sleep loss (perpetuating) maintain it. An observant wife and his commitment to his job (protective) support urgent review, stopping the antidepressant, mood stabilisation and protecting sleep.","hint":"A vice-principal giving 40-minute assembly speeches","tags":{"topic":"bipolar","difficulty":4,"objective":"Place a missed history and medicine as the drivers of mania","exams":["md-psychiatry","mcp-entrance"],"module":"bipolar","diagnosis":"Bipolar I disorder, manic episode after antidepressant"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-55', 'Mrs Pereira: the drilling through the wall (late-onset psychosis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-55-1","text":"Significant hearing loss for years","bucket":"predisposing"},{"id":"form-55-2","text":"Never married; reserved and private","bucket":"predisposing"},{"id":"form-55-3","text":"Hears them plotting at night","bucket":"presenting"},{"id":"form-55-4","text":"Conflict with neighbours confirms her fears","bucket":"perpetuating"},{"id":"form-55-5","text":"Talks to almost no one","bucket":"perpetuating"},{"id":"form-55-6","text":"Sister''s death left her alone in the flat","bucket":"precipitating"},{"id":"form-55-7","text":"Independent and cognitively intact","bucket":"protective"},{"id":"form-55-8","text":"Church community that cares","bucket":"protective"},{"id":"form-55-9","text":"No hearing aid, so sounds are misheard","bucket":"perpetuating"},{"id":"form-55-10","text":"Belief that neighbours drill through the wall and pump gas","bucket":"presenting"},{"id":"form-55-11","text":"She keeps her flat very tidy","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Pereira, 59, presents with a very late-onset schizophrenia-like psychosis: persecutory beliefs about neighbours and voices plotting at night, with intact cognition. Long-standing hearing loss and a reserved personality (predisposing) increase risk; her sister''s death and isolation (precipitating) preceded onset. No hearing aid, social isolation and confirming conflicts with neighbours (perpetuating) maintain it. Her independence and church community (protective) support a plan of hearing assessment, social contact, a low-dose antipsychotic and practical help with the housing society.","hint":"A retired telephone operator who lives alone and cannot hear well","tags":{"topic":"psychosis","difficulty":4,"objective":"Show sensory loss and isolation as formulation factors","exams":["md-psychiatry","mcp-entrance"],"module":"psychosis","diagnosis":"Very late-onset schizophrenia-like psychosis"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-56', 'Gita: the retired principal who rests too much (late-life depression)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-56-1","text":"Stopped meeting friends, gardening and answering calls for eight months","bucket":"presenting"},{"id":"form-56-2","text":"Daughter who flew in to help","bucket":"protective"},{"id":"form-56-3","text":"Identity built around her work as a principal","bucket":"predisposing"},{"id":"form-56-4","text":"She owns a collection of cookbooks","bucket":"distractor"},{"id":"form-56-5","text":"Widowed five years ago","bucket":"predisposing"},{"id":"form-56-6","text":"Phone on silent; isolation deepens","bucket":"perpetuating"},{"id":"form-56-7","text":"A doctor called it ''age'' and gave a vitamin injection","bucket":"perpetuating"},{"id":"form-56-8","text":"Weight loss and saying she ''wouldn''t mind'' not waking","bucket":"presenting"},{"id":"form-56-9","text":"Retirement eight months ago","bucket":"precipitating"},{"id":"form-56-10","text":"Believes rest is what she has earned so does not complain","bucket":"perpetuating"},{"id":"form-56-11","text":"Old students who still visit","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Gita, 52, presents with a moderate depressive episode: eight months of withdrawal, loss of interest, weight loss and passive death wishes. An identity built on work and widowhood (predisposing) left retirement as a major loss; retirement itself (precipitating) began the slide. Her belief that she has earned rest, isolation with the phone silenced and a doctor''s dismissal as age (perpetuating) delayed help. A daughter who came and old students who visit (protective) support a plan with a risk assessment, treatment and rebuilding meaningful activity.","hint":"A widow whose daughter flew in from Chennai","tags":{"topic":"depression","difficulty":1,"objective":"Sort late-life depression after retirement into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"depression","diagnosis":"Moderate depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-57', 'Lakshmi: the fits that come at her in-laws'' house (dissociative seizures)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-57-1","text":"Normal video EEG during an episode","bucket":"presenting"},{"id":"form-57-2","text":"Learned early to stay silent about distress","bucket":"predisposing"},{"id":"form-57-3","text":"Close sister she trusts","bucket":"protective"},{"id":"form-57-4","text":"Episodes bring a break from household demands and family concern","bucket":"perpetuating"},{"id":"form-57-5","text":"Mother-in-law''s criticism continues daily","bucket":"perpetuating"},{"id":"form-57-6","text":"Sexual abuse by a relative in childhood, never disclosed","bucket":"predisposing"},{"id":"form-57-7","text":"The wedding was held in a garden venue","bucket":"distractor"},{"id":"form-57-8","text":"Repeated anticonvulsant changes signal ''epilepsy'' to everyone","bucket":"perpetuating"},{"id":"form-57-9","text":"Episodes of falling, shaking with eyes tightly shut and crying, several a week","bucket":"presenting"},{"id":"form-57-10","text":"Married eight months ago and moved to a strict joint family","bucket":"precipitating"},{"id":"form-57-11","text":"Husband who wants to understand","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Lakshmi, 22, presents with dissociative seizures: frequent episodes with closed eyes, crying and shaking, with a normal EEG during an attack. Undisclosed childhood sexual abuse and a lifelong habit of silence about distress (predisposing) shaped a tendency to dissociate under overwhelming stress; marriage into a critical joint family (precipitating) came before onset. Relief from demands during episodes, repeated anticonvulsant changes that confirm an epilepsy label and daily criticism (perpetuating) keep them going. A husband who wants to understand and a trusted sister (protective) support a clear, non-blaming explanation, tapering unneeded anticonvulsants, psychological therapy and safe exploration of past trauma.","hint":"A young bride whose ''fits'' have normal EEGs","tags":{"topic":"somatic","difficulty":4,"objective":"Formulate dissociative seizures with family conflict","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Dissociative (functional) seizures"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-58', 'Deepak: the gap in Tuesday (dissociative amnesia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-58-1","text":"He drives a company car","bucket":"distractor"},{"id":"form-58-2","text":"Childhood with a violent father; ''switched off'' during beatings","bucket":"predisposing"},{"id":"form-58-3","text":"Knows who he is but cannot recall the trip","bucket":"presenting"},{"id":"form-58-4","text":"Fear of police makes him reluctant to recall","bucket":"perpetuating"},{"id":"form-58-5","text":"Company accused him of fraud a day before he vanished","bucket":"precipitating"},{"id":"form-58-6","text":"Avoids any discussion of the accusation","bucket":"perpetuating"},{"id":"form-58-7","text":"Avoidant coping style","bucket":"predisposing"},{"id":"form-58-8","text":"Family pressure to ''just remember''","bucket":"perpetuating"},{"id":"form-58-9","text":"Normal brain scan and no alcohol or drugs","bucket":"protective"},{"id":"form-58-10","text":"Wife who stands by him","bucket":"protective"},{"id":"form-58-11","text":"Found in Nagpur with no memory of travelling from Pune two days earlier","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Deepak, 38, presents with dissociative amnesia with fugue: purposeful travel to another city with a two-day memory gap and no organic cause found. A childhood of violence where he learned to switch off (predisposing) shaped a dissociative response to unbearable stress; a fraud accusation the day before (precipitating) triggered it. Avoidance of the accusation, fear of legal consequences and family pressure to remember (perpetuating) keep the gap closed. A normal medical work-up and a supportive wife (protective) allow a safe, unhurried therapy that addresses the stressor first and does not force recall.","hint":"A sales executive found in another city with no memory of the trip","tags":{"topic":"trauma","difficulty":5,"objective":"Formulate dissociative amnesia and rule out organic causes","exams":["md-psychiatry","ugc-net"],"module":"trauma","diagnosis":"Dissociative amnesia with dissociative fugue"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-59', 'Rahul: the white discharge and the weakness (dhat syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-59-1","text":"Avoids talking to anyone about it from shame","bucket":"perpetuating"},{"id":"form-59-2","text":"Guilt about masturbation from his teens","bucket":"predisposing"},{"id":"form-59-3","text":"Checks his urine every morning","bucket":"perpetuating"},{"id":"form-59-4","text":"Spends money on costly herbal tonics","bucket":"perpetuating"},{"id":"form-59-5","text":"Low mood, fatigue and poor concentration","bucket":"presenting"},{"id":"form-59-6","text":"Worry that he loses semen in urine, causing weakness and poor memory","bucket":"presenting"},{"id":"form-59-7","text":"Close friend who encouraged him","bucket":"protective"},{"id":"form-59-8","text":"Came to a general doctor on his own","bucket":"protective"},{"id":"form-59-9","text":"A roadside ''sex clinic'' told him his weakness came from semen loss","bucket":"precipitating"},{"id":"form-59-10","text":"Cultural belief that semen is vital strength","bucket":"predisposing"},{"id":"form-59-11","text":"He is studying for a B.Com degree","bucket":"distractor"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rahul, 22, presents with dhat syndrome: distress about supposed loss of semen in urine, attributed weakness and poor memory, with low mood and anxiety. Cultural beliefs about semen as vital strength and guilt about masturbation (predisposing) made the worry likely; a roadside clinic''s frightening explanation (precipitating) intensified it. Costly tonics, daily urine checking and secrecy (perpetuating) maintain it. His own help-seeking and a supportive friend (protective) allow respectful sex education, correction of myths without ridicule, and treatment of the anxiety and low mood.","hint":"A 22-year-old certain he is losing vital fluid","tags":{"topic":"culture","difficulty":3,"objective":"Formulate a culture-bound distress with depression and anxiety","exams":["mcp-entrance","md-psychiatry","ma-semester"],"module":"more-disorders","diagnosis":"Dhat syndrome with anxiety and low mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-60', 'Pradeep: performance worry after one bad night (erectile difficulty)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-60-1","text":"Bought online pills without seeing a doctor","bucket":"perpetuating"},{"id":"form-60-2","text":"Little sex education; learned from pornography","bucket":"predisposing"},{"id":"form-60-3","text":"Normal physical health","bucket":"protective"},{"id":"form-60-4","text":"Avoids intimacy, which worries his wife","bucket":"perpetuating"},{"id":"form-60-5","text":"Watches himself anxiously during sex (spectatoring)","bucket":"perpetuating"},{"id":"form-60-6","text":"Loses his erection during intercourse for three months","bucket":"presenting"},{"id":"form-60-7","text":"Wife who is patient and willing to join sessions","bucket":"protective"},{"id":"form-60-8","text":"Failed on the first night after the wedding when both were exhausted","bucket":"precipitating"},{"id":"form-60-9","text":"Their wedding had 900 guests","bucket":"distractor"},{"id":"form-60-10","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-60-11","text":"Normal morning erections","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Pradeep, 29, presents with psychogenic erectile disorder: three months of losing erections during intercourse with normal morning erections. An anxious temperament and poor sex education with unrealistic expectations (predisposing) set the ground; a failure on the exhausting wedding night (precipitating) began the worry. Anxious self-monitoring, unsupervised online pills and avoidance of intimacy (perpetuating) maintain the cycle. A patient wife and good physical health (protective) support couple-based sex therapy with sensate focus and accurate education.","hint":"A newly married man afraid of failing again","tags":{"topic":"sexual","difficulty":2,"objective":"Show performance anxiety as a maintaining cycle","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"more-disorders","diagnosis":"Erectile disorder, psychogenic, situational"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-61', 'Kunal: stuck between two hearts (hoarding disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-61-1","text":"Flat filled with newspapers, bags and broken items so rooms cannot be used","bucket":"presenting"},{"id":"form-61-2","text":"Feels each object holds memories of his wife","bucket":"perpetuating"},{"id":"form-61-3","text":"Son who visits weekly","bucket":"protective"},{"id":"form-61-4","text":"Clutter worsened after his wife died and nobody else cleared things","bucket":"precipitating"},{"id":"form-61-5","text":"Indecisive and perfectionistic","bucket":"predisposing"},{"id":"form-61-6","text":"Believes items may be needed one day","bucket":"perpetuating"},{"id":"form-61-7","text":"His building is forty years old","bucket":"distractor"},{"id":"form-61-8","text":"Neighbours'' complaints make him defensive and secretive","bucket":"perpetuating"},{"id":"form-61-9","text":"Severe distress at the thought of discarding","bucket":"presenting"},{"id":"form-61-10","text":"Agrees the clutter is a fire risk","bucket":"protective"},{"id":"form-61-11","text":"Grew up in poverty where nothing was wasted","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Kunal, 67, presents with hoarding disorder: a flat so full that rooms cannot be used and great distress about discarding. A childhood of poverty and an indecisive, perfectionistic style (predisposing) shaped strong beliefs about waste; his wife''s death (precipitating) removed the person who cleared things and gave objects new emotional weight. Beliefs about future need, attachment of memories to objects and defensiveness after complaints (perpetuating) maintain it. A visiting son and his recognition of fire risk (protective) support CBT for hoarding with practice in sorting and discarding at his pace, and a safety plan.","hint":"A retired clerk whose flat is full to the ceiling","tags":{"topic":"ocd","difficulty":3,"objective":"Formulate hoarding with its beliefs and family conflict","exams":["md-psychiatry","mcp-entrance"],"module":"ocd","diagnosis":"Hoarding disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-62', 'Aisha: the nose she can''t stop checking (body dysmorphic disorder)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-62-1","text":"Doing well academically when she attends","bucket":"protective"},{"id":"form-62-2","text":"Preoccupied for hours daily with a perceived crooked nose that others cannot see","bucket":"presenting"},{"id":"form-62-3","text":"Mother who notices her distress","bucket":"protective"},{"id":"form-62-4","text":"Avoids college on ''bad face'' days","bucket":"perpetuating"},{"id":"form-62-5","text":"Checks mirrors, takes many selfies, avoids photos","bucket":"presenting"},{"id":"form-62-6","text":"A relative commented on her nose at a wedding","bucket":"precipitating"},{"id":"form-62-7","text":"She studies architecture","bucket":"distractor"},{"id":"form-62-8","text":"Teased about her looks in school","bucket":"predisposing"},{"id":"form-62-9","text":"First rhinoplasty did not relieve the worry and she now wants another","bucket":"perpetuating"},{"id":"form-62-10","text":"Hours of mirror checking and photo filtering","bucket":"perpetuating"},{"id":"form-62-11","text":"Perfectionism and low self-worth","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aisha, 21, presents with body dysmorphic disorder: hours of preoccupation with a perceived nasal flaw invisible to others, mirror checking and avoidance. Childhood teasing and perfectionism with low self-worth (predisposing) set the ground; a relative''s remark (precipitating) focused the concern. An unhelpful first rhinoplasty that now drives a wish for more surgery, checking and filtering, and avoidance (perpetuating) keep it going. A concerned mother and academic strength (protective) support CBT for body dysmorphic disorder and an SSRI, with advice against further cosmetic procedures until treated.","hint":"A student who wants a second rhinoplasty","tags":{"topic":"ocd","difficulty":4,"objective":"Formulate body dysmorphic disorder and the cosmetic-surgery trap","exams":["md-psychiatry","mcp-entrance"],"module":"ocd","diagnosis":"Body dysmorphic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-63', 'Priya: the bald patch under her dupatta (trichotillomania)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-63-1","text":"Anxious temperament","bucket":"predisposing"},{"id":"form-63-2","text":"Shame stops her telling anyone","bucket":"perpetuating"},{"id":"form-63-3","text":"She takes the school bus","bucket":"distractor"},{"id":"form-63-4","text":"Tries to stop but cannot","bucket":"presenting"},{"id":"form-63-5","text":"Happens automatically while reading alone","bucket":"perpetuating"},{"id":"form-63-6","text":"Close friend she can tell","bucket":"protective"},{"id":"form-63-7","text":"Began during board exam preparation","bucket":"precipitating"},{"id":"form-63-8","text":"Wants to stop and accepted help","bucket":"protective"},{"id":"form-63-9","text":"Pulling relieves tension for a moment","bucket":"perpetuating"},{"id":"form-63-10","text":"Aunt who picked her skin","bucket":"predisposing"},{"id":"form-63-11","text":"Pulls hair from her scalp, leaving a bald patch she hides","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Priya, 16, presents with trichotillomania: repeated hair pulling causing a hidden bald patch and failed attempts to stop. An anxious temperament and a family history of skin picking (predisposing) increase risk; board-exam stress (precipitating) began it. Brief tension relief, automatic pulling during solitary reading and shame-driven secrecy (perpetuating) keep it going. Her motivation and a trusted friend (protective) support habit-reversal training with awareness, a competing response and stimulus control while studying.","hint":"A 16-year-old who pulls her hair while studying","tags":{"topic":"ocd","difficulty":2,"objective":"Show tension relief and cues in a body-focused repetitive behaviour","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"ocd","diagnosis":"Trichotillomania (hair-pulling disorder)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-64', 'Mrs Joseph: the old fear of birds (specific phobia)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-64-1","text":"She teaches mathematics","bucket":"distractor"},{"id":"form-64-2","text":"Anxious child","bucket":"predisposing"},{"id":"form-64-3","text":"Understanding principal","bucket":"protective"},{"id":"form-64-4","text":"Checks windows before entering rooms","bucket":"perpetuating"},{"id":"form-64-5","text":"Colleagues cover her courtyard duty","bucket":"perpetuating"},{"id":"form-64-6","text":"Mother also feared birds","bucket":"predisposing"},{"id":"form-64-7","text":"Motivated because of a new school timetable","bucket":"protective"},{"id":"form-64-8","text":"Intense fear of pigeons and crows, panics if one comes near","bucket":"presenting"},{"id":"form-64-9","text":"Avoids all places with birds","bucket":"perpetuating"},{"id":"form-64-10","text":"A crow swooped at her head when she was seven","bucket":"precipitating"},{"id":"form-64-11","text":"Avoids the school courtyard and open markets","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Joseph, 44, presents with a specific phobia of birds: intense fear and panic near pigeons and crows with avoidance of courtyards and markets. A fearful mother and an anxious temperament (predisposing) made her vulnerable; a crow swooping at her in childhood (precipitating) set the fear. Complete avoidance, colleagues covering for her and window checking (perpetuating) keep the fear untested. A new timetable that requires courtyard duty and an understanding principal (protective) support graded exposure therapy.","hint":"A teacher who will not go to the school courtyard","tags":{"topic":"anxiety","difficulty":1,"objective":"Sort a simple phobia into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"anxiety","diagnosis":"Specific phobia, animal type (birds)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-65', 'Rehan: the boy who won''t talk at school (selective mutism)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-65-1","text":"Started a large English-medium school where he knew no one","bucket":"precipitating"},{"id":"form-65-2","text":"Engaged parents","bucket":"protective"},{"id":"form-65-3","text":"His school bag is red","bucket":"distractor"},{"id":"form-65-4","text":"Teacher and classmates answer for him","bucket":"perpetuating"},{"id":"form-65-5","text":"Speaks to one classmate on the phone","bucket":"protective"},{"id":"form-65-6","text":"Parents excuse him as ''just shy''","bucket":"perpetuating"},{"id":"form-65-7","text":"Not expected to speak, so never practises","bucket":"perpetuating"},{"id":"form-65-8","text":"Mother with social anxiety","bucket":"predisposing"},{"id":"form-65-9","text":"Speaks freely at home but not at all at school for a year","bucket":"presenting"},{"id":"form-65-10","text":"Nods and points instead","bucket":"presenting"},{"id":"form-65-11","text":"Shy, behaviourally inhibited temperament","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Rehan, 6, presents with selective mutism: fluent speech at home but none at school for a year. A behaviourally inhibited temperament and a socially anxious mother (predisposing) increase risk; starting a large, unfamiliar English-medium school (precipitating) began it. Others speaking for him, low expectations and excusing it as shyness (perpetuating) remove chances to practise. Speaking to one classmate by phone and engaged parents (protective) support a graded plan that slowly brings speech into school through small steps.","hint":"A 6-year-old chatty at home, silent in class","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Show how others speaking for a child maintains mutism","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Selective mutism"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-66', 'Varun: the boy who breaks things (conduct problems)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-66-1","text":"Father left home; family moved to a rented room","bucket":"precipitating"},{"id":"form-66-2","text":"School exclusion increases time with the older boys","bucket":"perpetuating"},{"id":"form-66-3","text":"Suspended from school twice","bucket":"presenting"},{"id":"form-66-4","text":"Joined older boys who steal phones","bucket":"perpetuating"},{"id":"form-66-5","text":"He was born in the monsoon","bucket":"distractor"},{"id":"form-66-6","text":"Witnessed his father hit his mother for years","bucket":"predisposing"},{"id":"form-66-7","text":"Mother wants help and will attend","bucket":"protective"},{"id":"form-66-8","text":"Harsh, inconsistent discipline from an exhausted mother","bucket":"perpetuating"},{"id":"form-66-9","text":"Fights, theft from shops and truancy for a year","bucket":"presenting"},{"id":"form-66-10","text":"Good at cricket and loves the coach","bucket":"protective"},{"id":"form-66-11","text":"Undiagnosed reading difficulty","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Varun, 13, presents with adolescent-onset conduct disorder: fighting, theft and truancy with school suspensions. Exposure to domestic violence and an undiagnosed reading difficulty (predisposing) shaped anger and school failure; his father leaving and the family''s move (precipitating) began the slide. Antisocial peers, harsh inconsistent discipline and school exclusion (perpetuating) maintain it. A cricket coach he admires and a mother who wants help (protective) support parent training, a reading assessment, a school plan and structured sport.","hint":"A 13-year-old suspended for fighting","tags":{"topic":"child-adolescent","difficulty":3,"objective":"Formulate conduct problems with home and peer factors","exams":["mcp-entrance","ma-semester"],"module":"child","diagnosis":"Conduct disorder, adolescent onset"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-67', 'Ayaan: the blinks and the throat noises (Tourette syndrome)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-67-1","text":"Father had tics as a boy","bucket":"predisposing"},{"id":"form-67-2","text":"Also restless and inattentive","bucket":"predisposing"},{"id":"form-67-3","text":"Eye blinking, head jerks and throat-clearing noises for over a year","bucket":"presenting"},{"id":"form-67-4","text":"Excellent at chess","bucket":"protective"},{"id":"form-67-5","text":"Teacher willing to educate the class","bucket":"protective"},{"id":"form-67-6","text":"Teasing increases stress","bucket":"perpetuating"},{"id":"form-67-7","text":"Holds tics in at school then releases them at home","bucket":"perpetuating"},{"id":"form-67-8","text":"Teased at school","bucket":"presenting"},{"id":"form-67-9","text":"He likes mango ice cream","bucket":"distractor"},{"id":"form-67-10","text":"Parents tell him to stop, which raises tension and tics","bucket":"perpetuating"},{"id":"form-67-11","text":"Tics worsened when he started a new class","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ayaan, 10, presents with Tourette syndrome: multiple motor tics and a vocal tic for over a year, with teasing. A family history and coexisting attention difficulties (predisposing) fit the usual pattern; starting a new class (precipitating) worsened them. Being told to stop, teasing and suppressing tics then releasing them at home (perpetuating) increase tension and frequency. Chess talent and a willing teacher (protective) support education for family and class, behavioural therapy for tics and assessment of attention.","hint":"A 10-year-old teased for his tics","tags":{"topic":"child-adolescent","difficulty":2,"objective":"Formulate tics with stress and attention factors","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Tourette syndrome"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-68', 'Sneha: wet beds at nine (enuresis)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-68-1","text":"She has a younger brother","bucket":"distractor"},{"id":"form-68-2","text":"Drinks large amounts in the evening","bucket":"perpetuating"},{"id":"form-68-3","text":"Wears nappies at night, so no motivation to wake","bucket":"perpetuating"},{"id":"form-68-4","text":"Wets the bed most nights at age nine","bucket":"presenting"},{"id":"form-68-5","text":"Scolding and shaming by grandmother","bucket":"perpetuating"},{"id":"form-68-6","text":"Father wet the bed until age ten","bucket":"predisposing"},{"id":"form-68-7","text":"Parents willing to try an alarm","bucket":"protective"},{"id":"form-68-8","text":"No new trigger; always wet; noticed more after a school trip was announced","bucket":"precipitating"},{"id":"form-68-9","text":"Deep sleeper","bucket":"predisposing"},{"id":"form-68-10","text":"Keen to go on the trip","bucket":"protective"},{"id":"form-68-11","text":"Refuses sleepovers and school trips","bucket":"presenting"}]'::jsonb, '[]'::jsonb, '{"narrative":"Sneha, 9, presents with primary nocturnal enuresis: wetting most nights, now causing her to avoid trips. A family history and deep sleep (predisposing) are typical; there is no new trigger, but an upcoming trip made it urgent. Shaming, heavy evening drinking and night nappies (perpetuating) keep the pattern. Her wish to join the trip and willing parents (protective) support a bed-wetting alarm, fluid timing, a reward chart and an end to shaming, with medicine as a short-term option.","hint":"A girl who refuses school trips","tags":{"topic":"child-adolescent","difficulty":1,"objective":"Sort a common childhood problem into the 5 Ps","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Nocturnal enuresis (primary)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-69', 'Mr Sinha: the driven boss who can''t delegate (obsessive-compulsive personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-69-1","text":"Works late, so has no time for family","bucket":"perpetuating"},{"id":"form-69-2","text":"Strict father who punished mistakes","bucket":"predisposing"},{"id":"form-69-3","text":"He works in the textile export sector","bucket":"distractor"},{"id":"form-69-4","text":"Highly competent and honest","bucket":"protective"},{"id":"form-69-5","text":"Lifelong perfectionism, rigid rules and inability to delegate","bucket":"presenting"},{"id":"form-69-6","text":"Three team members resigned this year; marriage strained","bucket":"presenting"},{"id":"form-69-7","text":"Promoted to manage a team of twelve","bucket":"precipitating"},{"id":"form-69-8","text":"Sees his standards as correct, not a problem","bucket":"perpetuating"},{"id":"form-69-9","text":"Rewarded at school only for perfect marks","bucket":"predisposing"},{"id":"form-69-10","text":"Believes others'' work is never good enough so redoes it","bucket":"perpetuating"},{"id":"form-69-11","text":"Wife who still wants the marriage to work","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Sinha, 47, presents with obsessive-compulsive personality disorder: a lifelong, ego-syntonic pattern of perfectionism, rigidity and need for control, now harming his team and marriage. Unlike OCD, there are no intrusive unwanted thoughts or rituals; he sees his standards as right. A punishing father and reward only for perfection (predisposing) shaped the pattern; promotion to a large team (precipitating) exposed its cost. Redoing others'' work, overwork and lack of insight (perpetuating) maintain it. His competence, honesty and committed wife (protective) support therapy focused on flexibility and values.","hint":"A manager whose team keeps resigning","tags":{"topic":"personality","difficulty":4,"objective":"Tell a rigid personality pattern from OCD in a formulation","exams":["md-psychiatry","ugc-net","mcp-entrance"],"module":"personality","diagnosis":"Obsessive-compulsive personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-70', 'Ravi: charming, and always in trouble (antisocial personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-70-1","text":"He supports a football club","bucket":"distractor"},{"id":"form-70-2","text":"Peer group involved in crime","bucket":"perpetuating"},{"id":"form-70-3","text":"Assault after drinking at a bar","bucket":"precipitating"},{"id":"form-70-4","text":"Court-referred after an assault","bucket":"presenting"},{"id":"form-70-5","text":"Repeated fights, cheating and lying since his teens, with little remorse","bucket":"presenting"},{"id":"form-70-6","text":"Blames others and denies responsibility","bucket":"perpetuating"},{"id":"form-70-7","text":"Grew up with neglect and a father in prison","bucket":"predisposing"},{"id":"form-70-8","text":"Heavy alcohol use","bucket":"perpetuating"},{"id":"form-70-9","text":"Conduct problems from age 11","bucket":"predisposing"},{"id":"form-70-10","text":"Holds a driving licence and some work skills","bucket":"protective"},{"id":"form-70-11","text":"Loves his young daughter","bucket":"protective"}]'::jsonb, '[]'::jsonb, '{"narrative":"Ravi, 30, presents with antisocial personality disorder with alcohol misuse: a pattern since adolescence of violence, deceit and lack of remorse, now with a court referral after assault. Childhood conduct disorder, neglect and parental criminality (predisposing) laid the foundation; drinking at a bar (precipitating) preceded the assault. Heavy alcohol use, a criminal peer group and externalising blame (perpetuating) maintain risk. Love for his daughter and work skills (protective) are levers, but the plan centres on violence risk assessment, alcohol treatment and structured, realistic goals rather than expecting quick change.","hint":"A 30-year-old referred by a court after assault","tags":{"topic":"personality","difficulty":5,"objective":"Formulate antisocial personality with risk and comorbidity","exams":["md-psychiatry","ugc-net"],"module":"personality","diagnosis":"Antisocial personality disorder with alcohol misuse"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-71', 'Mr Kohli: everyone is against him (paranoid personality)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-71-1","text":"Humiliated by seniors early in service","bucket":"predisposing"},{"id":"form-71-2","text":"Lifelong suspicion that others exploit or deceive him","bucket":"presenting"},{"id":"form-71-3","text":"Holds grudges and has filed three lawsuits against neighbours","bucket":"presenting"},{"id":"form-71-4","text":"Isolates, so no one corrects his views","bucket":"perpetuating"},{"id":"form-71-5","text":"Still reasonable when facts are put to him directly","bucket":"protective"},{"id":"form-71-6","text":"Retired and lost his status and routine","bucket":"precipitating"},{"id":"form-71-7","text":"Reads hidden insults in neutral remarks","bucket":"perpetuating"},{"id":"form-71-8","text":"Grew up in a hostile, competitive family","bucket":"predisposing"},{"id":"form-71-9","text":"He keeps a tidy rose garden","bucket":"distractor"},{"id":"form-71-10","text":"Wife who is loyal and calm","bucket":"protective"},{"id":"form-71-11","text":"Each conflict confirms that people cannot be trusted","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Kohli, 64, presents with paranoid personality disorder: a lifelong pattern of suspicion, grudges and litigation, without fixed false beliefs of delusional intensity. A hostile family and humiliation early in service (predisposing) shaped distrust; retirement and lost status (precipitating) brought conflict to the fore. Misreading neutral remarks, isolation and conflicts that seem to prove his view (perpetuating) maintain it. A loyal wife and his ability to consider facts (protective) support a respectful, transparent therapeutic style and screening for depression.","hint":"A retired officer suing his neighbours for the third time","tags":{"topic":"personality","difficulty":4,"objective":"Separate a paranoid personality pattern from delusional disorder","exams":["md-psychiatry","ugc-net"],"module":"personality","diagnosis":"Paranoid personality disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
